import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-f-001","clusterId":"F","werkstueckRef":"F.0","stufe":1,"question":"Ein Forschungsteam testet eine kühne, noch unbewiesene Hypothese. Der entscheidende Versuch fällt negativ aus. Woran erkennst du, dass das Team trotz der gewagten Idee ehrlich wissenschaftlich arbeitet und nicht nur den Anschein davon erzeugt?","options":["Es beschreibt den negativen Versuch in sorgfältiger Fachsprache mit Formeln, Messwerten und Fachbegriffen.","Es besteht aus Fachleuten anerkannter Universitäten, die akademische Titel tragen und den Versuch betreuten.","Es erkennt das Scheitern des entscheidenden Tests an und passt die Hypothese an oder gibt sie ganz auf.","Es hält trotz des negativen Tests an der kühnen Hypothese fest, denn große Entdeckungen standen oft gegen die Lehrmeinung."],"correctIndex":2,"explanation":"Eine kühne Hypothese ist noch kein Warnsignal: Spekulation ist legitim, solange sie prüfbar bleibt. Entscheidend ist der Umgang mit dem Scheitern: In ehrlicher Forschung an der Grenze des Wissens wird ein gescheiterter Test anerkannt und führt dazu, dass die Hypothese angepasst oder aufgegeben wird. In der Pseudowissenschaft werden widersprechende Befunde dagegen oft ignoriert, wegerklärt oder umgedeutet. Wer ein negatives Ergebnis ernst nimmt, zeigt, dass die Idee an der Wirklichkeit scheitern kann, und genau das unterscheidet ehrliche Forschung von bloßer Imitation. Die anderen Merkmale klingen nach Wissenschaft, lassen sich aber nachahmen: Fachsprache, Formeln und Messwerte sagen nichts darüber, ob ein Team eine Widerlegung akzeptiert. Titel und Universitäten schützen nicht vor Selbsttäuschung. Und am kühnen Festhalten trotz Scheiterns zeigt sich keine Ehrlichkeit, denn Kühnheit allein belegt nichts.","coreRule":"⚡ Eine Idee darf kühn sein und scheitern; verdächtig wird sie, wenn jedes Scheitern wegerklärt wird.","beleg":"Werkstück F.0 (Kontext & Tiefe, Abschnitte II und III)","status":"entwurf","kurz":"Ehrlich ist ein Team, das einen gescheiterten Test gelten lässt und die Hypothese anpasst oder aufgibt. So zeigt sich, dass die Idee an der Wirklichkeit scheitern kann. Kühnheit, Fachsprache und Titel lassen sich dagegen auch bloß vorführen.","prueffrage":"Welches Ergebnis hätte das Team vorab als Scheitern seiner Hypothese gelten lassen, und gilt das jetzt noch?","rueckmeldung":[{"option":0,"text":"Sorgfältige Beschreibung mit Formeln und Messwerten wirkt seriös und ist für sich genommen nichts Schlechtes. Sie lässt sich aber auch ohne ehrliche Absicht nachahmen und zeigt nicht, ob das Team das Scheitern wirklich gelten lässt."},{"option":1,"text":"Titel und angesehene Universitäten stehen meist für echte Fachkenntnis, und diese ist wertvoll. Vor Selbsttäuschung schützt sie aber nicht, und sie zeigt nicht, wie das Team mit der Widerlegung umgeht."},{"option":3,"text":"Es stimmt, dass manche große Entdeckung zunächst gegen die Lehrmeinung stand. Durchgesetzt haben sich solche Ideen aber, weil sie Prüfungen bestanden, nicht weil man negative Tests übergangen hat. Festhalten allein belegt weder Mut noch Ehrlichkeit."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5bd227544941908b"}},{"id":"qx-f-002","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Was ist an dieser Reaktion auf die Pressemitteilung der Denkfehler?","scenario":"Eine Pressemitteilung meldet ein unerwartetes Signal im Detektor: „Es könnte auf neue Physik hindeuten. Messfehler können wir noch nicht ausschließen, deshalb planen wir unabhängige Wiederholungen.“ Ein Kollege winkt ab: „Unbewiesen heißt unwissenschaftlich. Das ist doch genauso Quatsch wie Astrologie.“","options":["Er setzt „noch nicht bewiesen“ mit „unwissenschaftlich“ gleich: Die Mitteilung benennt ihre Unsicherheit offen und plant unabhängige Wiederholungen.","Er urteilt zu früh: Erst wenn die geplanten Wiederholungen das Signal nicht bestätigen, dürfte er die Meldung als unwissenschaftlich abtun.","Er ersetzt die Prüfung durch Spott: Mit „Quatsch“ und dem Vergleich mit Astrologie wertet er die Meldung ab, ohne auf das Signal einzugehen.","Er urteilt ohne Kenntnis der Daten: Allein aus einer Pressemitteilung, ohne die Messwerte zu sehen, lässt sich nicht sagen, ob das Signal etwas taugt."],"correctIndex":0,"explanation":"„Nicht bewiesen“ und „widerlegt“ sind verschiedene Zustände. Eine spekulative, aber prüfbare Hypothese, deren Urheber ihre Unsicherheit offen benennen und weitere Tests planen, verhält sich methodisch wie seriöse Forschung am Rand des Wissens, nicht wie Pseudowissenschaft. Was Pseudowissenschaft (etwa Astrologie) auszeichnet, ist nicht, dass sie unbewiesen wäre, sondern dass sie widersprüchliche Beweise ignoriert oder wegerklärt und die Beweislast systematisch umkehrt. Entscheidend ist die Methode, nicht die Seltsamkeit oder der noch ausstehende Beweis. Wer jede unbestätigte Idee pauschal als Pseudowissenschaft ablehnt, riskiert, potenziell revolutionäre, aber noch unbewiesene Konzepte zu verpassen. Umgekehrt gibt es auch die Falle des Naiven, der jede als „alternativ“ dargestellte Idee für legitime Grenzwissenschaft hält.","coreRule":"⚡ Maßstab ist die Methode, nicht die Seltsamkeit: „noch nicht bewiesen“ ist nicht „widerlegt“.","beleg":"Werkstück F.0 (Anwendung & Relevanz; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"Unbewiesen ist nicht dasselbe wie unwissenschaftlich: Hier wird die Unsicherheit offen benannt und mit unabhängigen Wiederholungen geprüft. Der Fehler liegt darin, den fehlenden Beweis statt der Methode zum Maßstab zu machen.","prueffrage":"Was haben das Signal im Detektor und die Astrologie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Erst die Wiederholungen abzuwarten, wäre sicher besonnener. Aber auch ein ausbleibendes Signal machte die Meldung nur unbestätigt, nicht unwissenschaftlich: Wissenschaftlich ist sie schon wegen ihrer Methode, unabhängig vom Ausgang."},{"option":2,"text":"Der Spott lässt tatsächlich jede sachliche Auseinandersetzung mit dem Signal aus. Er ist aber nur die Begleiterscheinung: Der eigentliche Fehler liegt im Maßstab, nach dem hier abgewertet wird, nämlich dass etwas Unbewiesenes schon unseriös sei."},{"option":3,"text":"Ohne Messwerte lässt sich die Qualität des Signals tatsächlich nicht beurteilen. Der Kollege urteilt aber über den Status der Meldung, und der hängt an der Methode: Offene Unsicherheit und geplante Wiederholungen sprechen schon in der Mitteilung für seriöse Arbeit."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"aab2fccea63f662c"}},{"id":"qx-f-003","clusterId":"F","werkstueckRef":"F.0","stufe":3,"question":"Eine Anbieterin wirbt für ihre Lehre als „mutige Grenzwissenschaft, die von der dogmatischen Schulwissenschaft unterdrückt wird“. Du willst herausfinden, ob die Lehre ernsthafte Forschung am Rand des Wissens oder Pseudowissenschaft ist. Welche Prüfung bringt dich am sichersten weiter?","options":["Du fragst, wie viele Menschen berichten, dass ihnen die Lehre geholfen hat, denn viele übereinstimmende Erfahrungen sprechen für ihre Wirksamkeit.","Du fragst, welchen Test die Anbieterin vorschlägt und was für sie als Scheitern der Idee gälte, denn daran zeigt sich, ob sie sich überprüfen lässt.","Du prüfst, welche Ausbildung und welche Titel die Anbieterin hat, denn wer fachlich ausgewiesen ist, vertritt eher ernsthafte Forschung.","Du fragst, wie die etablierte Fachwelt auf die Lehre reagiert hat, denn eine einhellige Ablehnung zeigt, dass sie sich nicht bewährt hat."],"correctIndex":1,"explanation":"Ob eine Idee ernsthafte Erkundung oder Pseudowissenschaft ist, entscheidet sich an der Methode, nicht am Etikett und nicht an der Reaktion der anderen. Wer ehrlich am Rand des Wissens forscht, legt offen, wie man seine Idee testen kann, und akzeptiert, dass ein Scheitern des Tests die Idee widerlegt. Die Kombination aus Selbstlob als „mutig“ und dem Vorwurf, unterdrückt zu werden, ist dagegen ein Warnsignal: Sie erklärt Kritik im Voraus zum Beweis für die eigene Richtigkeit und macht die Lehre damit unangreifbar. Die anderen Prüfungen klingen vernünftig, entscheiden aber nichts: Erfolgsberichte Einzelner sind keine kontrollierten Belege und lassen sich für fast jede Lehre finden. Titel und Ausbildung sagen nichts über die Methode, denn auch Ausgewiesene können Unprüfbares vertreten. Und die Ablehnung durch die Fachwelt entscheidet nichts, denn auch ernsthafte Außenseiterideen stoßen zunächst auf Ablehnung; erst der Test zeigt, ob eine Lehre taugt.","coreRule":"⚡ Frag nicht „Wie seltsam?“, sondern „Wo ist der Test, und was gälte als Scheitern?“","quote":"","quoteLabel":"","beleg":"Werkstück F.0 (Red Flags; Anwendung & Relevanz; Das Härten im Feuer, Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Ob eine Lehre ernsthafte Randforschung ist, zeigt sich an der Methode: Nennt sie einen Test und akzeptiert sie, dass ein Scheitern die Idee widerlegt? Wer Kritik im Voraus zum Beweis erklärt, macht sich unangreifbar.","prueffrage":"Was weißt du über die Lehre selbst, nachdem die Anbieterin sie „mutig“ und „unterdrückt“ genannt hat?","rueckmeldung":[{"option":0,"text":"Viele Berichte beeindrucken, und manche Erfahrungen sind sicher echt. Als Beleg taugen sie aber kaum: Sie sind unkontrolliert und lassen sich für fast jede Lehre finden, ohne dass sie die Lehre selbst belegen."},{"option":2,"text":"Eine Ausbildung zeigt, dass jemand Fachkenntnis erworben hat. Über die Methode sagt sie aber nichts, denn auch fachlich Ausgewiesene können Unprüfbares vertreten. Entscheidend ist, ob die Idee testbar ist."},{"option":3,"text":"Ablehnung durch die Fachwelt ist ein Hinweis, mehr nicht: Auch ernsthafte Außenseiterideen stoßen zunächst auf Widerstand. Ob eine Lehre taugt, zeigt erst ein Test, nicht die Zahl derer, die sie ablehnen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"43985581a84e6644"}},{"id":"qx-f-004","clusterId":"F","werkstueckRef":"F.0","stufe":4,"question":"Ein Bekannter wirft Skeptikern vor: „Ihr lehnt einfach alles Neue ab. Früher hat man auch über Ideen gelacht, die später stimmten.“ Welche Antwort geht auf den Einwand am besten ein?","options":["Bei neuen Behauptungen lohnt der Blick auf Geldgeber und Interessen, denn wer von einer Idee profitiert, urteilt selten neutral, und das trifft Außenseiter wie Etablierte.","Bei neuen Ideen sollte man zuerst fragen, wie ausgewiesen die Kritiker im jeweiligen Fach sind, denn ein Urteil aus einem fremden Fachgebiet hat nur geringes Gewicht.","Zuerst sollte geklärt werden, was mit „neu“ und was mit „Skeptiker“ gemeint ist, denn ohne genaue Begriffe redet man aneinander vorbei und kann dem Vorwurf nicht sachlich begegnen.","Neues ist willkommen, wenn es sich prüfen lässt, doch die meisten solcher Ideen scheitern am Test, und nur wenige setzen sich am Ende als gesichertes Wissen durch."],"correctIndex":3,"explanation":"Der Einwand verwechselt zwei Dinge: ob eine Idee neu oder ungewöhnlich ist und ob sie sich prüfen lässt. Entscheidend ist die Methode, nicht die Seltsamkeit der Behauptung. Zwei Fallen liegen nah. In die Falle des Dogmatikers tappt, wer jede neue, seltsam klingende Idee pauschal ablehnt und so potenziell revolutionäre Konzepte verpasst. In die Falle des Naiven tappt, wer jede als „alternativ“ oder „unterdrückt“ dargestellte Idee für legitim hält und so Scharlatanen auf den Leim geht. Die angemessene Haltung gegenüber spekulativen Ideen ist offene, aber kritische Neugier („Wie können wir sie testen?“). Ob eine Idee sich lohnt, zeigt der Test: Die meisten Ideen am Rand des gesicherten Wissens scheitern und verschwinden, nur wenige entwickeln sich zu etablierter Wissenschaft. Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert, doch der Vorwurf lautet hier nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde. Die Fachkenntnis von Kritikern zu hinterfragen hilft, wenn ein Urteil strittig ist, beantwortet aber nicht den Verdacht, Neues werde grundsätzlich abgewiesen. Begriffe zu klären ist nützlich bei unklaren Aussagen, doch der Einwand ist verständlich genug, um in der Sache beantwortet zu werden.","coreRule":"⚡ Offen für Neues, aber nur nach Methode: Prüfbarkeit zählt, nicht Außenseiterstatus. Die meisten Randideen scheitern, einige wenige werden Wissen.","beleg":"Werkstück F.0 (Anwendung & Relevanz: Falle des Dogmatikers und des Naiven; Kontext & Tiefe, Abschnitt II „Fortschritt“)","status":"entwurf","kurz":"Der Einwand verwechselt „neu“ mit „prüfbar“: Entscheidend ist, ob sich eine Idee testen lässt. Wer alles Neue ablehnt, verpasst Gutes, wer alles Neue glaubt, fällt auf Scharlatane herein, denn die meisten Randideen scheitern am Test.","prueffrage":"Wie viele der Ideen, über die früher gelacht wurde, stellten sich später als richtig heraus, und wie viele nicht?","rueckmeldung":[{"option":0,"text":"Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert. Der Vorwurf lautet hier aber nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde, und darauf gibt der Blick auf Geld keine Antwort."},{"option":1,"text":"Wie fachkundig Kritiker sind, ist bei strittigen Urteilen eine berechtigte Frage. Den Verdacht, Neues werde grundsätzlich abgewiesen, räumt das aber nicht aus, denn es sagt nichts darüber, ob sich die Idee prüfen lässt."},{"option":2,"text":"Begriffsklärung hilft bei unklaren Aussagen, doch dieser Einwand ist verständlich genug, um in der Sache beantwortet zu werden. Wer erst über Wörter streitet, weicht der eigentlichen Frage aus, wie sich die neue Idee testen lässt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"8a2db48007ff070b"}},{"id":"qx-f-005","clusterId":"F","werkstueckRef":"F.1.1","stufe":1,"question":"Eine Prüferin stellt bei einer Heilmethode fest: Die Beweislast wird umgekehrt, die Aussagen sind nicht widerlegbar, es gibt fast nur Erfolgsgeschichten statt kontrollierter Studien, kritische Studien werden ignoriert, die Grundlehre ist seit Jahrhunderten unverändert und mit der Methode lassen sich teure Seminare verkaufen. Was darfst du daraus am vernünftigsten schließen?","options":["Die Methode imitiert sehr wahrscheinlich nur den Anschein von Wissenschaft, auch wenn nicht jedes denkbare Warnzeichen vorliegt.","Die Methode ist sehr wahrscheinlich ein vorsätzlicher Betrug, denn wer teure Seminare verkauft, täuscht seine Kundschaft bewusst.","Das Muster zeigt nur, dass die Anbieter unseriös auftreten; ob die Methode wirkt, lässt sich daraus nicht einmal abschätzen.","Jedes dieser Warnzeichen kommt gelegentlich auch bei seriöser Forschung vor; aus der Liste lässt sich daher nichts ableiten."],"correctIndex":0,"explanation":"Die Warnzeichen betreffen Methode und Verhalten, nicht den Inhalt jeder Einzelbehauptung. Eine Disziplin muss nicht alle denkbaren Kriterien erfüllen, damit das Muster aussagekräftig ist: Je mehr davon zutreffen, desto wahrscheinlicher ist es, dass nur die äußere Form von Wissenschaft nachgeahmt wird, ohne ihre Prinzipien (Prüfbarkeit, Selbstkorrektur, Offenheit für Gegenbeweise) zu befolgen. Das ist ein Wahrscheinlichkeitsurteil über die Methode, kein Beweis gegen jede einzelne Aussage.","coreRule":"⚡ Methodische Warnzeichen sind ein Scanner für Verhalten: Je mehr Treffer, desto wahrscheinlicher Imitation von Wissenschaft, aber nie ein Beweis.","beleg":"Werkstück F.1.1 (Kontext & Tiefe: 10-Punkte-Checkliste, Schlusssatz)","status":"entwurf","scenario":"","kurz":"Je mehr dieser Zeichen zusammenkommen, desto wahrscheinlicher ahmt die Methode nur die Form von Wissenschaft nach, ohne ihre Prinzipien zu befolgen. Das ist ein Urteil über die Methode, kein Beweis gegen jede Einzelaussage.","prueffrage":"Wie viele der aufgezählten Auffälligkeiten treffen bei dieser Heilmethode zugleich zu?","rueckmeldung":[{"option":1,"text":"Teure Seminare sind ein Warnzeichen, aber Gewinnstreben beweist keine Täuschungsabsicht: Anbieter können selbst überzeugt sein. Das Muster urteilt über die Methode, nicht über die Absicht der Anbieter."},{"option":2,"text":"Das Muster widerlegt tatsächlich keine einzelne Behauptung. Es sagt aber durchaus etwas über die Methode aus und verschiebt die Wahrscheinlichkeit, ob sie Wirksamkeit belegen kann. Gar nichts abschätzen zu können, geht zu weit."},{"option":3,"text":"Einzelne Zeichen kommen tatsächlich auch bei seriöser Forschung vor. Entscheidend ist hier aber das Zusammentreffen mehrerer: Das Muster als Ganzes ist aussagekräftig, auch wenn jedes Zeichen für sich es nicht wäre."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1, 5.2","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1e2624731f1dbbae"}},{"id":"qx-f-006","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Was ist an dieser Aussage aus Sicht der wissenschaftlichen Methode das Kernproblem?","scenario":"In einem Reiki-Kurs sagt der Leiter: „Wenn die Energieheilung bei dir nicht gewirkt hat, hat deine Skepsis den Energiefluss blockiert.“","options":["Sie greift die Person an, statt auf die Sache einzugehen, weil sie den Teilnehmer als Skeptiker abstempelt.","Sie macht die Behauptung unwiderlegbar, weil sich jedes Scheitern dem Prüfenden und seiner Skepsis anlasten lässt.","Sie nennt keinen Mechanismus, weil offenbleibt, auf welchem Weg Skepsis einen Energiefluss überhaupt blockieren soll.","Sie erschwert Tests, weil Erwartungen eine Wirkung verstärken können und Gläubige anders reagieren könnten als Skeptiker."],"correctIndex":1,"explanation":"Eine Behauptung, die jedes Scheitern auf den Prüfenden abwälzt, kann durch kein Experiment widerlegt werden: Wirkt die Behandlung, gilt sie als bestätigt; wirkt sie nicht, war der Zweifler schuld. Eine Aussage, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt.","coreRule":"⚡ Wenn der Zweifler am Misserfolg schuld sein soll, ist die Behauptung nicht mehr prüfbar.","beleg":"Werkstück F.1.1 (Checkliste Punkt 2, mit Beispiel zur Energieheilung)","status":"entwurf","kurz":"Die Aussage erklärt jedes Scheitern zur Schuld des Zweiflers und kann so durch kein Ergebnis widerlegt werden. Der naheliegende Fehler ist, nur einzelne Schwächen zu sehen, statt dass sie mit jedem Ausgang vereinbar ist.","prueffrage":"Welche Belege, Einzelfälle oder Studien führt der Leiter in seinem Satz überhaupt an?","rueckmeldung":[{"option":0,"text":"Die Aussage richtet sich tatsächlich auf die Person und ihre Haltung, das ist ein berechtigter Eindruck. Entscheidend ist aber, was sie leistet: Sie verteidigt die Behauptung gegen jeden Misserfolg, und das ist die eigentliche methodische Schwäche."},{"option":2,"text":"Ein fehlender Mechanismus ist hier tatsächlich ein berechtigter Einwand. Er trifft aber nicht den Kern: Auch mit einem genannten Mechanismus bliebe die Aussage unwiderlegbar, solange jedes Scheitern der Skepsis zugeschrieben wird."},{"option":3,"text":"Erwartungseffekte sind real und können Tests tatsächlich verzerren, doch dem lässt sich mit verblindeten Versuchen begegnen. Hier liegt das Problem tiefer: Die Aussage schließt von vornherein aus, dass ein Ergebnis sie widerlegen könnte."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"c0ecd38ba78eb2f4"}},{"id":"qx-f-007","clusterId":"F","werkstueckRef":"F.1.1","stufe":3,"question":"Woran würdest du erkennen, dass aus dieser Hypothese eine Pseudowissenschaft geworden ist?","options":["Sie ist ausgesprochen ungewöhnlich, und eine Hypothese, die so weit vom Gewohnten abweicht, ist eher Glaube als Wissenschaft.","Sie ist seit 20 Jahren unbestätigt, und eine Hypothese, die so lange keine Bestätigung findet, ist keine Wissenschaft mehr.","Sie ist nicht mehr testbar und bestätigt sich selbst, weil jedes denkbare Ergebnis zu ihren Gunsten ausgelegt wird.","Mehrere Experimente zu ihr sind gescheitert, und eine Hypothese, die sich nicht bewährt, ist damit pseudowissenschaftlich."],"correctIndex":2,"explanation":"Spekulative, seltsame oder lange unbestätigte Ideen können Wissenschaft bleiben, solange ein Test sie widerlegen könnte. Sie kippt, wenn sie sich der Prüfung entzieht: Wer Fehlschläge mit Ausreden auffängt und jedes Ergebnis als Bestätigung liest, hat aus der Hypothese ein Glaubenssystem gemacht, das nichts mehr widerlegen kann. Entscheidend ist die Prüfbarkeit selbst. Dass niemand die Hypothese seit 20 Jahren bestätigen konnte, macht sie nicht pseudowissenschaftlich, solange ein Test sie widerlegen könnte. Gescheiterte Experimente gehören zur Wissenschaft, entscheidend ist, ob man sie als Widerlegung gelten lässt.","coreRule":"⚡ Nicht die Dauer oder die Seltsamkeit entscheidet, sondern ob die Idee noch scheitern darf.","beleg":"Werkstück F.1.1 (Der Kipppunkt)","status":"entwurf","scenario":"Eine Forscherin vertritt seit 20 Jahren eine ungewöhnliche Hypothese, die bisher niemand bestätigen konnte. In den vergangenen Jahren sind mehrere Experimente zur Hypothese gescheitert. Ihre Reaktion: Die Experimente seien nicht empfindlich genug gewesen, denn die Wirkung zeige sich nur, wenn niemand sie zu messen versucht. Jedes weitere Ergebnis deutet sie als Bestätigung.","kurz":"Entscheidend ist, ob irgendein Ergebnis die Hypothese noch widerlegen könnte. Wer Fehlschläge mit Ausreden auffängt und jedes Resultat als Bestätigung liest, macht sie unwiderlegbar. Ungewöhnlich oder lange unbestätigt darf sie bleiben.","prueffrage":"Wie viele Experimente sind bisher gescheitert, und was folgerte die Forscherin jeweils daraus?","rueckmeldung":[{"option":0,"text":"Ungewöhnliches verlangt zu Recht starke Belege und weckt Skepsis. Über die Prüfbarkeit sagt das aber nichts: Auch sehr seltsame Ideen bleiben Wissenschaft, solange ein Test sie widerlegen könnte."},{"option":1,"text":"Zwanzig Jahre ohne Bestätigung sind ein guter Grund, die Hypothese für wenig plausibel zu halten. Pseudowissenschaftlich wird sie dadurch nicht, solange ein Test sie widerlegen könnte."},{"option":3,"text":"Gescheiterte Experimente sprechen gegen die Hypothese, gehören aber zur Wissenschaft und zeigen gerade, dass sie prüfbar ist. Kritisch ist die Reaktion darauf: ob man das Scheitern als Widerlegung gelten lässt oder wegerklärt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.6, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7209b426b7d01761"}},{"id":"qx-f-008","clusterId":"F","werkstueckRef":"F.1.1","stufe":4,"question":"Wie solltest du auf dieses Seminarversprechen reagieren, wenn du seine Stichhaltigkeit prüfen willst?","options":["Du fragst, was „Quantenheilung“ und „biologische Schwingung“ bedeuten und wie man ihre Wirkung testen könnte. Bleibt das vage, ist der Anspruch nicht prüfbar.","Du suchst selbst nach Studien zur Quantenheilung durch Schwingung. Findest du keine, ist das Versprechen damit widerlegt und das Seminar nicht ernst zu nehmen.","Du lässt dir die Qualifikation der Seminarleitung nachweisen. Ein anerkannter Abschluss ist ein guter Hinweis darauf, dass jemand in seinem Fach kompetent ist.","Du prüfst, ob Begriffe wie „Quanten“ und „Schwingung“ tatsächlich in der Physik vorkommen. Tun sie das, hat das Versprechen eine wissenschaftliche Grundlage."],"correctIndex":0,"explanation":"Wissenschaftlich klingende Wörter beweisen nichts; entscheidend ist, ob eine Behauptung etwas Bestimmtes aussagt, das sich testen lässt. „Quantenheilung“ und „biologische Schwingung“ klingen nach Physik, ohne eine nachprüfbare Bedeutung zu haben, und der Verweis auf „Ganzheitlichkeit“ verlegt den Anspruch dorthin, wo ihn angeblich keine Prüfung erreicht. Die Rückfrage nach Bedeutung und Prüfbarkeit deckt genau das auf. Eine Qualifikation sagt etwas über die Person, nicht darüber, ob die Behauptung überhaupt prüfbar ist.","coreRule":"⚡ Klingt eine Behauptung wissenschaftlich und beruft sich auf „Ganzheitlichkeit“, frag zuerst nach Bedeutung und Prüfbarkeit, bevor du Belege würdigst.","beleg":"Werkstück F.1.1 (Checkliste Punkte 8 und 9)","status":"entwurf","scenario":"Ein Seminar verspricht „Quantenheilung durch biologische Schwingung“. Auf Nachfrage heißt es, das sei „ganzheitlicher“, als es die „reduktionistische“ Wissenschaft je erfassen könne. Studien oder Messwerte werden nicht genannt.","kurz":"Wer zuerst nach Bedeutung und Testbarkeit fragt, erkennt, ob überhaupt etwas Prüfbares behauptet wird. Fachwörter klingen nach Physik und beweisen nichts, und „ganzheitlich“ verschiebt den Anspruch dorthin, wo er angeblich nicht erreichbar ist.","prueffrage":"Was genau soll bei Teilnehmenden nach dem Seminar anders sein als vorher?","rueckmeldung":[{"option":1,"text":"Selbst zu recherchieren ist sinnvoll, und fehlende Studien lassen das Versprechen unbelegt. Widerlegt ist es dadurch aber nicht: Bei so unscharfen Begriffen weißt du kaum, wonach du suchen solltest, und ein Suchergebnis ersetzt keine Klärung."},{"option":2,"text":"Ein anerkannter Abschluss sagt etwas über die Fachkompetenz einer Person aus. Er sagt aber nichts darüber, ob dieses Versprechen etwas Bestimmtes behauptet, das sich testen lässt; auch Qualifizierte können Unprüfbares behaupten."},{"option":3,"text":"„Quanten“ und „Schwingung“ stammen tatsächlich aus der Physik, das lässt sich leicht bestätigen. Dass die Wörter dort vorkommen, heißt aber nicht, dass sie hier etwas Bestimmtes bedeuten; dafür müsste ihre Bedeutung in diesem Zusammenhang klar und nachprüfbar sein."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"38555ea9de1a2b5e"}},{"id":"qx-f-009","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Ein Sportler trägt seit Jahren vor jedem Spiel seine Glückssocken, obwohl er weiß, dass sie nichts bewirken. Ein Kollege fragt ihn: „Warum machst du das dann?“ Welche Antwort ist die sinnvollste Erklärung für sein Verhalten?","options":["Das Ritual kann bestehen bleiben, weil er sich vor allem an Siege mit den Socken erinnert und Niederlagen übersieht, auch wenn die Socken nichts bewirken.","Das Ritual kann bestehen bleiben, weil es seine Anspannung dämpft und ihm ein Gefühl von Kontrolle gibt, auch wenn offen bleibt, ob er dadurch besser spielt.","Das Ritual kann bestehen bleiben, weil er nach den vielen Jahren nicht aufgeben will, was er hineingesteckt hat, auch wenn es ihm nichts bringt.","Das Ritual kann bestehen bleiben, weil er durch den Glauben an die Socken tatsächlich besser spielt, auch wenn er weiß, dass sie nichts bewirken."],"correctIndex":1,"explanation":"Wer sich einer Situation mit unsicherem Ausgang gegenübersieht, kann durch ein Ritual das Gefühl gewinnen, den Ausgang irgendwie zu beeinflussen. Dieses Gefühl von Kontrolle kann Angst dämpfen, auch wenn der Sportler rational weiß, dass die Socken nichts bewirken. Ein Feldexperiment mit religiösen Tempelritualen (Lang, Krátký und Xygalatas, 2020) deutet auf weniger berichtete Angst und weniger körperliche Anspannung nach einer Stressaufgabe hin (nach Angabe der Autoren erste, nicht laborgenau kontrollierte Belege); ob dasselbe für private Glücksrituale gilt, ist damit nicht gezeigt.","coreRule":"⚡ Ein Ritual kann beruhigen, ohne das Ergebnis zu beeinflussen: Trenne das Gefühl von Kontrolle von der tatsächlichen Wirkung.","beleg":"Werkstück F.1.2 (Kontext & Tiefe; Fn. gl-f-ritual-angst: Lang, Krátký, Xygalatas 2020, Abschn. 3 und 4)","status":"entwurf","scenario":"","kurz":"Das Ritual kann Anspannung dämpfen und das Gefühl geben, den unsicheren Ausgang irgendwie zu beeinflussen, auch wenn er weiß, dass die Socken nichts bewirken. Ob er dadurch besser spielt, bleibt offen.","prueffrage":"Was ließe sich beim Sportler vor einem Spiel mit und ohne Socken tatsächlich beobachten oder messen?","rueckmeldung":[{"option":0,"text":"Selektives Erinnern an Siege hält viele Aberglauben am Leben. Es setzt aber voraus, dass er die Siege den Socken zuschreibt, und genau das tut er nicht: Er weiß ja, dass sie nichts bewirken."},{"option":2,"text":"Wer schon viel investiert hat, hält oft an etwas fest. Hier ginge aber kaum etwas verloren, denn Socken anzuziehen kostet fast keinen Aufwand. Als Erklärung trägt das also nicht."},{"option":3,"text":"Der Glaube an eine Wirkung kann die Leistung tatsächlich beeinflussen. Dafür müsste er aber auf die Socken vertrauen, und er weiß, dass sie nichts bewirken. Ob solche Rituale die Leistung überhaupt verbessern, ist zudem nicht gesichert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Calin-Jageman, R. J.; Caldwell, T. L. (2014): „Replication of the Superstition and Performance Study by Damisch, Stoberock, and Mussweiler (2010)“, Social Psychology 45(3)","oeffentlich":false,"doi":"10.1027/1864-9335/a000190"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aa5830c57cf41ae1"}},{"id":"qx-f-010","clusterId":"F","werkstueckRef":"F.1.2","stufe":2,"question":"Was ist an dieser Deutung das eigentliche Problem?","scenario":"Dein Kollege trägt zur Prüfung immer dieselbe Glückskette. Besteht er, sagt er: „Siehst du, sie wirkt.“ Fällt er durch, sagt er: „Ich habe sie zu spät angezogen.“","options":["Er hält die Kette für wirksam, weil das Bestehen auf das Tragen folgte; so verwechselt er ein zeitliches Nacheinander mit einer Ursache.","Er übersieht den Zufall, denn Prüfungen gehen auch ohne Kette mal gut und mal schlecht aus; so hält er Schwankungen für eine Wirkung.","Er legt Prüfungen nur mit der Kette ab und hat keinen Vergleich; so fehlt ihm etwa ein Durchfallen ohne Kette, das ihre Wirkung zeigen würde.","Er wertet Bestehen als Beweis für die Kette und Durchfallen als seinen eigenen Fehler; so kann kein denkbares Ergebnis die Kette widerlegen."],"correctIndex":3,"explanation":"Entscheidend ist die ungleiche Auswertung: Ein Treffer bestätigt das Ritual, ein Fehlschlag wird dem Anwender angelastet. Damit gibt es kein denkbares Ergebnis, das gegen die Kette sprechen würde, die Behauptung ist nicht widerlegbar und sagt deshalb auch nichts aus. Ob ein Ritual wirkt, ließe sich nur in einem kontrollierten Vergleich mit und ohne Ritual prüfen.","coreRule":"⚡ Wenn nur Erfolge dem Ritual zählen und Misserfolge dem Menschen, ist das Ritual immun gegen Widerlegung.","beleg":"Werkstück F.1.2 (Red Flags: asymmetrische Erklärung; Der Kipppunkt)","status":"entwurf","kurz":"Er wertet nur zu seinen Gunsten: Bestehen gilt als Beweis, Durchfallen als eigener Fehler. So kann kein Ergebnis gegen die Kette sprechen, und die Behauptung sagt nichts aus. Das Problem liegt weniger im Nacheinander als in dieser ungleichen Auswertung.","prueffrage":"Was würde sich an seiner Deutung ändern, wenn er die Kette noch zwanzig weitere Prüfungen lang trägt?","rueckmeldung":[{"option":0,"text":"Dass er aus dem Bestehen nach dem Tragen auf Wirkung schließt, stimmt und ist für sich schon fragwürdig. Das erklärt aber nicht, warum ihn auch Durchfallen nicht umstimmt: Dafür sorgt erst, dass er Fehlschläge ausschließlich sich selbst anlastet."},{"option":1,"text":"Schwankungen der Prüfungsergebnisse gibt es tatsächlich, und mit Zufall allein ließe sich vieles erklären. Selbst ohne jeden Zufall bliebe seine Deutung aber unwiderlegbar, weil er jedes Ergebnis zu Gunsten der Kette auslegt."},{"option":2,"text":"Ein Vergleich mit und ohne Kette wäre tatsächlich nötig, um ihre Wirkung zu prüfen. Doch auch mit Vergleich ließe sich ein Fehlschlag noch dem Anwender anlasten; das eigentliche Problem liegt darin, wie er die Ergebnisse auswertet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"afdbe7bba8692784"}},{"id":"qx-f-011","clusterId":"F","werkstueckRef":"F.1.2","stufe":3,"question":"Bei welcher Person ist die Grenze vom harmlosen Ritual zum echten Problem überschritten?","options":["Ein Vertreter fährt vor wichtigen Kundenterminen einen Umweg an einem Ort vorbei, der ihm für das Gespräch Glück bringen soll.","Ein Student nimmt zu seinen Klausuren denselben Glücksstift mit und hat vorsorglich einen zweiten gekauft, falls er den ersten verliert.","Eine Unternehmerin sagt eine gut vorbereitete, wichtige Geschäftsentscheidung kurzfristig ab, weil ihr Tageshoroskop davon abrät.","Eine Familie legt ihren Ausflug wegen Freitag, dem 13., auf den Samstag, obwohl der Freitag eigentlich ihr Wunschtermin war."],"correctIndex":2,"explanation":"Ein Aberglaube ist dann ein Problem, wenn er echte, kostspielige Entscheidungen steuert, wenn er zwanghaft wird, wenn er wirksames Handeln ersetzt oder wenn er bei Misserfolg zu Selbstvorwürfen führt. Ein Horoskop, das darüber entscheidet, ob eine wichtige Geschäftsentscheidung fällt, hat mit dem Erfolg des Geschäfts nichts zu tun, kann aber viel Geld kosten. Die anderen drei Rituale sind klein und werden bewusst gehandhabt. Die Glückszahl entscheidet beim Händler nur zwischen zwei Angeboten, die er vorher gründlich geprüft hat und die gleich gut sind. Der Handschuh beruhigt die Torfrau und ersetzt keine Vorbereitung. Die Verlegung des Ausflugs kostet die Familie nichts, weil beide Tage gleich gut passen.","coreRule":"⚡ Harmlos ist das Ritual, das beruhigt; gefährlich wird es, wenn es Entscheidungen steuert.","beleg":"Werkstück F.1.2 (Der Kipppunkt, Punkt 1 bis 4)","status":"entwurf","scenario":"Vier Personen pflegen jeweils einen kleinen Aberglauben. Alle vier wissen, dass ihr Ritual keine nachweisbare Wirkung hat; es geht darum, was das Ritual im Alltag tatsächlich anrichtet.","kurz":"Ein Aberglaube wird zum Problem, wenn er eine wichtige, womöglich teure Entscheidung steuert. Ein Horoskop hat mit dem Erfolg eines Geschäfts nichts zu tun, kann aber viel Geld kosten. Kleine, bewusst gehandhabte Rituale ersetzen dagegen kein wirksames Handeln.","prueffrage":"Welche der vier Personen ändert wegen ihres Rituals überhaupt etwas an einer Entscheidung?","rueckmeldung":[{"option":0,"text":"Ein Ritual vor einem wichtigen Termin wirkt schnell riskant, weil viel auf dem Spiel steht. Der Umweg ist aber klein und bewusst gewählt und entscheidet nichts am Geschäft selbst; er kostet höchstens etwas Zeit."},{"option":1,"text":"Ein zweiter Stift wirkt wie der Anfang eines Zwangs. Das Szenario zeigt aber nur eine kleine, bewusste Vorsorge, die kaum etwas kostet und keine Entscheidung bestimmt."},{"option":3,"text":"Hier richtet sich eine Planung nach einem Aberglauben, und das fällt auf. Es entsteht aber kein Schaden, denn beide Tage passen der Familie gleich gut. Eine Entscheidung mit echten Kosten wird dadurch nicht verändert."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): „A double-blind test of astrology“, Nature 318","oeffentlich":false,"doi":"10.1038/318419a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a32adb3373301821"}},{"id":"qx-f-012","clusterId":"F","werkstueckRef":"F.1.2","stufe":4,"question":"Eine Freundin zündet eine Kerze an, um „Reichtum anzuziehen“, und bekommt drei Wochen später eine Gehaltserhöhung. Sie sagt: „Siehst du, es hat funktioniert!“ Warum ist das noch kein Beleg dafür, dass die Kerze gewirkt hat?","options":["Dass die Erhöhung nach der Kerze kam, zeigt nicht, dass sie deswegen kam; erst ein Vergleich mit und ohne Kerze würde eine Wirkung zeigen.","Es ist bisher nur ein einziger Fall; erst wenn auf mehrere angezündete Kerzen jeweils eine Erhöhung folgte, ließe sich eine Wirkung annehmen.","Es fehlt ein Weg, wie eine Kerze ein Gehalt beeinflussen könnte; erst wenn sich ein solcher Weg zeigen ließe, spräche die Erhöhung für die Kerze.","Für eine Gehaltserhöhung gibt es meist Gründe im Beruf; erst wenn sich dort keiner findet, spräche die Erhöhung für eine Wirkung der Kerze."],"correctIndex":0,"explanation":"Die Kerze steht vor der Gehaltserhöhung, aber zeitliche Abfolge ist keine Ursache. Das ist der Fehlschluss „danach, also deswegen“. Es gibt keine plausible Verbindung zwischen einer brennenden Kerze und dem Gehalt, und ein einzelner Treffer ist mit Zufall bestens erklärbar: Gehaltserhöhungen kommen auch ohne Kerzen vor. Erst ein Vergleich würde zeigen, ob Menschen mit Kerze häufiger eine Erhöhung bekommen als Menschen ohne. Eine Umkehrung von Ursache und Wirkung klingt nach einer üblichen Fehlerquelle, scheitert aber daran, dass die Kerze drei Wochen vor der Erhöhung brannte und von einer erwarteten Erhöhung nichts erzählt wird. Das Vergessen anderer Rituale wäre ein bekannter Denkfehler, doch es geht um einen einzelnen Fall, nicht um eine Auswahl aus vielen. Eine Überschätzung der Häufigkeit wirkt naheliegend, aber die Freundin schätzt keine Häufigkeit; entscheidend ist, ob die Kerze überhaupt etwas dazu beiträgt.","coreRule":"⚡ Wer von „danach“ auf „deswegen“ schließt, braucht einen Vergleich mit und ohne die vermutete Ursache; die bloße Reihenfolge reicht nie.","beleg":"Werkstück F.1.2 (Kontext & Tiefe: Post hoc; Anwendung & Relevanz: In der Esoterik & New Age)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Dass die Erhöhung nach der Kerze kam, heißt nicht, dass sie deswegen kam: Erhöhungen gibt es auch ohne Kerzen. Erst ein Vergleich von Menschen mit und ohne Kerze zeigt, ob sie überhaupt etwas beiträgt.","prueffrage":"Was ist in den drei Wochen zwischen Kerze und Gehaltserhöhung sonst noch geschehen, etwa bei ihrer Arbeit oder im Betrieb?","rueckmeldung":[{"option":1,"text":"Ein Einzelfall ist tatsächlich zu wenig. Aber auch mehrere Erhöhungen nach mehreren Kerzen blieben bloße Abfolgen, solange offen ist, wie oft Erhöhungen auch ohne Kerze vorkommen."},{"option":2,"text":"Dass sich kein Weg vom Kerzenlicht zum Gehalt denken lässt, spricht gegen eine Wirkung. Doch selbst ein denkbarer Weg wäre noch kein Beleg: Auch dann müsste ein Vergleich mit und ohne Kerze zeigen, ob sie etwas bewirkt."},{"option":3,"text":"Meist hat eine Gehaltserhöhung berufliche Gründe, das stimmt. Aus dem Fehlen sichtbarer Gründe folgt aber nicht, dass die Kerze gewirkt hat, denn man kennt nie alle Gründe, und auch Zufall bliebe möglich."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Post Hoc“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"214105fe0fe904cd"}},{"id":"qx-f-013","clusterId":"F","werkstueckRef":"F.1.3","stufe":1,"question":"Ein Online-Beitrag behauptet: „Eine geheime Elite steuert seit Jahrzehnten die Weltpolitik, ohne dass je ein Mitwisser geplaudert hat. Dass sie ständig verräterische Symbole in Filmen und Logos versteckt, beweist: Sie ist so sicher, dass sie sich nicht verstecken muss.“ Welcher Widerspruch macht diese Erzählung unglaubwürdig?","options":["Dieselbe Gruppe soll so umsichtig sein, dass sie ein Geheimnis jahrzehntelang perfekt wahrt, und so nachlässig, dass ein Hobbydetektiv ihre Spuren findet.","Dieselbe Gruppe soll die Weltpolitik steuern und hat trotzdem Zeit und Mittel, Symbole in Filmen und Logos zu verstecken, als hätte sie nichts Wichtigeres zu tun.","Dieselbe Gruppe soll Mitwisser haben, von denen keiner je geplaudert hat; das widerspricht der Erfahrung, dass Geheimnisse irgendwann durchsickern.","Dieselbe Gruppe soll die Weltpolitik lenken, und belegt wird das nur mit gedeuteten Symbolen; ein so großer Anspruch und so dünne Belege passen nicht zusammen."],"correctIndex":0,"explanation":"Die Erzählung braucht einen Feind, der zwei Dinge zugleich sein muss: übermenschlich kompetent (er hält eine globale Verschwörung jahrzehntelang geheim) und unfassbar dumm (er hinterlässt „Hinweise“, die jeder YouTube-Detektiv finden kann). Beides gleichzeitig ist kaum plausibel. Wenn eine Erklärung nur funktioniert, indem sie ihrem Feind widersprüchliche Eigenschaften zuschreibt, ist das ein Warnsignal.","coreRule":"⚡ Allmächtig und doch schlampig: Wenn der Feind beides zugleich sein muss, trägt die Erzählung nicht.","beleg":"Werkstück F.1.3 (Kontext & Tiefe, Anatomie, Punkt 1: Ein allmächtiger, böswilliger Feind)","status":"entwurf","scenario":"","kurz":"Der Feind muss zugleich übermenschlich geschickt (er wahrt ein Geheimnis jahrzehntelang) und erstaunlich sorglos (er streut Spuren, die jeder findet) sein. Wenn eine Erzählung nur trägt, weil sie ihrem Gegner Gegensätzliches zuschreibt, ist das ein Warnsignal.","prueffrage":"Wie erklärt der Beitrag, dass die angeblichen Symbole offen in Filmen und Logos zu sehen sind?","rueckmeldung":[{"option":1,"text":"Dass eine Gruppe mit so großer Macht Zeit für Symbole hätte, ist tatsächlich seltsam. Das ist aber ein Einwand gegen ihre Prioritäten. Der eigentliche Widerspruch liegt darin, dass sie zugleich perfekt verborgen und auffallend sorglos handeln soll."},{"option":2,"text":"Geheimnisse mit vielen Mitwissern sickern erfahrungsgemäß oft durch, das spricht gegen die Erzählung. Es ist aber ein Einwand aus der Erfahrung und kein Widerspruch in der Erzählung selbst, denn die Eigenschaften der Gruppe vertragen sich hier nicht."},{"option":3,"text":"Ein so großer Anspruch mit so dünnen Belegen passt wirklich schlecht zusammen. Das beschreibt aber fehlende Belege und nicht den inneren Widerspruch der Erzählung: Dieselbe Gruppe soll zugleich makellos geheim und auffällig nachlässig sein."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Contradictory“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a451add5f3656e14"}},{"id":"qx-f-014","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Wie erklärst du am besten, dass dir die Saboteur-Geschichte verführerischer vorkommt, obwohl sie kaum belegt ist?","scenario":"In deinem Haus zeigen sich Risse in der Wand, und die Tür klemmt. Ein Gutachter nennt instabilen Baugrund: ein komplexes, teures Problem, das ein aufwendiges Stabilisieren des Fundaments verlangt. Dein Nachbar flüstert dagegen, eine geheime Immobilien-Lobby wolle das Viertel billig aufkaufen und schlage nachts mit dem Hammer gegen dein Fundament. Der klemmende Türrahmen sei der Beweis.","options":["Sie knüpft an die klemmende Tür an, die du selbst sehen und prüfen kannst; so wirkt sie wie ein greifbarer Beleg, den du nicht erst einem Gutachter glauben musst.","Sie ist einfach und dramatisch und bietet einen Feind, gegen den man kämpfen kann; sie erfüllt das Bedürfnis nach Sinn und Kontrolle, ohne mehr Belege zu liefern.","Sie verspricht einen Ausweg aus den hohen Kosten; wenn Saboteure schuld sind, scheint die teure und aufwendige Stabilisierung des Fundaments auf einmal vermeidbar.","Sie wird dir zugeflüstert und wirkt dadurch wie Insiderwissen; was vertraulich weitergegeben wird, hält man leicht für wertvoller als eine öffentliche Auskunft."],"correctIndex":1,"explanation":"Wie verführerisch eine Erklärung wirkt, sagt nichts darüber, wie gut sie belegt ist. Die Saboteur-Geschichte bietet einen klaren Bösewicht, einen einfachen Plan und das Gefühl, Bescheid zu wissen und handeln zu können. Die Erklärung des Gutachters ist dagegen kompliziert, beängstigend und teuer, obwohl sie die Risse und die klemmende Tür ebenfalls erklärt. Dass eine Geschichte emotional befriedigt, ist kein Beleg für ihre Wahrheit. Die Forschung zu Verschwörungsglauben zeigt außerdem: Er wird von Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit getrieben, erfüllt sie aber meist nicht.","coreRule":"⚡ Eine Erklärung kann sich gut anfühlen und trotzdem schlecht belegt sein: Prüfe Belege, nicht den Gefühlswert.","beleg":"Werkstück F.1.3 (Das rissige Fundament; Kernidee; Anatomie, Punkt 2: Apophenie)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wie verführerisch eine Geschichte wirkt, sagt nichts über ihre Belege. Die Saboteur-Version bietet einen Feind, einen einfachen Plan und das Gefühl, handeln zu können, während der Gutachter dieselben Risse unbequem und teuer erklärt.","prueffrage":"Was bietet die Geschichte des Nachbarn dem Hausbesitzer, das ihm das Gutachten nicht bietet?","rueckmeldung":[{"option":0,"text":"Die klemmende Tür ist wirklich sichtbar und prüfbar. Sie spricht aber nicht für die Saboteure, denn der instabile Baugrund erklärt Risse und klemmende Tür genauso gut. Deshalb taugt sie nicht als Grund für die größere Anziehungskraft."},{"option":2,"text":"Die Aussicht, hohe Kosten zu sparen, kann tatsächlich Wunschdenken anstoßen. Die Stärke der Saboteur-Geschichte liegt aber tiefer: Sie liefert einen klaren Feind, Sinn und das Gefühl, handeln zu können, und das wirkt auch ohne jede Kostenfrage."},{"option":3,"text":"Etwas Zugeflüstertes kann geheimnisvoll und wertvoll wirken. Das erklärt hier aber nicht, warum gerade diese Geschichte besticht: Sie verführt, weil sie einen Bösewicht, einen einfachen Plan und das Gefühl von Kontrolle bietet, nicht wegen der Art der Weitergabe."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c682cc82a98e8a25"}},{"id":"qx-f-015","clusterId":"F","werkstueckRef":"F.1.3","stufe":3,"question":"Wie ordnest du seine Aussage am besten ein?","options":["Sein Satz zeigt, dass der Glaube ihm Kontrolle gibt; die Experimente prüften nur kurzes Lesen und sagen über Monate des Glaubens deshalb wenig aus.","Sein Satz zeigt, dass Kontrolle sein Motiv war; und weil ein Glaube ohne erfülltes Motiv aufgegeben würde, erfüllt er es nach Monaten offenbar auch.","Sein Satz zeigt, warum er glaubt, nicht dass er Kontrolle hat; die Experimente, in denen Lesen das Kontrollgefühl senkte, sprechen eher dagegen.","Sein Satz gibt sein eigenes Erleben wieder; was er nach Monaten über sich selbst sagt, wiegt schwerer als Experimente mit fremden Versuchspersonen."],"correctIndex":2,"explanation":"Hier sind zwei Fragen zu trennen: Warum glaubt jemand? Und: Bekommt er, was er sich davon verspricht? Die Forschung (Douglas, Sutton und Cichocka 2017) führt Verschwörungsglauben auf epistemische, existenzielle und soziale Motive zurück, etwa das Bedürfnis nach Sinn, Kontrolle und Zugehörigkeit. Der Satz deines Freundes passt genau zu diesem Motiv. Einen Beleg, dass der Glaube das Bedürfnis auch erfüllt, gibt es aber nicht; in Experimenten schwächte schon das Lesen von Verschwörungserzählungen das Gefühl von Kontrolle. Sein Gefühl ist real, belegt aber nicht, dass die Erzählung ihm tatsächlich Kontrolle verschafft: „Es fühlt sich nach Kontrolle an“ ist etwas anderes als „Ich habe Kontrolle“. Seine eigene Auskunft wirkt wie ein Beweis, gibt aber nur das Versprechen wieder, nicht den Befund. Dass er nach Monaten noch glaubt, zeigt, dass das Motiv wirkt, nicht dass es erfüllt wird.","coreRule":"⚡ Wer fragt, ob ein Glaube ein Bedürfnis erfüllt, darf das Versprechen nicht mit dem Befund verwechseln: Verschwörungsglaube verspricht Halt, löst ihn aber meist nicht ein.","beleg":"Werkstück F.1.3 (Das Adaptive Talent); Fn. gl-f-douglas (Douglas, Sutton, Cichocka 2017, S. 538 f.)","status":"entwurf","scenario":"Ein Freund beschäftigt sich seit Monaten mit einer Verschwörungserzählung. Er sagt: „Seit ich die Verschwörung durchschaue, habe ich endlich Kontrolle in einer chaotischen Welt.“ Dir fallen zwei Dinge ein. Die Forschung erklärt solchen Glauben mit Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit. Und in Experimenten fühlten sich Versuchspersonen, die eine Verschwörungserzählung gelesen hatten, danach weniger in Kontrolle als andere.","kurz":"Sein Satz zeigt, was er sich vom Glauben verspricht, nicht dass er es bekommt. Dass er seit Monaten glaubt, belegt nur, dass das Motiv wirkt; die Experimente sprechen eher gegen echte Kontrolle.","prueffrage":"Was würde sich bei ihm im Alltag konkret ändern, wenn er wirklich mehr Kontrolle hätte?","rueckmeldung":[{"option":0,"text":"Dass kurzes Lesen kein Monate langes Glauben abbildet, ist ein berechtigter Einwand. Er ändert aber nichts daran, dass es keinen Beleg für gewonnene Kontrolle gibt; die Lücke der Experimente ist noch kein Beleg für das Gegenteil."},{"option":1,"text":"Der Satz passt tatsächlich zum Motiv Kontrolle. Dass er nach Monaten noch glaubt, zeigt aber nur, dass das Motiv weiter wirkt. Ob es erfüllt wird, folgt daraus nicht, denn Glaube kann auch ohne Erfüllung fortbestehen."},{"option":3,"text":"Sein Erleben ist echt, und das darfst du ernst nehmen. Es zeigt aber, wie sich der Glaube für ihn anfühlt, nicht ob er ihm Kontrolle verschafft; ein Gefühl von Kontrolle ersetzt keinen Befund und lässt sich nicht gegen Experimente ausspielen."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"bc0d5c967d39cc58"}},{"id":"qx-f-016","clusterId":"F","werkstueckRef":"F.1.3","stufe":4,"question":"Welcher der beiden Beiträge gibt mehr Grund zur Sorge, und warum?","scenario":"Zwei Beiträge kursieren im Netz. Der erste scherzt, die Stadt Bielefeld existiere gar nicht und sei eine Erfindung. Der zweite behauptet, eine bestimmte Bevölkerungsgruppe steuere insgeheim die Wirtschaft und sei an Krisen schuld. Beide Beiträge bekommen viele Likes. Eine Freundin sagt: „Sind doch beides Verschwörungsgeschichten, also gleich harmlos oder gleich schlimm.“","options":["Beide Beiträge sind gleich ernst, weil beide ohne Beleg eine geheime Lenkung behaupten und damit Misstrauen säen können.","Der erste Beitrag ist ernster, weil er mit Bielefeld eine leicht überprüfbare Tatsache bestreitet und damit Wirklichkeit leugnen kann.","Der zweite Beitrag ist ernster, weil er mehr Zustimmung bekommt und damit eine größere Reichweite hat als der Bielefeld-Scherz.","Der zweite Beitrag ist ernster, weil er reale Menschen zum Feind erklärt und damit Ausgrenzung und Gewalt den Boden bereiten kann."],"correctIndex":3,"explanation":"Beide Beiträge haben die Form einer Verschwörungserzählung: ein verborgener Plan, bei dem Zufall keine Rolle spielt. Den entscheidenden Unterschied macht das Ziel. Ein Scherz über eine Stadt, die es angeblich nicht gibt, bleibt ein Gedankenspiel, das niemandem schadet. Wird dagegen eine reale Gruppe von Menschen zum geheimen Drahtzieher erklärt, entsteht ein Feindbild, und aus Feindbildern können Ausgrenzung, Hass und im schlimmsten Fall Gewalt entstehen. Historisch zeigt das der Vorwurf der Brunnenvergiftung, mit dem 1348 beim Herannahen der Pest jüdische Gemeinden ermordet wurden, oder die gefälschten „Protokolle der Weisen von Zion“, die dem modernen Antisemitismus als angeblicher Beweis dienten.","coreRule":"⚡ Gefährlich wird ein Mythos dort, wo er reale Menschen zum Feind erklärt.","beleg":"Werkstück F.1.3 (Der Kipppunkt; Anwendung & Relevanz: Historische Verschwörungsmythen)","status":"entwurf","kurz":"Entscheidend ist, wer als Drahtzieher benannt wird: Ein Scherz über eine erfundene Stadt bleibt ein Spiel, eine reale Gruppe als Feind schafft ein Feindbild, aus dem Ausgrenzung und Gewalt entstehen können. Dass beide ohne Beleg auftreten, trennt sie nicht.","prueffrage":"Worin unterscheiden sich die beiden Beiträge bei den Likes, und worin bei dem, was sie behaupten?","rueckmeldung":[{"option":0,"text":"Die gemeinsame Form leuchtet ein: Beide behaupten ohne Beleg einen verborgenen Plan. Das haben sie aber nur gemeinsam, es trennt sie nicht. Der Bielefeld-Scherz bleibt ein Gedankenspiel, der zweite Beitrag richtet sich gegen reale Menschen."},{"option":1,"text":"Bielefeld gibt es tatsächlich, und das lässt sich leicht prüfen. Der Beitrag scherzt aber erkennbar und leugnet nichts im Ernst. Gewichtiger ist der Beitrag, der reale Menschen zum geheimen Drahtzieher erklärt."},{"option":2,"text":"Reichweite wäre ein Grund zur Sorge, doch laut Szenario bekommen beide Beiträge viele Likes. Zustimmung unterscheidet die Fälle also nicht; den Unterschied macht, wer als Feind benannt wird."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum, Holocaust Encyclopedia: „Protocols of the Elders of Zion“","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/protocols-of-the-elders-of-zion","abruf":"2026-10-12"},{"typ":"url","kurz":"Cohn, S. K. (2007): „The Black Death and the Burning of Jews“, Past and Present 196 (Einleitung bei Medievalists.net)","oeffentlich":true,"url":"https://www.medievalists.net/2011/01/the-black-death-and-the-burning-of-jews/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3fdee6975387d78f"}},{"id":"qx-f-017","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":1,"question":"Was ist hier der sinnvollste erste Schritt?","options":["Zuerst die Einzelheiten prüfen: Das Video nennt viele Daten und Namen, und erst wenn jede davon bestätigt ist, lässt sich die Erzählung beurteilen.","Zuerst die Verbreitung prüfen: Das Video hat über zwei Millionen Aufrufe, und so viele Zuschauer hätten grobe Fehler längst bemerkt und gemeldet.","Zuerst die offenen Fragen prüfen: Der amtliche Bericht lässt zwei Punkte ungeklärt, und jede solche Lücke stützt die Erzählung des Videos.","Zuerst die Bauweise prüfen: Das Video wertet fehlende Beweise als Beweis, verlangt von dir den Gegenbeweis und erklärt Einwände zur Vertuschung."],"correctIndex":3,"explanation":"Ob eine Erzählung trägt, zeigt sich oft schon an ihrer Bauweise, noch bevor du ein einziges Detail geprüft hast. Das Video zeigt mehrere Alarmzeichen: Das Fehlen von Beweisen wird selbst als Beweis gewertet (Argument aus Unwissenheit), die Beweislast wird dir zugeschoben, und die Erzählung ist unfalsifizierbar, weil jeder Gegenbeweis zur Vertuschung erklärt wird. Eine Behauptung, die durch nichts widerlegt werden kann, ist keine robuste Hypothese, sondern eine uneinnehmbare Festung. Deshalb ist es klüger, zuerst die Struktur zu prüfen, statt endlos die „Fakten“ zu recherchieren, zumal du die Einzelheiten hier gar nicht überprüfen kannst. Alle Einzelheiten nachzuprüfen klingt gründlich, ist hier aber nicht möglich und änderte nichts daran, dass das Video jeden Gegenbeleg umdeutet. Zwei Millionen Aufrufe zeigen Beliebtheit, keine Prüfung. Und zwei offene Punkte im amtlichen Bericht machen die alternative Erzählung nicht wahrscheinlicher; Lücken der einen Darstellung sind kein Beleg für die andere.","coreRule":"⚡ Erst die Struktur prüfen, dann die Details: Wird fehlender Beweis als Beweis gewertet, die Beweislast umgekehrt und jeder Gegenbeweis eingemeindet, ist Vorsicht angebracht.","beleg":"Werkstück F.1.3.1 (Kernidee; Die 7 Warnsignale, Nr. 2–4; Werkbank-Frage)","status":"entwurf","scenario":"Eine Freundin schickt dir ein Video über ein Unglück. Es erklärt das Ereignis zum Werk einer kleinen, mächtigen Gruppe, nennt viele Daten und Namen und hat über zwei Millionen Aufrufe; der amtliche Untersuchungsbericht lässt zwei Punkte ungeklärt. Am Ende heißt es: „Dass keine Beweise auftauchen, zeigt nur, wie perfekt sie alles vertuschen. Beweise du mir erst mal, dass es nicht stimmt.“ Jeden Einwand erklärt das Video vorab zum Teil der Vertuschung. Du kannst die Einzelheiten selbst nicht überprüfen.","kurz":"Schon die Bauweise verrät viel: Das Video wertet fehlende Beweise als Beweis, schiebt dir die Beweislast zu und erklärt jeden Einwand zur Vertuschung, sodass nichts es widerlegen kann. Das erkennst du, ohne ein Detail zu prüfen.","prueffrage":"Welcher Beleg oder Einwand wäre denkbar, den das Video nicht zum Teil der Vertuschung erklären würde?","rueckmeldung":[{"option":0,"text":"Gründliches Nachprüfen wirkt seriös. Du kannst die Einzelheiten hier aber gar nicht prüfen, und selbst bestätigte Daten änderten nichts daran, dass das Video jeden Gegenbeleg umdeutet."},{"option":1,"text":"Viele Aufrufe wirken wie eine große Kontrolle durch viele Augen. Sie zeigen aber nur, wie viele das Video angeklickt haben, nicht, ob jemand es geprüft hat. Beliebtheit ist kein Wahrheitsbeleg."},{"option":2,"text":"Offene Punkte im amtlichen Bericht sind berechtigt und darf man ansprechen. Eine Lücke in der einen Darstellung belegt aber nicht die andere: Dass etwas ungeklärt ist, macht die Erzählung des Videos nicht wahrscheinlicher."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c882523a5c86ae24"}},{"id":"qx-f-018","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"In einem Online-Video heißt es: „Wer das noch nicht durchschaut hat, schläft noch. Du gehörst zu den wenigen, die endlich aufgewacht sind und hinter die Kulissen blicken.“ Welche Wirkung hat diese Rahmung auf das Denken des Publikums?","options":["Sie schmeichelt den Zuschauern mit einem Überlegenheitsgefühl; wer sich zu den „Wissenden“ zählt, ist für die Erzählung eingenommen.","Sie ermuntert die Zuschauer, selbst hinter die Kulissen zu blicken; wer zum Durchschauen aufgerufen wird, prüft die Behauptungen genauer.","Sie setzt zweifelnde Zuschauer unter Druck; wer nicht als Schlafender dastehen will, stimmt lieber zu, als sich bloßzustellen.","Sie ist eine rhetorische Zuspitzung, wie sie in Videos üblich ist; wer solche Sprüche kennt, lässt sich davon kaum beeinflussen."],"correctIndex":0,"explanation":"Die Einteilung in „Erwachte“ und „Schlafschafe“ befriedigt das Bedürfnis nach Überlegenheit: Wer sich zu den Wissenden zählt, fühlt sich den anderen überlegen und wird für die Erzählung eingenommen. Beweislastumkehr, Mitläufereffekt und Gefühlsappell kommen in Verschwörungserzählungen häufig vor, passen aber nicht zu diesem Satz. Er verlangt keinen Gegenbeweis und droht mit nichts. Er nennt „die wenigen“ und beruft sich damit gerade nicht auf eine Mehrheit, sondern schmeichelt dem Selbstbild des Publikums.","coreRule":"⚡ Wo die Welt in Erwachte und Schlafende zerfällt, wirkt das Überlegenheitsgefühl als Bindemittel und ersetzt die Prüfung durch Zugehörigkeit.","beleg":"Werkstück F.1.3.1 (Die 7 Warnsignale, Punkt 7)","status":"entwurf","scenario":"","kurz":"Die Einteilung in „Wissende“ und „Schlafende“ schmeichelt dem Selbstbild: Wer sich zu den wenigen Aufgewachten zählt, fühlt sich überlegen und ist für die Erzählung eingenommen. Mit Druck oder Beweisforderung hat das nichts zu tun.","prueffrage":"Wen teilt der Satz in welche zwei Gruppen ein, und zu welcher soll sich das Publikum zählen?","rueckmeldung":[{"option":1,"text":"„Hinter die Kulissen blicken“ klingt nach Selbstdenken. Der Satz nennt aber keinen einzigen Beleg und lädt nur ein, sich als Wissender zu fühlen. Wer sich schon aufgewacht glaubt, prüft eher weniger genau."},{"option":2,"text":"Der Wunsch, nicht als „Schlafender“ dazustehen, kann Zustimmung begünstigen. Der Satz droht aber mit nichts und beruft sich auf „die wenigen“, nicht auf eine Mehrheit. Er wirkt, indem er dem Selbstbild schmeichelt, nicht über Furcht vor Bloßstellung."},{"option":3,"text":"Dass solche Sprüche in Videos üblich sind, stimmt. Wer sie kennt, ist aber nicht automatisch gefeit: Das gute Gefühl, zu den Wissenden zu gehören, kann trotzdem einnehmen, auch ohne dass man es bemerkt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Persecuted victim“","abruf":"2026-10-12"},{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"eb3545a89840fcd1"}},{"id":"qx-f-019","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":3,"question":"Wie beurteilst du die beiden Fälle?","options":["Beide zeigen den Kipppunkt: Anna wie Ben misstrauen demselben Amt, und schon dieses Misstrauen gegenüber einer Behörde ist das eigentliche Warnsignal.","Nur Ben zeigt den Kipppunkt: Annas Misstrauen ließ sich durch die Rohdaten korrigieren, Bens deutet jeden Beleg um und kostet ihn schon Beziehungen.","Keiner zeigt den Kipppunkt: Beide hatten wegen der falschen Fallzahlen im Vorjahr einen guten Anlass, und ein berechtigter Anlass schließt das Muster aus.","Nur Ben zeigt den Kipppunkt: Er zweifelt nach den alten auch an den neuen Zahlen, und wer einer Behörde wiederholt misstraut, hat die Grenze schon überschritten."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob jemand misstraut, sondern was aus dem Misstrauen wird. Gesundes Misstrauen gegenüber Autoritäten ist nützlich: Anna hatte nach den falschen Zahlen des Vorjahres Grund zur Skepsis, prüfte nach und ließ sich von den Rohdaten korrigieren. Der Kipppunkt ist erreicht, wenn Misstrauen zu einem geschlossenen Weltbild wird, das keinen Gegenbeweis mehr zulässt: Jeder Widerspruch gilt dann als Teil der Verschwörung, wie bei Ben. Ein zweites Kriterium kommt hinzu: wenn der Glaube an die Verschwörung wichtiger wird als persönliche Beziehungen und die eigene Sicherheit; auch das trifft auf Ben zu, der den Kontakt zu seiner Schwester abgebrochen hat. Die Ansicht, Misstrauen sei an sich verdächtig, verwechselt das Merkmal mit dem Muster und würde auch Annas berechtigte Prüfung verurteilen. Ein guter Anlass am Anfang schützt nicht davor, später zu kippen, wie Bens Fall zeigt. Und wiederholter Zweifel ist kein Kriterium, denn auch Anna zweifelte an den neuen Zahlen und blieb dabei offen für Belege.","coreRule":"⚡ Misstrauen darf prüfen; es darf nur nicht jeden Gegenbeweis ausschließen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Zwei Bekannte misstrauen dem Gesundheitsamt, seit es im Vorjahr falsche Fallzahlen genannt hatte. Anna zweifelt auch die neuen Zahlen an, prüft sie aber anhand der veröffentlichten Rohdaten nach und ändert ihre Meinung, als diese die Zahlen bestätigen. Ben erklärt dieselben Rohdaten für gefälscht, deutet jeden weiteren Beleg als Teil der Vertuschung und hat deswegen den Kontakt zu seiner Schwester abgebrochen. Ein Freund meint: „Beide stecken schon halb im Kaninchenbau, Misstrauen gegenüber Behörden ist an sich verdächtig.“","kurz":"Entscheidend ist, was aus dem Misstrauen wird: Anna prüfte nach und ließ sich korrigieren. Bei Ben gilt jeder Beleg als Vertuschung, und er hat den Kontakt zur Schwester abgebrochen. Misstrauen allein ist kein Kipppunkt.","prueffrage":"Was geschieht mit dem jeweiligen Misstrauen, wenn die Rohdaten die Zahlen bestätigen?","rueckmeldung":[{"option":0,"text":"Beide misstrauen demselben Amt, daher liegt der Vergleich nahe. Misstrauen allein ist aber kein Warnsignal, denn nach den falschen Zahlen war Skepsis berechtigt, und Anna zeigt, dass sie sich korrigieren lässt. Das Muster liegt im Umgang mit Belegen."},{"option":2,"text":"Ein guter Anlass ist hier tatsächlich gegeben, und der Zweifel am Anfang war berechtigt. Er schützt aber nicht davor, später zu kippen: Ben lässt keinen Gegenbeweis mehr gelten und hat den Kontakt zur Schwester abgebrochen."},{"option":3,"text":"Dass nur Ben kippt, stimmt, und er zweifelt auch an den neuen Zahlen. Wiederholter Zweifel ist aber kein Kriterium: Auch Anna zweifelte an den neuen Zahlen und blieb offen für Belege. Entscheidend ist, ob Gegenbelege noch etwas ändern können."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Kasten „Conventional vs. Conspiratorial Thinking“; Abschnitt CONSPIR","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f96e925b26bc1b14"}},{"id":"qx-f-020","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":4,"question":"Welche Antwort wird der Lage am besten gerecht?","scenario":"Ein Bekannter erzählt dir, seine Schwägerin sei „komplett paranoid“, nur weil sie eine bekannte Online-Verschwörungserzählung glaubt. Du hast die Erzählung mit einer Liste typischer Warnsignale geprüft (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und weitere) und festgestellt, dass sie mehrere davon erfüllt.","options":["Die Erzählung erfüllt mehrere Warnsignale, aber das ist ein Befund über die Erzählung und ihren Denkstil, nicht über den seelischen Gesundheitszustand der Schwägerin.","Die Warnsignale zeigen nur, dass die Erzählung schlecht prüfbar gebaut ist; ob sie stimmt, entscheidet sich erst, wenn man ihre einzelnen Behauptungen an Quellen überprüft.","Die Warnsignale zeigen, dass die Schwägerin die Erzählung nicht kritisch geprüft hat, denn wer mehrere Warnsignale übersieht, hat sich mit der Erzählung kaum befasst.","Die Herkunft einer Erzählung gehört ebenfalls zu den Prüfpunkten; deshalb solltest du als Nächstes klären, wer sie verbreitet und ob er Belege vorlegt."],"correctIndex":0,"explanation":"Die Warnsignale (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und ähnliche) beschreiben Eigenschaften einer Erzählung: Wie ist sie gebaut, und lässt sie sich überhaupt prüfen? Daraus folgt nichts über den Gesundheitszustand eines Menschen, der sie glaubt. Auch die Fachwelt trennt hier: Psychiater müssen Überzeugungen aus Verschwörungserzählungen erst von Wahn und wahnähnlichen Überzeugungen unterscheiden (Holoyda 2022, Journal of the American Academy of Psychiatry and the Law); meist ist Verschwörungsglaube ein Denkstil und kein Wahn, und ob im Einzelfall mehr dahintersteckt, kann nur eine fachliche Untersuchung klären. Wer aus „glaubt eine unbelegbare Geschichte“ auf „ist krank“ schließt, springt von einer Eigenschaft der Erzählung auf eine Eigenschaft der Person und etikettiert, statt zu prüfen. Ob eine Erzählung stimmt, klärt erst die Prüfung ihrer einzelnen Behauptungen, doch der Bekannte urteilt über die Schwägerin und nicht über den Wahrheitsgehalt. Aus der Zahl der Warnsignale folgt auch nicht, dass die Schwägerin sie übersehen hätte, denn sie kann sie gekannt und anders gewichtet haben. Und die Herkunft der Erzählung zu klären ist ein guter weiterer Prüfschritt, beantwortet aber nicht, ob das Etikett „paranoid“ berechtigt ist.","coreRule":"⚡ Wir sezieren die Erzählung und ihren Denkstil, wir stellen keine Diagnosen über Menschen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt); Fn. gl-f-wahn (Holoyda 2022, JAAPL 50(1), S. 124--135)","status":"entwurf","kurz":"Die Warnsignale beschreiben, wie die Erzählung gebaut ist und ob sie sich prüfen lässt, nicht, ob ihre Anhängerin seelisch gesund ist. Wer von „glaubt Unbelegbares“ auf „ist krank“ schließt, springt von der Erzählung auf die Person.","prueffrage":"Was weißt du über die Schwägerin außer der Tatsache, dass sie diese Erzählung glaubt?","rueckmeldung":[{"option":1,"text":"Das ist richtig: Ob eine Erzählung stimmt, zeigt erst die Prüfung ihrer Behauptungen. Der Bekannte urteilt aber gar nicht über den Wahrheitsgehalt, sondern über die Schwägerin, und genau diese Frage lässt die Antwort offen."},{"option":2,"text":"Viele Warnsignale legen nahe, dass jemand nicht genau hingesehen hat. Das lässt sich aber nicht daraus schließen: Die Schwägerin kann sie gekannt und anders gewichtet haben. Auch das wäre ein Urteil über die Person, das die Warnsignale nicht tragen."},{"option":3,"text":"Die Herkunft einer Erzählung zu klären ist tatsächlich ein sinnvoller weiterer Prüfschritt. Er sagt aber nichts darüber, ob das Wort „paranoid“ für die Schwägerin berechtigt ist, und beantwortet damit nicht die gestellte Frage."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Holoyda, B. J. (2022): „The QAnon Conspiracy Theory and the Assessment of Its Believers“, Journal of the American Academy of Psychiatry and the Law 50(1)","oeffentlich":true,"url":"https://jaapl.org/content/50/1/124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1d5bd5d2d1c57dc3"}},{"id":"qx-f-021","clusterId":"F","werkstueckRef":"F.1.4","stufe":1,"question":"Ein Freund nennt eine Gruppe einen Kult, weil sie an Engel glaubt. Woran würdest du stattdessen prüfen, ob die Gruppe ihre Mitglieder manipulativ kontrolliert?","options":["Daran, wie die Gruppe ihre Mitglieder behandelt, denn dort zeigt sich, ob sie deren Kontakte, Informationen, Denken und Gefühle steuert.","Daran, ob sich die Existenz von Engeln belegen lässt, denn das zeigt, ob die Lehre der Gruppe über die Welt zutrifft oder nicht.","Daran, wie viele Mitglieder die Gruppe hat und wie lange es sie schon gibt, denn das zeigt, ob sie eine etablierte Gemeinschaft ist.","Daran, woher die Engelrituale der Gruppe geschichtlich stammen, denn das zeigt, ob ihre Bräuche auf alte Überlieferungen zurückgehen."],"correctIndex":0,"explanation":"Ob eine Gruppe ihre Mitglieder manipulativ kontrolliert, zeigt sich nicht an dem, was sie glaubt, sondern an dem, was sie mit ihren Mitgliedern macht. Geprüft werden Struktur und Verhalten: Wird bestimmt, mit wem man Umgang haben darf? Werden kritische Informationen abgeschnitten? Wird Zweifel bestraft? Werden Angst und Schuld als Druckmittel eingesetzt? Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen. Und selbst wenn einzelne Merkmale zutreffen, ist nicht jede enge Gemeinschaft ein Kult: Je mehr Kontrollmerkmale in hoher Intensität zusammenkommen, desto eher ist der Einfluss manipulativ.","coreRule":"⚡ Nicht was eine Gruppe glaubt, sondern wie sie ihre Mitglieder kontrolliert, entscheidet über den Kultverdacht.","beleg":"Werkstück F.1.4 (Kontext & Tiefe: Das BITE-Modell der Gedankenkontrolle)","status":"entwurf","scenario":"Im Gespräch fällt der Satz: „Die glauben an Engel, das ist doch ein Kult!“ Über das Verhalten der Gruppe gegenüber ihren Mitgliedern weißt du noch nichts.","quote":"","quoteLabel":"","kurz":"Ob eine Gruppe manipuliert, zeigt sich an ihrem Umgang mit den Mitgliedern: Kontakte, Informationen, Zweifel, Druck. Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Unbelegbares.","prueffrage":"Welche anderen, als harmlos geltenden Gemeinschaften glauben ebenfalls an Engel?","rueckmeldung":[{"option":1,"text":"Ob sich Engel belegen lassen, beantwortet, ob die Lehre stimmt, aber nicht, wie die Gruppe mit ihren Mitgliedern umgeht. Auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen."},{"option":2,"text":"Größe und Alter zeigen, wie etabliert eine Gruppe ist, und das ist ein echtes Merkmal. Über Kontrolle sagt es aber nichts: Auch große, alte Gruppen können Mitglieder steuern, kleine können fair mit ihnen umgehen."},{"option":3,"text":"Woher die Rituale stammen, erklärt ihre Geschichte, nicht den Umgang mit den Mitgliedern. Eine alte Überlieferung entlastet eine Gruppe nicht, eine junge belastet sie nicht; entscheidend ist ihr Verhalten."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"cd640f6028f31374"}},{"id":"qx-f-022","clusterId":"F","werkstueckRef":"F.1.4","stufe":2,"question":"Was ist an diesem Verhalten der Gruppe das eigentlich Auffällige und Prüfenswerte?","scenario":"Du gehst zu einem Vertriebsevent, weil dich eine Bekannte eingeladen hat. Dort wirst du mit Aufmerksamkeit und Lob überschüttet. Ein paar Wochen später heißt es, deine skeptischen Freunde „gönnen dir deinen Erfolg nicht“, und du solltest den Kontakt zu ihnen herunterfahren.","options":["Die Gruppe überschüttet dich zuerst mit Lob und wertet dann deine skeptischen Freunde ab, sodass du von deren Einwänden abgeschnitten wirst.","Die Gruppe überschüttet dich auf dem Event mit Lob, sodass du ihr Angebot in dieser Hochstimmung deutlich weniger kritisch prüfst als sonst.","Die Gruppe sagt, deine Freunde gönnten dir den Erfolg nicht, sodass vor allem zu prüfen ist, ob deren Skepsis tatsächlich aus Neid kommt.","Die Gruppe holt dich über eine Bekannte zum Event, sodass du ihr aus persönlicher Verbundenheit eher vertraust als einem völlig fremden Anbieter."],"correctIndex":0,"explanation":"Auffällig ist die Kombination aus „Love Bombing“ und der Isolation von kritischen Freunden: Erst gibt es überschwängliche Zuwendung, dann heißt es „Die gönnen dir deinen Erfolg nicht“. Genau dadurch fehlen dir die Menschen, die Einwände äußern würden. Das ist ein Kontrollmuster, kein Zufall: Wer Bindung durch Zuwendung aufbaut und zugleich Kritiker abwertet, macht dich von der Gruppe abhängig. Ob eine Gruppe dir guttut, erkennst du daran, ob sie dein unabhängiges Denken und deine Beziehungen stärkt oder ob sie verlangt, beides zurückzufahren.","coreRule":"⚡ Überschwängliche Zuwendung plus Abkopplung von Kritikern ist ein Kontrollmuster, kein Zufall.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Kommerzielle Kulte; BITE: Emotional Control)","status":"entwurf","kurz":"Auffällig ist die Abfolge: erst überschwängliche Zuwendung, dann die Abwertung deiner skeptischen Freunde. Einzeln wirkt beides harmlos, zusammen entfernt es die Menschen, die Einwände äußern würden, und bindet dich an die Gruppe.","prueffrage":"Woher weiß die Gruppe, warum deine Freunde skeptisch sind, und hat sie je mit ihnen gesprochen?","rueckmeldung":[{"option":1,"text":"Starkes Lob kann die Prüfung tatsächlich lockern, das ist ein Teil der Geschichte. Es erklärt aber nicht, warum Wochen später über deine Freunde gesprochen wird und du den Kontakt herunterfahren sollst."},{"option":2,"text":"Ob die Skepsis der Freunde aus Neid kommt, lässt sich fragen. Wichtiger ist, wozu der Satz dient: Er stellt Kritiker als befangen dar und legt nahe, ihre Einwände nicht mehr zu hören."},{"option":3,"text":"Vertrauen über eine Bekannte ist verständlich, und eine Einladung allein ist noch kein Warnzeichen. Das Prüfenswerte zeigt sich erst später: im überschwänglichen Lob und darin, wie die Gruppe über deine Freunde spricht."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ec7bb885dc0d89ff"}},{"id":"qx-f-023","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Was spricht am stärksten gegen den Plan der Behörde?","options":["Die Studie zeigt nur, dass die Punkte zusammenpassen, nicht dass sie Manipulation messen; sie stammt vom Entwickler, und ein Ja zeigt noch keine Intensität.","Die Studie stützt die Liste zwar, doch die Behörde müsste vor dem Einsatz festlegen, ab wie vielen Ja-Antworten eine Gruppe als manipulativ gilt.","Die Ja-Antworten bei Chor, Sportverein und Kloster zeigen, dass die Liste falsch misst, denn solche Gruppen hält kaum jemand für manipulativ.","Der Entwickler war selbst Aussteiger und berät heute Betroffene; bei so viel eigener Betroffenheit fehlt ihm der neutrale Blick für ein amtliches Messinstrument."],"correctIndex":0,"explanation":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; dass die Punkte einer Liste in sich stimmig sind, zeigt nur, dass sie zusammenpassen, nicht dass sie das Gemeinte zuverlässig messen. Dafür braucht es eine unabhängige Prüfung, und die fehlt hier. Hinzu kommt: Ein Teil der beschriebenen Kontrolle gehört unvermeidlich zu jeder Gemeinschaft (so die Enquete-Kommission des Bundestages 1998), entscheidend sind Intensität und Verlust der Selbstbestimmung; die Ja-Antworten bei Chor, Sportverein und Kloster beweisen deshalb noch keine Manipulation. Als Orientierungshilfe in der Beratung kann die Liste nützlich sein, als verbindliche amtliche Messlatte reicht sie nicht.","coreRule":"⚡ Als Checkliste brauchbar, als Messlatte ungeeignet: Wer das eigene Instrument selbst prüft, liefert keine unabhängige Prüfung, und entscheidend sind Intensität und Verlust der Selbstbestimmung.","beleg":"Werkstück F.1.4 (Das BITE-Modell); Fn. gl-f-6; Fn. gl-f-enquete (Bundestag 1998, Drucksache 13/10950, S. 77)","status":"entwurf","scenario":"Eine Behörde will Gruppen amtlich als manipulativ einstufen und dafür eine Merkmalsliste als verbindliches Messinstrument nutzen. Entwickelt hat sie ein früherer Sektenaussteiger, der heute Betroffene berät; die Liste fragt Kontrolle über Verhalten, Information, Gedanken und Gefühle ab. Als Beleg für ihre Zuverlässigkeit führt er eine eigene Fragebogenstudie an, nach der die Punkte der Liste in sich stimmig sind. In einem Probelauf erhalten auch ein Chor, ein Sportverein und ein Kloster bei einzelnen Punkten ein Ja.","kurz":"Eine Liste, deren Punkte nur zusammenpassen, ist noch nicht gültig: Dass sie Manipulation misst, müsste jemand Unabhängiges prüfen, nicht ihr Entwickler. Auch ein Ja bei Chor oder Kloster zeigt allein keine Manipulation.","prueffrage":"Wer hat die Zuverlässigkeit der Liste geprüft, und wäre das Ergebnis auch bei einer Prüfung durch Dritte so ausgefallen?","rueckmeldung":[{"option":1,"text":"Eine feste Schwelle brauchte ein amtliches Instrument tatsächlich. Sie ersetzt aber nicht den Nachweis, dass die Liste Manipulation misst; die Studie des Entwicklers zeigt nur, dass ihre Punkte zusammenpassen, und unabhängig geprüft wurde nichts."},{"option":2,"text":"Die Ja-Antworten bei Chor, Sportverein und Kloster machen stutzig, widerlegen die Liste aber nicht. Ein Teil dieser Kontrolle gehört zu jeder Gemeinschaft; entscheidend sind Intensität und Verlust der Selbstbestimmung, und die erfasst ein einzelnes Ja nicht."},{"option":3,"text":"Seine Biografie kann den Blick färben, belegt aber noch keinen Mangel der Liste. Das Problem liegt nicht in seiner Person, sondern im Verfahren: Er hat die Liste entwickelt und selbst geprüft, eine unabhängige Prüfung fehlt."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hassan, S. A. (2020): The BITE Model of Authoritarian Control. Diss. Fielding Graduate University","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"03761a2c9eb32c40"}},{"id":"qx-f-024","clusterId":"F","werkstueckRef":"F.1.4","stufe":4,"question":"Eine Person bestimmt, mit wem ihr Partner Umgang hat, verwaltet dessen Geld allein und macht dessen Freunde schlecht. Eine Bekannte meint: „Kontrolle in dieser Form gibt es nur in Sekten, in einer Zweierbeziehung kann das gar nicht passieren.“ Welche Antwort trifft den Denkfehler am besten?","options":["Sie schließt von der bekanntesten Form auf die einzige: Nicht die Gruppengröße entscheidet, sondern ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen.","Sie achtet auf das falsche Merkmal: Nicht die Gruppengröße entscheidet, sondern ob körperliche Gewalt hinzukommt; ohne sie ist das Geschilderte eher ein Machtgefälle als echte Kontrolle.","Sie legt den falschen Maßstab an: Nicht die Gruppengröße entscheidet, sondern ob der Partner widerspricht; nimmt er das Geschilderte hin, ist es eher eine Absprache als echte Kontrolle.","Sie legt die Schwelle zu hoch: Nicht die Gruppengröße entscheidet, sondern ob einer allein bestimmt; dass hier einer das Geld allein verwaltet, genügt schon, um von echter Kontrolle zu sprechen."],"correctIndex":0,"explanation":"Die Bekannte schließt von der bekanntesten Form (Sekte) auf die einzige Form. Entscheidend ist aber die Struktur: Wer Kontakte einschränkt, finanzielle Abhängigkeit schafft und Freunde abwertet, isoliert den anderen und entzieht ihm andere Informations- und Rückhalt-Quellen. Das sind dieselben Kontrollmechanismen, die man bei manipulativen Gruppen beobachtet, nur im Format einer Zweierbeziehung. Dafür braucht es weder einen Anführer noch eine Gruppe. Dabei gilt: Ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft, problematisch wird es erst bei systematischer Isolation, Abhängigkeit und Manipulation.","coreRule":"⚡ Prüfe die Struktur der Kontrolle (Umgang, Geld, Information, Gefühle), nicht die Größe oder das Etikett der Gruppe.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Missbräuchliche Beziehungen)","status":"entwurf","scenario":"","kurz":"Kontrollmechanismen wie Isolation, finanzielle Abhängigkeit und Abwertung von Freunden brauchen weder Gruppe noch Anführer. Der Fehler ist, von der bekanntesten Form (Sekte) auf die einzige zu schließen.","prueffrage":"Welcher der drei Schritte, die die Person unternimmt, wäre ohne eine Gruppe im Hintergrund nicht möglich?","rueckmeldung":[{"option":1,"text":"Körperliche Gewalt ist ein ernstes Zeichen, aber keine Voraussetzung: Wer Kontakte lenkt, Geld allein verwaltet und Freunde schlechtmacht, kontrolliert auch ohne Schläge, und zwar durch Isolation und Abhängigkeit."},{"option":2,"text":"Fehlender Widerspruch wirkt wie Zustimmung. Wer aber isoliert und finanziell abhängig ist, hat oft kaum Rückhalt oder Alternativen zum Widersprechen; Schweigen sagt hier wenig über Einvernehmen."},{"option":3,"text":"Das allein verwaltete Geld ist ein ernstes Warnzeichen, doch ein einzelnes Merkmal genügt nicht pauschal, denn ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft. Entscheidend ist das Zusammenspiel von Isolation, Abhängigkeit und Abwertung."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Crown Prosecution Service: „Controlling or Coercive Behaviour in an Intimate or Family Relationship“ (Leitlinie, Stand 07.02.2025)","oeffentlich":true,"url":"https://www.cps.gov.uk/legal-guidance/controlling-or-coercive-behaviour-intimate-or-family-relationship","abruf":"2026-10-12"},{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"99f13b22914f63fc"}},{"id":"qx-f-025","clusterId":"F","werkstueckRef":"F.1.5","stufe":1,"question":"Welche Frage hilft dir am besten, bei einer beeindruckend aussehenden „Studie“ zu prüfen, ob sie echte Forschung ist oder nur deren äußere Form nachahmt?","options":["Ob die Zahlen im Bericht rechnerisch stimmen und ob die Grafiken sauber beschriftet und nachvollziehbar aufgebaut sind","Ob das Institut ein Impressum mit Adresse hat und ob die Autoren mit „Dr.“ öffentlich auffindbar und überprüfbar sind","Ob der Bericht auch Ergebnisse nennt, die der Behauptung widersprechen, und ob andere Forscher sie wiederholen konnten","Ob der Bericht die Fachbegriffe korrekt verwendet und durchgehend sachlich bleibt, ohne jede Werbesprache oder Übertreibung"],"correctIndex":2,"explanation":"Jargon, Grafiken, Titel und Institutsnamen lassen sich leicht nachahmen, sie sagen nichts darüber, ob die Methode taugt. Entscheidend ist die selbstkritische Redlichkeit: Echte Forschung berichtet auch Belege, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen. Ob unabhängige Forscher das Ergebnis wiederholen können, zeigt, ob mehr dahintersteckt als eine schön gebaute Hülle. Der Physiker Richard Feynman nannte dieses Muster „Cargo-Kult-Wissenschaft“: Inselbewohner bauten nach dem Zweiten Weltkrieg Landebahnen, Feuer und Holz-Kopfhörer nach, um Flugzeuge zurückzulocken. Die Form stimmte, das Verständnis fehlte, und die Flugzeuge blieben aus.","coreRule":"⚡ Nicht das Aussehen, sondern die Redlichkeit macht Wissenschaft aus: Frag nach Gegenbelegen und Wiederholbarkeit, nicht nach Jargon und Titeln.","beleg":"Werkstück F.1.5 (Kernidee; Kontext & Tiefe); Fn. gl-f-7 (Feynman 1974, Caltech-Rede)","status":"entwurf","scenario":"Ein Institut, das du nicht kennst, veröffentlicht einen Bericht mit Fachjargon, vielen Grafiken und Titeln wie „Dr.“. Der Bericht stützt eine Behauptung, die dir zweifelhaft vorkommt.","kurz":"Ob ein Bericht auch Belege gegen die eigene Behauptung nennt und ob andere Forscher das Ergebnis wiederholen konnten, zeigt echte Forschung. Jargon, Titel und Grafiken lassen sich nachbauen, wie die Landebahnen im Cargo-Kult: Die Form stimmt, das Verständnis fehlt.","prueffrage":"Welche der Merkmale, die dich an dem Bericht beeindrucken, könnte auch jemand ohne echte Daten herstellen?","rueckmeldung":[{"option":0,"text":"Stimmige Zahlen und saubere Grafiken sind ein sinnvoller erster Check, grobe Fehler wären ein Warnsignal. Beides lässt sich aber ebenso nachbauen wie Jargon und sagt nicht, ob die Methode taugt oder Widersprechendes verschwiegen wurde."},{"option":1,"text":"Ein Impressum und auffindbare Autoren zeigen, dass es das Institut gibt und Verantwortliche greifbar sind. Ob dort sauber geforscht wird, folgt daraus nicht, denn auch Titel und Institutsnamen gehören zur nachahmbaren äußeren Form."},{"option":3,"text":"Korrekt gebrauchte Fachbegriffe in nüchternem Ton wirken seriös, gehören aber gerade zur äußeren Form, die sich leicht übernehmen lässt. Werbesprache kann misstrauisch machen, ihr Fehlen belegt jedoch keine gute Methode."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e5c3cf3e9faed809"}},{"id":"qx-f-026","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Wie bewertest du das Vorgehen der Gruppe?","scenario":"Eine Forschungsgruppe testet Telepathie in 40 Versuchsreihen. Veröffentlicht werden die drei Reihen mit auffälligem Treffer, die übrigen 37 verschwinden in der Schublade. Ein Kollege sagt: „Drei klare Treffer sind doch ein Ergebnis. Es steht ja alles korrekt in der Veröffentlichung.“","options":["Als vertretbar, denn die drei Treffer sind korrekt wiedergegeben; unredlich wäre erst, Daten zu fälschen, und gefälscht wurde bei den 40 Versuchsreihen nichts.","Als lückenhaft, aber verständlich, denn Reihen ohne Treffer zeigen nichts Neues; wer in 37 Reihen nichts gefunden hat, hat davon auch wenig zu berichten.","Als Nachahmung von Forschung ohne ihren Kern, denn wer nur drei Treffer zeigt und 37 Fehlschläge verschweigt, täuscht ein Ergebnis vor, das das Ganze nicht trägt.","Als vorläufig ernst zu nehmen, denn drei Treffer sind mehr als keiner; ob der Effekt hält, zeigt sich dann, wenn andere Gruppen genau diese drei Reihen wiederholen."],"correctIndex":2,"explanation":"Aussagekraft hat erst das Gesamtbild aller Versuche, nicht die herausgepickten Treffer. Wer nur die drei Treffer zeigt und die 37 Fehlschläge verschweigt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben. Redliche Forschung berichtet auch über alles, was der eigenen Hypothese widerspricht. Fachsprache, Versuchsaufbau und Veröffentlichung können dann perfekt aussehen, und trotzdem fehlt der Kern der Wissenschaft: die Bereitschaft, die eigene Idee scheitern zu sehen. Feynman nannte das Cargo-Kult-Wissenschaft: Die Landebahn steht, aber die Flugzeuge der Erkenntnis landen dort nicht. Die Pflicht, auch widersprechende Ergebnisse zu berichten, besteht unabhängig davon, ob die Gruppe von Beweis spricht. Dass die drei Treffer für sich richtig wiedergegeben sind, klingt nach Redlichkeit, doch das Verschweigen der übrigen Reihen täuscht auch ohne gefälschte Zahl.","coreRule":"⚡ Wer Fehlschläge verschweigt, baut nur die Landebahn, aber keine Wissenschaft.","beleg":"Werkstück F.1.5 (Anwendung & Relevanz: In der Parapsychologie)","status":"entwurf","kurz":"Aussagekraft hat erst das Gesamtbild aller 40 Reihen, nicht die drei herausgepickten Treffer. Korrekt wiedergegebene Einzelwerte sind noch keine Redlichkeit: Wer die 37 Fehlschläge verschweigt, täuscht einen Effekt vor.","prueffrage":"Wie viele auffällige Treffer würde man bei 40 Versuchsreihen allein durch Zufall erwarten?","rueckmeldung":[{"option":0,"text":"Dass die drei Treffer korrekt wiedergegeben sind und nichts gefälscht wurde, stimmt. Täuschen lässt sich aber auch mit richtigen Zahlen: Das Verschweigen der 37 übrigen Reihen erzeugt den Eindruck eines Effekts, den die Daten nicht hergeben."},{"option":1,"text":"Reihen ohne Treffer bringen tatsächlich keine Schlagzeile. Sie gehören aber zum Gesamtbild: Erst mit ihnen lässt sich beurteilen, ob drei Treffer unter 40 Reihen überhaupt etwas Besonderes sind."},{"option":3,"text":"Dass andere Gruppen Ergebnisse nachprüfen, ist sinnvoll. Hier greift es zu kurz: Die drei Treffer sind schon eine Auswahl aus 40 Reihen, und ohne die übrigen 37 lässt sich nicht sagen, ob sie überhaupt ernst zu nehmen sind."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ef7c592cc179ae29"}},{"id":"qx-f-027","clusterId":"F","werkstueckRef":"F.1.5","stufe":3,"question":"Dein Kollege sagt dazu: „Unseriöse Forschung gibt es nur bei Homöopathen und Parapsychologen. Was an einer Hochschule veröffentlicht wird, hat Institut, Fachjargon und Peer-Review, also ist es automatisch Wissenschaft.“ Was ist an diesem Schluss fehlerhaft?","options":["Er schließt von der äußeren Form auf die Qualität: Institut, Fachjargon und Peer-Review sagen noch nichts darüber, ob die Forschenden ihre eigenen Ideen ernsthaft scheitern lassen wollten.","Er überschätzt nur das Peer-Review: Gutachten fangen viele Fehler ab, aber nicht alle; mit dieser Einschränkung wären Institut und Fachjargon ein guter Hinweis auf die Qualität einer Studie.","Er stellt eine falsche Zweiteilung auf: Er teilt die Forschung in Hochschulen und Homöopathen, obwohl es auch andere Einrichtungen gibt, deren Forschung ebenso seriös sein kann.","Er schließt von bekannten Beispielen auf alle Fälle: Weil Homöopathie und Parapsychologie als unseriös gelten, hält er unseriöse Forschung anderswo für ausgeschlossen, ohne danach gesucht zu haben."],"correctIndex":0,"explanation":"Der Kollege verwechselt die äußere Form der Wissenschaft mit ihrer Substanz. Ob Forschung trägt, entscheidet sich an der selbstkritischen Redlichkeit: Werden Gegenbelege gesucht und berichtet, gibt es Kontrollgruppen, ist das Ergebnis wiederholbar? Das gilt überall, auch an Hochschulen. Richard Feynman nannte in seiner Rede „Cargo Cult Science“ (1974) ausdrücklich auch Studien zu Lesemethoden und Rattenversuche der Psychologie, die die sorgfältigen Kontrollen eines vorbildlichen Vorgängers nicht beachteten, als Beispiele für Forschung, die nur die Form der Wissenschaft wahrt. Sein Fehler ist, die Form als Beweis der Substanz zu nehmen.","coreRule":"⚡ Ein Titel, ein Institut und Fachjargon beweisen keine Redlichkeit: Prüfe die Methode, nicht das Etikett.","beleg":"Werkstück F.1.5 (Kernidee); Fn. gl-f-7 (Quelle der Feynman-Rede „Cargo Cult Science“, 1974)","status":"entwurf","scenario":"Ihr sprecht über eine Schlagzeile zu einer neuen Studie, die an einer Universität entstanden ist.","kurz":"Institut, Fachjargon und Peer-Review beschreiben nur die äußere Form. Ob Forschung trägt, zeigt sich daran, ob Gegenbelege gesucht, Kontrollen eingesetzt und Ergebnisse wiederholbar sind, auch an Hochschulen.","prueffrage":"Ist schon einmal eine Hochschulstudie mit Peer-Review später zurückgezogen worden oder bei der Wiederholung gescheitert?","rueckmeldung":[{"option":1,"text":"Dass Gutachten nicht alle Fehler finden, stimmt. Aber auch mit dieser Einschränkung wären Institut und Fachjargon kein guter Hinweis: Sie sind äußere Merkmale und zeigen nicht, ob Gegenbelege gesucht und Kontrollen sorgfältig durchgeführt wurden."},{"option":2,"text":"Daran stimmt: Seriöse Forschung gibt es auch außerhalb von Hochschulen. Das trifft aber nicht den Kern. Selbst mit mehr Einrichtungen bliebe der Schluss falsch, dass Institut und Fachjargon schon Wissenschaft belegen; es kommt auf die Redlichkeit der Arbeit an."},{"option":3,"text":"Ein Schluss von wenigen bekannten Fällen auf alle wäre wirklich zu voreilig. Der eigentliche Fehler liegt aber tiefer: Selbst nach gründlicher Suche wäre die Form kein Beweis für Substanz, und auch an Hochschulen gibt es Studien, die nur die Form wahren."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 10, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"319810330ab94679"}},{"id":"qx-f-028","clusterId":"F","werkstueckRef":"F.1.6","stufe":1,"question":"Ein Bekannter sagt: „Meine Schwester ist Ärztin und gewohnt, Behauptungen kritisch zu prüfen. Seit dem Tod ihres Mannes schwört sie auf einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt. Ausgerechnet sie fällt auf so etwas nie herein, da muss etwas dran sein.“ Welcher Schluss ist am besten begründet?","options":["Ihre Überzeugung spricht für eine echte Wirkung des Heilers, denn wer nach einem solchen Verlust so fest an etwas hält, hat dort offenbar etwas Tragendes erlebt.","Ihre Überzeugung spricht kaum für den Heiler, denn auch geübte Prüfer setzen die Prüfung leicht aus, wenn ein Verlust wie dieser ein tiefes Bedürfnis berührt.","Ihre Erfahrung spricht dafür, dass Kontakt möglich ist, solange niemand gezeigt hat, dass der Heiler ihn nicht herstellen kann; die Beweislast liegt bei den Zweiflern.","Ihre Berufserfahrung macht sie zur verlässlichen Prüferin, denn wer täglich Behauptungen kritisch prüft, erkennt auch bei einem Heiler eher, was echt ist und was nicht."],"correctIndex":1,"explanation":"Intelligenz oder Fachkompetenz belegen nicht, dass eine Überzeugung stimmt. Das zeigt der Fall des Schriftstellers Arthur Conan Doyle: Der Schöpfer des kühlen Logikers Sherlock Holmes hielt nach den Verlusten im Ersten Weltkrieg die inszenierten „Cottingley Fairies“-Fotos trotz ihrer Fälschung für Zeugnisse einer unsichtbaren Lebensform, öffentlich vorsichtig als starken ersten Anschein, privat als erwiesen. Kritisches Denken ist keine feste Eigenschaft, sondern eine Praxis, die bewusst angewendet werden muss; niemand ist durch Intelligenz oder Skepsis dauerhaft immun. Ein überwältigendes Bedürfnis nach Trost oder Hoffnung kann sie ausgerechnet bei der eigenen Überzeugung abschalten, und dann dient der Verstand als Anwalt für den Glauben statt als Prüfer. Der Verweis auf ihre Kompetenz hilft also nicht weiter; entscheidend ist, ob die Behauptung selbst einer Prüfung standhält. Dass niemand das Gegenteil bewiesen hat, ist kein Beleg, denn wer etwas behauptet, muss es belegen. Und die Routine einer Ärztin im Prüfen von Behauptungen gilt für ihren Beruf; sie schützt nicht davor, dass ein tiefes Bedürfnis die Prüfung bei der eigenen Überzeugung aussetzt.","coreRule":"⚡ Skepsis ist eine Praxis, keine Eigenschaft: Sie muss gerade dort angewendet werden, wo es weh tut.","beleg":"Werkstück F.1.6 (Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von seiner Schwester, einer erfahrenen Ärztin. Sie ist es gewohnt, Behauptungen kritisch zu prüfen, glaubt aber seit dem Tod ihres Mannes fest an einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt.","quote":"","quoteLabel":"","kurz":"Fachkompetenz belegt nicht, dass eine Überzeugung stimmt: Ein tiefes Bedürfnis nach Trost kann auch geübte Prüfer dazu bringen, ausgerechnet bei der eigenen Überzeugung nicht zu prüfen. Entscheidend ist, ob die Behauptung selbst standhält.","prueffrage":"Welche Belege für die Fähigkeiten des Heilers gibt es außer der Überzeugung der Ärztin selbst?","rueckmeldung":[{"option":0,"text":"Dass sie so fest daran hält, ist real, zeigt aber vor allem, wie stark das Bedürfnis nach Trost nach diesem Verlust ist. Es erklärt das Festhalten auch dann, wenn der Heiler selbst nichts bewirkt."},{"option":2,"text":"Dass niemand das Gegenteil gezeigt hat, ist noch kein Beleg. Wer eine Behauptung aufstellt, muss sie belegen; die Beweislast liegt nicht bei den Zweiflern. Auch ihre Erfahrung ist hier ja gerade die Überzeugung, die geprüft werden soll."},{"option":3,"text":"Ihre Routine im Prüfen von Behauptungen ist echt und nützlich. Sie gilt aber für ihren Beruf und schützt nicht davor, dass ein tiefes Bedürfnis die Prüfung bei der eigenen Überzeugung aussetzt. Niemand ist durch Skepsis dauerhaft immun."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II (Strand-Artikel: „strong prima facie case“) und Kap. IV (Brief an Gardner: „You and I needed no confirmation“) (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d2effaa04e67af68"}},{"id":"qx-f-029","clusterId":"F","werkstueckRef":"F.1.6","stufe":2,"question":"Was zeigt dieser Unterschied am ehesten?","options":["Er schwankt noch zwischen Hoffnung und Zweifel; im vertrauten Brief überwiegt bei ihm die Hoffnung, in der Öffentlichkeit eher der Zweifel.","Er spitzt im Brief nur zu, wie man es unter Gleichgesinnten tut; seine eigentliche Einschätzung ist die vorsichtige öffentliche.","Er hat seine Überzeugung längst gefasst und gibt sich nach außen nur vorsichtig, statt die dünnen Belege ergebnisoffen zu prüfen.","Er passt sich dem jeweiligen Publikum an und sagt, was es hören will; eine feste eigene Meinung hat er sich noch nicht gebildet."],"correctIndex":2,"explanation":"Die vorsichtige öffentliche Formulierung und die private Gewissheit passen nicht zusammen. Das spricht dafür, dass die Überzeugung innerlich schon feststeht und die Vorsicht nach außen eher Zurückhaltung oder Taktik ist. Die Belege werden dann eher verteidigt als ergebnisoffen geprüft. Hohe Intelligenz schützt davor nicht: Sie liefert dann bloß bessere Argumente für das, was man ohnehin glauben will. Gerade bei Behauptungen, die ein tiefes persönliches Bedürfnis berühren, lohnt es sich daher, genau auf diese Diskrepanz zu achten. Ein Beispiel ist Arthur Conan Doyle, der Schöpfer von Sherlock Holmes: Öffentlich sprach er von einem „starken ersten Anschein“ der Cottingley-Feenfotos (Strand-Artikel vom Dezember 1920), im Brief an seinen Mitstreiter E. L. Gardner vom Oktober 1920 hielt er die Sache dagegen für erwiesen und hoffte, sie werde den Materialismus brechen.","coreRule":"⚡ Wer privat schon überzeugt ist, prüft öffentlich nur noch pro forma: Der Wunsch regiert.","beleg":"Werkstück F.1.6 (Der Riss in der Festung); Fn. gl-f-doyle (Doyle 1922, Kap. I, II und IV)","status":"entwurf","scenario":"Ein sehr kluger, öffentlich bekannter Mann verteidigt eine Behauptung, die eine Weltsicht stützen würde, an der er seit schweren Verlusten mit ganzem Herzen hängt. Die Belege sind dünn. Öffentlich schreibt er, die Belege sprächen für einen „starken ersten Anschein“, mehr nicht; in einem privaten Brief an einen Gleichgesinnten nennt er die Sache längst erwiesen.","kurz":"Wer öffentlich von „starkem Anschein“ spricht, privat aber von Gewissheit, dessen Überzeugung steht wohl längst fest. Dann werden die dünnen Belege eher verteidigt als offen geprüft, und Klugheit liefert dafür nur bessere Argumente.","prueffrage":"Wie stark sind die Belege, und welche der beiden Äußerungen geht über das hinaus, was sie hergeben?","rueckmeldung":[{"option":0,"text":"Hoffnung spielt hier tatsächlich eine Rolle. Wer aber im Brief etwas „längst erwiesen“ nennt, schwankt nicht mehr, sondern ist sich innerlich sicher. Die öffentliche Vorsicht wirkt dann eher wie Zurückhaltung als wie echter Zweifel."},{"option":1,"text":"Unter Gleichgesinnten wird oft zugespitzt, und ein Brief ist kein Fachaufsatz. Doch „längst erwiesen“ bei dünnen Belegen und die Hoffnung, die Sache werde eine ganze Weltsicht brechen, deuten eher darauf, dass die Gewissheit die eigentliche Haltung ist und die Vorsicht Fassade."},{"option":3,"text":"Dass er je nach Publikum anders auftritt, stimmt. Daraus folgt aber nicht, dass er keine eigene Meinung hat: Der Brief zeigt eine feste, sogar sehr entschiedene Überzeugung. Angepasst ist wohl nur, wie vorsichtig er sie nach außen formuliert."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II und IV (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"342deee02ce2da5d"}},{"id":"qx-f-030","clusterId":"F","werkstueckRef":"F.1.6","stufe":3,"question":"Was ändert sich am Wechsel vom Freundeskreis zur Kolumne am stärksten?","options":["Neu ist, dass sie ihren guten Ruf einsetzt, um eine unbewiesene Behauptung zu verbreiten, sodass andere ihr vertrauen, ohne selbst zu prüfen.","Neu ist, dass sie Prüfungen mit immer neuen Ausreden entkräftet, sodass ihre Überzeugung durch keinen Befund mehr widerlegbar ist.","Neu ist, dass der Verlust ihres Bruders ihr Urteil trübt, sodass sie ihre eigene Überzeugung nicht mehr nüchtern prüfen kann.","Neu ist, dass sie in zufälligen Signalen des Geräts Muster erkennt, sodass sie bloßes Rauschen als Botschaft von Verstorbenen deutet."],"correctIndex":0,"explanation":"Ein privater Glaube, der Trost spendet, betrifft vor allem die Person selbst. Problematisch wird es, wenn Ansehen und Reichweite eingesetzt werden, um eine ungeprüfte Behauptung zu verbreiten: Andere vertrauen ihr womöglich, weil der Name der Person dem Unsinn den „Stempel der Genialität“ verleiht, statt selbst zu prüfen (Appell an die falsche Autorität). Genau das tat Arthur Conan Doyle, als er die Cottingley-Feen-Fotos mit seinem Ruf als Denker adelte; sie waren, wie die Mädchen später zugaben, mit Papierfiguren und Nadeln inszeniert. Dass jemand Trost sucht, ist menschlich; zur Gefahr wird es, wenn das Vertrauen in einen Namen an die Stelle der Prüfung tritt und andere in die Irre führt.","coreRule":"⚡ Privater Trost ist Privatsache; zur Gefahr wird er, wenn berühmte Autorität ihn in die Öffentlichkeit trägt und andere das Prüfen ersetzen lässt.","beleg":"Werkstück F.1.6 (Der Kipppunkt)","status":"entwurf","scenario":"Eine für ihren scharfen Verstand berühmte Wissenschaftsjournalistin hat ihren Bruder verloren. Seitdem ist sie überzeugt, dass sich Verstorbene über ein bestimmtes Gerät melden, und ist dafür bisher keiner Prüfung begegnet, die sie nicht mit immer neuen Ausreden entkräftet hätte. Zunächst erzählt sie nur Freunden davon. Dann beginnt sie, das Gerät in einer reichweitenstarken Kolumne als gut belegt zu empfehlen.","kurz":"Der Glaube selbst bleibt derselbe; neu ist, dass ihr Ruf nun als Bürgschaft dient. Wer ihrem Namen vertraut, übernimmt die Behauptung, statt sie zu prüfen, und genau so wirkt der Appell an die falsche Autorität.","prueffrage":"Was an ihrer Überzeugung und an ihrem Umgang mit Prüfungen ist vor und nach dem Wechsel gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dieses Ausweichen vor Prüfungen ist auffällig, kam aber schon vor der Kolumne vor. Es erklärt ihren Glauben, nicht, was sich ändert, wenn sie ihn mit großer Reichweite vor anderen vertritt."},{"option":2,"text":"Trauer kann das Urteil trüben, das wirkte aber schon im Freundeskreis. Neu ist nicht ihr Zustand, sondern dass durch die Reichweite viele Menschen dieser Behauptung vertrauen könnten."},{"option":3,"text":"Ob sie Zufälliges als Botschaft deutet, betrifft ihren eigenen Glauben und wäre im Freundeskreis nicht anders. Am Wechsel zur Kolumne ändert sich etwas anderes: die Wirkung auf Menschen, die ihr vertrauen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Veröffentlichung im Strand Magazine 1920/1921, Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8e794de8f86f9367"}},{"id":"qx-f-031","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Wie gehst du mit ihr am sinnvollsten um?","scenario":"Eine kluge Bekannte vertraut seit dem Tod ihres Mannes den Botschaften eines Mediums. Wenn du Widersprüche ansprichst, findet sie jedes Mal eine neue, geschickte Begründung, warum die Botschaften trotzdem stimmen. Du möchtest ihr helfen und dabei nicht überheblich wirken.","options":["Die Widersprüche in den Botschaften sammeln und ihr gebündelt vorlegen, denn je mehr Belege zusammenkommen, desto schwerer lässt sich der Glaube an das Medium halten.","Gemeinsam mit anderen Angehörigen deutlich machen, dass das Medium sie täuscht, denn mehrere Stimmen überzeugen eher als ein einzelner Einwand von dir allein.","Nach dem Bedürfnis fragen, das der Glaube an das Medium seit dem Tod ihres Mannes für sie erfüllt, denn Intelligenz schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist.","Das Thema vorerst ruhen lassen und das Medium nicht mehr ansprechen, denn Kritik an einer Überzeugung wirkt in der Trauer um ihren Mann in aller Regel unpassend."],"correctIndex":2,"explanation":"Intelligenz ist kein Gütesiegel für einzelne Behauptungen, und wer in einem Gebiet brillant ist, kann in einem anderen völlig danebenliegen (Appell an die falsche Autorität). Kein Mensch ist immun gegen Selbsttäuschung, egal wie intelligent oder skeptisch er sonst ist. Auffällig ist hier das Muster: Eine intelligente Person verteidigt eine unbewiesene Behauptung, die ein tiefes persönliches Bedürfnis berührt, wendet ihre kritischen Fähigkeiten nicht auf die eigene, liebgewonnene Überzeugung an und erfindet für widersprüchliche Beweise immer neue Rationalisierungen. Der Schlüssel liegt also im Bedürfnis dahinter (Trost, Hoffnung, Sinn). Die Frage, welches tiefe emotionale Bedürfnis dieser Glaube für sie erfüllt, nimmt sie ernst und zeigt, warum die Prüfung bei ihr aussetzt. Das schafft die Grundlage für ein Gespräch.","coreRule":"⚡ Erst fragen, was ein Glaube leistet, dann prüfen, was er behauptet.","beleg":"Werkstück F.1.6 (Das Härten im Feuer: Schmiede-Übung; Anwendung & Relevanz: Lektion in Demut; Red Flags)","status":"entwurf","kurz":"Wer ein Gespräch will, fragt, welches Bedürfnis der Glaube seit dem Tod ihres Mannes erfüllt. Klugheit schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist, und weitere Gegenbeweise prallen an immer neuen Begründungen ab.","prueffrage":"Wendet sie ihre kritische Schärfe, die sie sonst zeigt, auch auf die Botschaften des Mediums an?","rueckmeldung":[{"option":0,"text":"Die Widersprüche sind real, und sie zu sammeln wirkt gründlich. Genau damit hat sie aber bisher Erfahrung: Für jeden fand sie eine neue Begründung, ein ganzer Stapel wirkt eher wie ein Angriff als wie Hilfe."},{"option":1,"text":"Rückhalt durch mehrere Menschen kann Mut machen, hier erzeugt er aber Druck und genau die Überheblichkeit, die du vermeiden willst. Dazu kommt: Das Bedürfnis dahinter bleibt unberührt, und davon hängt ab, ob ihre Prüfung aussetzt."},{"option":3,"text":"Rücksicht in der Trauer ist ein guter Anlass, und niemand muss sofort Kritik üben. Schweigen heißt aber, auf jede Hilfe zu verzichten: Zuhören und nach dem Bedürfnis fragen verletzen sie nicht, sondern öffnen das Gespräch."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"02e0ab722a352b24"}},{"id":"qx-f-032","clusterId":"F","werkstueckRef":"F.1.7","stufe":1,"question":"In einer Diskussion sagt jemand: „Eine Taschenuhr hat offensichtlich einen Uhrmacher. Lebewesen sind noch viel komplexer, also muss es auch für sie einen Designer geben.“ Welcher Einwand trifft den Schwachpunkt dieses Vergleichs am besten?","options":["Eine Uhr wird in einer einzigen Herstellungsphase fertig gebaut, Lebewesen entstehen dagegen über lange Zeiträume schrittweise durch Variation und Selektion; der Vergleich überträgt also die Entstehungsweise eines Objekts auf einen ganz anders ablaufenden Prozess.","Eine Uhr besteht aus Metall, Lebewesen bestehen dagegen aus organischen Stoffen; wer beide vergleicht, mischt also zwei Materialklassen, die sich grundsätzlich nicht gegenüberstellen lassen.","Eine Uhr erfüllt erkennbar einen Zweck, Lebewesen dagegen nicht; wer ihnen eine Funktion zuschreibt, deutet also menschliche Absichten in die Natur hinein, die dort gar nicht vorkommen.","Eine Uhr braucht einen Hersteller, weil sie eine Ursache haben muss; Lebewesen sind dagegen unverursacht und entstehen aus reinem Zufall, ohne dass irgendein Mechanismus wirkt."],"correctIndex":0,"explanation":"Eine Analogie trägt nur so weit, wie die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt. Hier ist der entscheidende Punkt die Entstehungsweise: Eine Taschenuhr könnte in ihrer heutigen Form nicht aus winzigen, funktionsfähigen Vorformen herauswachsen, sie wird in einer Herstellungsphase fertig gebaut. Lebewesen entstehen dagegen über viele Generationen, weil zufällige Mutationen auftreten und die Selektion nicht-zufällig diejenigen bevorzugt, die sich besser fortpflanzen. Teilstrukturen können dabei zunächst andere Vorteile bieten und später in neue Funktionen eingebunden werden (Exaptation). Der Uhrmacher-Schluss setzt also stillschweigend voraus, dass Komplexität nur durch fertige Planung entsteht, und genau das ist der unbelegte Schritt. Die anderen Einwände greifen daneben: Der Materialunterschied ist für den Schluss unerheblich, Funktionen lassen sich an Organen sehr wohl feststellen, und Evolution ist gerade nicht reiner Zufall, denn Selektion ist nicht zufällig.","coreRule":"⚡ Prüfe bei jeder Analogie, ob die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 4; Abschnitt „Die Uhr im Garten“); Fn. gl-f-8 nur für Paleys Uhr-Analogie (Paley 1802, Kap. 1 und 3)","status":"entwurf","scenario":"","kurz":"Der Vergleich trägt nur, wenn Uhr und Lebewesen auf gleiche Weise entstehen: Eine Uhr wird fertig gebaut, Lebewesen haben sich über viele Generationen schrittweise entwickelt. Dass Komplexität nur durch Planung entstehen kann, setzt der Schluss stillschweigend voraus.","prueffrage":"Woran erkennt man bei einer Taschenuhr, dass ein Uhrmacher sie gebaut hat, und trifft dasselbe auf eine Katze zu?","rueckmeldung":[{"option":1,"text":"Metall und organische Stoffe unterscheiden sich tatsächlich, nur hängt der Schluss nicht am Material. Entscheidend ist, wie etwas entsteht, und dazu sagt der Stoffunterschied nichts. Verglichen werden kann auch über Materialgrenzen hinweg."},{"option":2,"text":"Wer Funktionen in der Natur sieht, deutet leicht Absichten hinein, das ist eine bekannte Gefahr. Die Funktion eines Organs lässt sich aber feststellen, und die Selektion erklärt sie ohne Absicht. Das Problem des Vergleichs liegt woanders."},{"option":3,"text":"Mutationen sind zwar zufällig, die Selektion ist es nicht: Sie bevorzugt, wer sich besser fortpflanzt. Von „unverursacht“ kann also keine Rede sein. Der Vergleich scheitert nicht an fehlender Ursache, sondern an der Art der Entstehung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–75, 80–81","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cdefbcd858d890be"}},{"id":"qx-f-033","clusterId":"F","werkstueckRef":"F.1.7","stufe":2,"question":"Was ist an der Aussage sachlich falsch?","scenario":"Ein Mitschüler behauptet im Biologieunterricht: „Evolution ist doch reiner Zufall. So etwas Komplexes wie ein Auge kann nicht zufällig entstehen.“ Du willst herausfinden, ob die Behauptung überhaupt auf den tatsächlichen Mechanismus zielt.","options":["Er verwechselt Evolution mit der Entstehung des ersten Lebens: Wie die erste Zelle entstand, ist eine andere Frage als die Entwicklung der Arten und ihrer Augen danach.","Er verwechselt Evolution mit der Entwicklung einzelner Lebewesen: Nicht einzelne Individuen entwickeln sich im evolutionären Sinn, sondern Populationen über viele Generationen.","Er setzt Evolution mit Zufall gleich: Zufällige Mutationen treffen auf eine nicht-zufällige Auslese, die vorteilhafte Veränderungen über viele Generationen anhäuft.","Er verwechselt Evolution mit einem Wettlauf zu immer größerer Komplexität: Die Auslese begünstigt, was in der jeweiligen Umwelt besser zurechtkommt, nicht, was komplexer ist."],"correctIndex":2,"explanation":"Der Fehler liegt in der Gleichsetzung von „Evolution“ mit „Zufall“. Der Prozess kombiniert zwei Teile: zufällige Mutation und nicht-zufällige Selektion. Natürliche Selektion filtert aus unzähligen Mutationen beständig diejenigen heraus, die den Fortpflanzungserfolg steigern. Über Millionen von Generationen entstehen so komplexe Anpassungen, ohne dass ein bewusster Designer nötig wäre. Biologische Systeme entstehen über lange Zeiträume und vielfältige Zwischenstufen, nicht in einem einzigen Schritt. Wer die Frage stellt, wie wahrscheinlich es ist, dass ein Auge rein zufällig entsteht, bekämpft daher ein Zerrbild der Evolution.","coreRule":"⚡ Mutation würfelt, Selektion sortiert: Das Ergebnis ist alles andere als Zufall.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 2: Zufällige Mutation, nicht-zufällige Selektion)","status":"entwurf","kurz":"Evolution ist nicht reiner Zufall: Mutationen sind zufällig, die Selektion danach ist es nicht, und sie sammelt über viele Generationen und Zwischenstufen Vorteilhaftes an. Wer fragt, wie wahrscheinlich ein Auge rein zufällig entsteht, bekämpft ein Zerrbild.","prueffrage":"Hat ein Tier mit einer schädlichen Veränderung dieselben Chancen auf Nachwuchs wie eines mit einer nützlichen?","rueckmeldung":[{"option":0,"text":"Die Unterscheidung stimmt: Die Entstehung der ersten Zelle ist eine eigene Frage. Der Mitschüler spricht aber vom Auge, also von dem, was danach kam, und genau dort liegt sein Fehler nicht."},{"option":1,"text":"Dass sich Populationen und nicht einzelne Lebewesen entwickeln, trifft zu. Über einzelne Individuen sagt der Mitschüler aber nichts, sein Denkfehler liegt an anderer Stelle: bei der Rolle des Zufalls."},{"option":3,"text":"Selektion zielt tatsächlich nicht auf mehr Komplexität. Der Mitschüler unterstellt aber auch kein Ziel, er behauptet Zufall. Damit trifft dieser Einwand eine andere Aussage als die gemachte."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“ (Abschnitt „Evolution happens by chance“)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5947fb24b1ef6019"}},{"id":"qx-f-034","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Ein Podiumsredner sagt: „Wissenschaftliche Methodik hin oder her – ob eine Idee in den Biologieunterricht gehört, ist reine Geschmacksfrage. Wir stellen einfach beide Erklärungen gleichwertig nebeneinander und lassen die Schüler entscheiden.“ Die Idee, um die es geht: Bestimmte Strukturen seien so komplex, dass ein bewusster Designer sie geplant haben müsse. Welche Prüffrage trifft den Kern, ob die Idee als gleichwertige wissenschaftliche Alternative in den Lehrplan gehört?","options":["Sagt die Idee eines planenden Designers etwas voraus, das sich beobachten oder widerlegen lässt, und wurden ihre prüfbaren Teilbehauptungen getestet?","Wie viele Fachleute der Biologie halten die Designer-Idee für eine ernsthafte Erklärung, und wie umstritten ist sie unter ihnen derzeit tatsächlich?","Kann die Idee eines planenden Designers die komplexen Strukturen ebenso lückenlos erklären wie die gängige biologische Erklärung, ohne Fragen offenzulassen?","Kann die Biologie bisher sicher ausschließen, dass bestimmte Strukturen zu komplex sind, um ohne einen planenden Designer entstanden zu sein?"],"correctIndex":0,"explanation":"Ob etwas gleichwertige Wissenschaft ist, entscheidet die Prüfbarkeit. Eine Hypothese, die jeden Befund als weiteren Beleg deutet, ist nicht falsifizierbar, und die Beweislast liegt bei dem, der sie vorbringt. Prüfbar ist beim Designer-Argument nur die Teilbehauptung, bestimmte Strukturen seien „irreduzibel komplex“, also ohne jedes einzelne Teil nutzlos – und sie wurde geprüft: Beim bakteriellen Flagellum entspricht ein Teil der Bauteile denen des Typ-III-Sekretionssystems, das für sich allein voll funktionsfähig ist. Ein US-Bundesgericht urteilte 2005 im Fall Dover: Intelligent Design sei keine Wissenschaft und lasse sich von seinen kreationistischen Wurzeln nicht trennen; der Schulbezirk durfte es deshalb nicht im Biologieunterricht vorstellen lassen. Maßgeblich ist, ob die Idee prüfbar und damit wissenschaftlich ist.","coreRule":"⚡ Ob eine Idee als Wissenschaft gleichwertig neben anderen steht, entscheidet ihre Prüfbarkeit – nicht Beliebtheit, Weltbild-Verträglichkeit oder Lautstärke ihrer Vertreter.","beleg":"Werkstück F.1.7 (Anwendung & aktuelle Bedeutung, Wissenschaftspolitik; Der Kipppunkt); Fn. gl-f-kitzmiller (Kitzmiller v. Dover, 20.12.2005, S. 28 f., 64 und 136)","status":"entwurf","scenario":"","kurz":"Gleichwertige Wissenschaft ist eine Idee nur, wenn sie prüfbar ist, also etwas Beobachtbares voraussagt, das sie widerlegen könnte. Geschmack entscheidet das nicht; wer sie vorbringt, muss Tests liefern, und die prüfbare Teilbehauptung ist bereits geprüft.","prueffrage":"Woran sollen die Schüler nach dem Vorschlag des Redners erkennen, welche der beiden Erklärungen zutrifft?","rueckmeldung":[{"option":1,"text":"Die Einschätzung von Fachleuten kann Orientierung geben, ersetzt aber keinen Test. Auch eine Idee, die viele für plausibel halten, ist erst dann Wissenschaft, wenn sie sich an Beobachtungen messen lässt."},{"option":2,"text":"Lückenlosigkeit ist kein Maßstab für Wissenschaft: Auch gut gestützte Erklärungen lassen Fragen offen. Eine Idee, die jeden Befund als Beleg deutet, wirkt lückenlos, lässt sich aber gerade deshalb nicht prüfen."},{"option":3,"text":"Hier ist die Beweislast vertauscht: Nicht die Biologie muss ausschließen, dass ein Designer nötig war, sondern wer die Idee vorbringt, muss prüfbare Behauptungen liefern. Die prüfbare Teilbehauptung wurde übrigens schon getestet."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 64, 76–77, 136","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper, Stanford Encyclopedia of Philosophy (Abschn. 2–3, Falsifizierbarkeit)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b2e35cdfc9b59162"}},{"id":"qx-f-035","clusterId":"F","werkstueckRef":"F.1.7","stufe":4,"question":"Eine Verteidigerin einer Theorie sagt: „Findet man in den Gesteinsschichten eine Zwischenform, ist das ein Beleg für meine Theorie; findet man keine, ist es ebenfalls ein Beleg.“ Wo liegt das methodische Problem?","options":["Die Verteidigerin achtet vor allem auf Funde, die zu ihrer Erwartung passen, und sucht zu wenig gezielt nach Gegenbelegen (Bestätigungsfehler).","Die Verteidigerin wertet das Fehlen einer Zwischenform als Beleg, obwohl ein ausbleibender Fund für sich genommen wenig zeigt (Argument aus Nichtwissen).","Die Verteidigerin deutet beide Befunde schon im Licht ihrer Theorie und nimmt die so gedeuteten Befunde dann als deren Beleg (Zirkelschluss).","Die Verteidigerin wertet Fund und Nichtfund als Bestätigung; die Theorie sagt nichts voraus und kann an keinem Befund scheitern (Immunisierung)."],"correctIndex":3,"explanation":"Eine Theorie, die sowohl den Fund als auch das Ausbleiben des Funds als Bestätigung verbucht, schließt keinen denkbaren Befund aus. Damit kann nichts sie widerlegen, und gerade deshalb prüft nichts sie. Wissenschaftliche Modelle sagen dagegen etwas voraus, das auch scheitern könnte: „Wenn die Theorie stimmt, dürfen wir X nicht finden.“ Wer jeden Ausgang als Treffer wertet, erklärt scheinbar alles, in Wahrheit aber nichts. Das Gegenmittel ist die Frage: „Welcher Befund würde dich umstimmen?“ Gibt es keinen, ist die Behauptung nicht prüfbar.","coreRule":"⚡ Wer jeden Befund erklären kann, erklärt nichts: Ein prüfbares Modell muss etwas ausschließen.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 3: Beweislast und Falsifizierbarkeit; Red Flags)","status":"entwurf","scenario":"","kurz":"Wer Fund und Nichtfund gleichermaßen als Beleg verbucht, schließt keinen Befund aus, also kann auch keiner die Theorie widerlegen. Der Denkfehler liegt nicht in der Auswahl der Funde, sondern darin, dass die Theorie nichts voraussagt, woran sie scheitern könnte.","prueffrage":"Was weißt du nach ihrer Aussage über die Gesteinsschichten, das du vorher noch nicht wusstest?","rueckmeldung":[{"option":0,"text":"Dass sie nur Passendes beachtet, liegt nahe, weil sie alles als Bestätigung liest. Doch sie lässt gerade nichts weg: Fund und Nichtfund zählen beide. Ein selektives Auswählen wäre es erst, wenn nur die passenden Funde zählten."},{"option":1,"text":"Dass ein ausbleibender Fund wenig zeigt, ist richtig, denn Gesteinsschichten überliefern vieles nicht. Damit ist aber nur die Hälfte des Satzes erfasst. Das eigentliche Problem ist, dass auch der Fund als Beleg zählt und so jeder Ausgang passt."},{"option":2,"text":"Die Deutung im Licht der Theorie klingt nach einem Kreis, weil Befund und Theorie eng verknüpft sind. Der Satz behauptet aber nur, dass jeder Ausgang als Beleg zählt, und nicht, dass die Theorie erst zur Deutung der Befunde dient, um sich dann damit zu stützen."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2 „Backdrop to Popper's Thought“, Abschn. 3 „The Problem of Demarcation“)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"ed6a8c67abd920bf"}},{"id":"qx-f-036","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Welche Prüfung zeigt am besten, ob die Aussage wirklich etwas Besonderes über deine Freundin verrät?","scenario":"Eine Freundin liest dir aus ihrem Tageshoroskop vor: „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist.“ Sie ist begeistert: „Das trifft genau auf mich zu! Das kann doch kein Zufall sein.“ Du willst herausfinden, ob die Aussage wirklich etwas über sie verrät.","options":["Fragen, ob dieselbe Aussage auch auf andere Menschen zutreffen würde, etwa auf ihre Kollegen und Nachbarn.","Prüfen, ob das Horoskop aus einer seriösen Quelle stammt und seine Autoren und Methoden offenlegt.","Klären, ob sie sich nur an die Treffer früherer Horoskope erinnert und die Fehlschläge längst vergessen hat.","Klären, ob deine Freundin ohnehin an Horoskope glaubt und deshalb eher einen Treffer in der Aussage sieht."],"correctIndex":0,"explanation":"Eine Aussage verrät nur dann etwas über eine bestimmte Person, wenn sie auf diese Person besser passt als auf andere. „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist“ ist eine typische Barnum-Aussage: vage, schmeichelhaft und universell genug, dass jeder sich darin wiedererkennt. Solche Sätze fühlen sich persönlich an, sind es aber nicht. Das Gefühl der Treffsicherheit ist deshalb kein Beleg. Entscheidend ist, ob die Aussage auch auf andere zutrifft. Die Herkunft des Horoskops ist eine berechtigte Frage der Quellenkritik, sagt aber nichts darüber, ob dieser eine Satz auf deine Freundin besser passt als auf andere. Die Erinnerung an frühere Treffer ist ein bekannter Fehler, betrifft hier aber nicht die vorgelesene Aussage, die sie gerade zum ersten Mal hört. Dass sie an Horoskope glaubt, erklärt ihre Begeisterung, zeigt aber nicht, ob die Aussage etwas über sie verrät.","coreRule":"⚡ Passt eine Aussage auf alle, sagt sie über niemanden etwas: Prüfe, ob sie auch auf andere zutreffen würde.","beleg":"Werkstück F.2.1 (Die Anatomie der Täuschung: Barnum-Effekt, B.10)","status":"entwurf","kurz":"Der Satz sagt nur dann etwas über deine Freundin, wenn er auf sie besser passt als auf andere. Er ist vage und schmeichelhaft genug, dass sich fast jeder darin wiedererkennt, und das Gefühl, er treffe genau, ist deshalb kein Beleg.","prueffrage":"Wer in deinem Bekanntenkreis würde von sich sagen, sein kreatives Potenzial sei schon voll ausgeschöpft?","rueckmeldung":[{"option":1,"text":"Nach der Herkunft zu fragen ist eine berechtigte Frage der Quellenkritik. Sie klärt aber nur, wer den Satz geschrieben hat, nicht, ob er auf deine Freundin besser passt als auf andere."},{"option":2,"text":"Selektive Erinnerung an Treffer ist ein bekannter Fehler und kann bei Horoskopen eine Rolle spielen. Hier geht es aber um einen Satz, den sie gerade zum ersten Mal hört, nicht um frühere Vorhersagen."},{"option":3,"text":"Ein Glaube an Horoskope könnte ihre Begeisterung erklären, denn wer etwas erwartet, sieht eher einen Treffer. Ob der Satz selbst etwas über sie verrät, bleibt damit aber offen: Das zeigt nur der Vergleich mit anderen."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „Forer effect“","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): The fallacy of personal validation: a classroom demonstration of gullibility. Journal of Abnormal and Social Psychology 44(1), S. 118 ff.","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d87b8bed81f1019c"}},{"id":"qx-f-037","clusterId":"F","werkstueckRef":"F.2.1","stufe":2,"question":"Ein Astrologe behauptet: „Die Schwerkraft der Planeten prägt den Charakter eines Menschen bei der Geburt.“ Welcher Einwand trifft diese Behauptung am stärksten?","options":["Ein Körper im selben Raum, etwa der Geburtshelfer, zieht das Neugeborene ähnlich stark oder stärker an als der Mars. Wäre Schwerkraft der Mechanismus, bestimmte der Geburtshelfer das Horoskop mit.","Das Licht der Fixsterne ist bei der Geburt viel zu schwach, um messbar auf ein Neugeborenes zu wirken. Eine Prägung des Charakters durch Sternenstrahlung ist deshalb nicht plausibel.","Die Sternbilder des Tierkreises haben sich seit der Antike durch die Präzession verschoben. Die heutigen Tierkreiszeichen passen deshalb nicht mehr zu den Sternbildern am Himmel.","Die Sterne eines Sternbilds liegen weit auseinander und gehören nur aus Sicht der Erde zusammen. Ein Sternbild bildet deshalb keine reale Einheit, die einen Charakter prägen könnte."],"correctIndex":0,"explanation":"Der Einwand prüft, ob die behauptete Ursache überhaupt ausreicht: Die Anziehung des Geburtshelfers neben der Mutter liegt je nach Marsstellung und Abstand in derselben Größenordnung wie die des Planeten oder deutlich darüber, und seine Gezeitenwirkung übertrifft die des Mars um viele Größenordnungen. Wäre Schwerkraft der Mechanismus, müsste das Horoskop also mindestens ebenso vom Geburtshelfer abhängen wie vom Planeten. Das ist offensichtlich nicht gemeint, also taugt die Schwerkraft nicht als Erklärung. Das schwache Licht der Fixsterne ist zutreffend, betrifft aber nicht die Schwerkraft der Planeten, auf die sich der Astrologe beruft. Die Verschiebung der Sternbilder ist real, betrifft aber die Zuordnung der Zeichen und nicht die Frage, ob Schwerkraft als Ursache reicht. Dass die Sterne eines Sternbilds nur scheinbar zusammengehören, ist eine berechtigte Kritik an den Sternbildern, sagt aber nichts über die Schwerkraft der Planeten.","coreRule":"⚡ Eine behauptete Ursache muss stärker sein als naheliegende Alternativen im selben Raum. Sonst taugt sie nicht als Erklärung.","beleg":"Werkstück F.2.1 (Die Konfrontation mit der Realität: Verletzung der Physik)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wenn Schwerkraft der Mechanismus wäre, müsste der Geburtshelfer im Raum das Horoskop mindestens ebenso mitbestimmen wie der ferne Mars. Das ist offensichtlich nicht gemeint, also reicht die behauptete Ursache nicht aus. Die Stärke der Wirkung wird gar nicht geprüft.","prueffrage":"Wovon hängt ab, wie stark ein Körper ein Neugeborenes anzieht, und wie ändert sich das mit der Entfernung?","rueckmeldung":[{"option":1,"text":"Dass Fixsternlicht bei der Geburt kaum etwas bewirkt, stimmt. Die Behauptung beruft sich aber auf die Schwerkraft der Planeten, nicht auf Sternenlicht. Der Einwand trifft also einen anderen Mechanismus als den genannten."},{"option":2,"text":"Die Verschiebung der Sternbilder durch die Präzession ist real, betrifft aber die Zuordnung der Zeichen zu den Sternbildern. Ob Schwerkraft überhaupt als Ursache ausreicht, bleibt dabei unberührt."},{"option":3,"text":"Die Sterne eines Sternbilds gehören tatsächlich nur aus Sicht der Erde zusammen, das ist eine berechtigte Kritik an Sternbildern. Die Behauptung spricht aber von den Planeten und ihrer Schwerkraft, nicht von Sternbildern."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Universe Today: „Debunking Astrology: Mars Can't Influence You“","oeffentlich":true,"url":"https://universetoday.com/articles/debunking-astrology-mars-cant-influence-you","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"cbe390c606412098"}},{"id":"qx-f-038","clusterId":"F","werkstueckRef":"F.2.1","stufe":3,"question":"Du kritisierst: „Wegen der Präzession passt dein Sternzeichen nicht mehr zu dem Sternbild, in dem die Sonne bei deiner Geburt tatsächlich stand.“ Ein Astrologe entgegnet: „Mein Tierkreis richtet sich bewusst nach den Jahreszeiten, gezählt ab dem Frühlingsanfang, nicht nach den Sternbildern.“ Wie bewertest du diese Antwort?","options":["Sie beantwortet den Einwand, aber dann deutet die Astrologie streng genommen nicht mehr die Sterne, sondern nur noch den Kalender der Jahreszeiten.","Sie löst das Problem nicht, denn die Präzession verschiebt auch den Frühlingspunkt, sodass die Zählung ab Frühlingsanfang mit der Zeit ebenso falsch wird.","Sie zeigt, dass dein Einwand auf einem Missverständnis beruht, denn wenn die Zeichen bewusst den Jahreszeiten folgen, trifft die Präzession die Astrologie nicht.","Sie zeigt, dass ihr nur verschiedene Zählweisen meint, denn dann ist der Streit eine Frage der Festlegung, bei der letztlich keine Seite einen Fehler macht."],"correctIndex":0,"explanation":"Die Verteidigung ist in sich stimmig: Ein tropischer Tierkreis wird von Frühlingspunkt zu Frühlingspunkt gezählt und ist damit an die Jahreszeiten gebunden, nicht an die Sternbilder. Der Einwand der Präzession trifft ihn deshalb nicht. Aber die Antwort hat einen Preis: Wenn sich die Zeichen nach dem Kalender richten, ordnet die Astrologie Menschen nach dem Datum und nicht nach der Stellung der Himmelskörper. Damit fällt auch die Behauptung, die Sterne selbst hätten einen Einfluss. Eine Verteidigung, die den ursprünglichen Gegenstand aufgibt, hat den Streitpunkt nicht gewonnen, sondern verlagert.","coreRule":"⚡ Wer den Himmel gegen den Kalender tauscht, hat die Sterne aus der Astrologie gestrichen.","beleg":"Werkstück F.2.1 (Verletzung der Astronomie); Fn. gl-f-tropisch (Carroll 2003, Skeptic's Dictionary, Art. astrology)","status":"entwurf","scenario":"Du diskutierst mit einem Astrologen über die Verschiebung der Sternbilder seit der Antike.","quote":"","quoteLabel":"","kurz":"Der Astrologe hat die Präzession entkräftet, denn sein Tierkreis folgt den Jahreszeiten. Aber dann ordnet er Menschen nach dem Datum statt nach den Sternen. Wer den Gegenstand wechselt, hat den Streit nicht gewonnen, sondern verlagert.","prueffrage":"Welches Zeichen hätte nach diesem Tierkreis jemand, der heute am selben Kalendertag geboren wird wie jemand vor 2000 Jahren?","rueckmeldung":[{"option":1,"text":"Dass die Präzession auch den Frühlingspunkt verschiebt, stimmt. Der tropische Tierkreis ist aber gerade an diesen Punkt gebunden und behauptet keine Übereinstimmung mit den Sternbildern, also wird er dadurch nicht falsch."},{"option":2,"text":"Die Präzession trifft den tropischen Tierkreis tatsächlich nicht. Ein bloßes Missverständnis ist das aber nicht, denn die Antwort hat einen Preis: Folgen die Zeichen dem Kalender, fällt der behauptete Einfluss der Sterne weg."},{"option":3,"text":"Die Bindung an den Frühlingsanfang ist tatsächlich eine Festlegung der Zählweise. Egal ist sie nicht: Mit ihr ordnet die Astrologie nach dem Datum statt nach den Sternen und gibt damit ihren eigentlichen Gegenstand auf."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „astrology“","oeffentlich":true,"url":"https://skepdic.com/astrology.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"04364564cfb7aece"}},{"id":"qx-f-039","clusterId":"F","werkstueckRef":"F.2.1","stufe":4,"question":"Welche Testanordnung prüft die Behauptung der Astrologin am fairsten?","options":["Die Astrologin ordnet Horoskope den Persönlichkeitsprofilen zu, und die Testleitung, die die richtigen Zuordnungen kennt, begleitet den Ablauf nur beobachtend.","Die Astrologin ordnet Horoskope den Persönlichkeitsprofilen zu, und was als Treffer zählt, legt man erst nach Sicht der Ergebnisse gemeinsam mit ihr fest.","Die Astrologin deutet Horoskope von zufällig ausgewählten Freiwilligen, und diese bewerten anonym, wie gut die Deutung zu ihnen passt.","Die Astrologin ordnet Horoskope den passenden Persönlichkeitsprofilen zu, und weder sie noch die Testleitung wissen währenddessen, welche Zuordnung richtig ist."],"correctIndex":3,"explanation":"Ein fairer Test muss ausschließen, dass etwas anderes als das Horoskop die Treffer erzeugt. Im Doppelblindtest kennt niemand die Lösung, sodass Erwartung und Vorwissen ausscheiden und nur zählt, ob mehr als der Zufall herauskommt. Genau so ein Test fand statt: Carlson ließ Astrologen Horoskope den passenden Persönlichkeitsprofilen zuordnen, und die Trefferquote betrug 0,34 bei einer Zufallsquote von 0,33. Ein anderer Test mit „Zeitzwillingen“ (gut 2.000 Londoner, geboren im März 1958) zeigte ebenfalls keine Ähnlichkeit über den Zufall hinaus: Sie ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen Menschen.","coreRule":"⚡ Fair testen heißt blind testen: Wer Vorwissen oder Bewertung in der Hand hat, misst seine Erwartung, nicht die Behauptung.","beleg":"Werkstück F.2.1 (Das Zwillings-Problem); Fn. gl-f-astrotests (Carlson 1985, Nature 318, S. 419--425; Dean, Kelly 2003)","status":"entwurf","scenario":"Eine Astrologin behauptet: „Ich erkenne den Charakter eines Menschen an seinem Horoskop, auch wenn ich ihn nie getroffen habe.“ Ein Skeptiker will das prüfen, ohne dass das Ergebnis durch Erwartungen, Vorwissen oder Wohlwollen verzerrt wird. Er schlägt vier Testanordnungen vor.","kurz":"Nur wenn weder die Astrologin noch die Testleitung die Lösung kennen, kann nichts außer dem Horoskop die Treffer erzeugen, und es zählt, ob sie über den Zufall hinausgehen. Wer die Lösung kennt, kann unbewusst Hinweise geben.","prueffrage":"Woher könnte in jeder der vier Anordnungen ein Treffer kommen, wenn Horoskope gar nichts über den Charakter verraten?","rueckmeldung":[{"option":0,"text":"Rein beobachtend zu bleiben klingt neutral, und die Zuordnung ist die richtige Aufgabe. Wer die Lösung kennt, kann sie aber unbewusst verraten, etwa durch Mimik oder Zögern. Dann ist es kein echter Doppelblindtest."},{"option":1,"text":"Die Astrologin einzubeziehen wirkt entgegenkommend, und die Zuordnungsaufgabe ist sinnvoll. Legt man den Treffer erst nach Sicht der Ergebnisse fest, lässt sich fast jedes Resultat als Erfolg deuten. Das begünstigt den Bestätigungsfehler. Kriterien müssen vorher feststehen."},{"option":2,"text":"Zufällige Auswahl und anonyme Bewertung wirken fair. Vage Deutungen werden aber fast immer als zutreffend empfunden (Barnum-Effekt), und es fehlt der Vergleich mit dem Zufall. Gemessen wird so eher die Vagheit der Deutung als ihre Treffsicherheit."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, S. 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2be1b2d6ddce1aea"}},{"id":"qx-f-040","clusterId":"F","werkstueckRef":"F.2.2","stufe":1,"question":"Welche Frage prüft die Behauptung „Je stärker verdünnt und geschüttelt, desto stärker die Wirkung“ am besten auf Plausibilität?","options":["Wie viel von der Ausgangssubstanz steckt bei C30 noch im Fläschchen, und wodurch soll dann eine Wirkung entstehen?","Wie vielen Menschen hat das Mittel schon geholfen, und berichten sie bei stärkerer Verdünnung von stärkerer Wirkung?","Steht diese Regel so in den Lehrbüchern der Homöopathie, oder ist sie nur eine persönliche Ansicht deines Bekannten?","Wie lange wird schon nach dieser Regel behandelt, und hat sie sich in der Praxis der Homöopathen bewährt?"],"correctIndex":0,"explanation":"Eine Wirkbehauptung prüft man zuerst an ihrem Mechanismus: Soll eine Substanz wirken, muss sie in der Lösung auch vorhanden sein. Bei C30 beträgt der Verdünnungsfaktor 10^60; statistisch ist kein einziges Molekül der Ausgangssubstanz mehr zu erwarten, schon ab etwa C12 ist die Avogadro-Grenze überschritten. Außerdem beruht die Pharmakologie auf der Dosis-Wirkungs-Beziehung: Mehr Wirkstoff bewirkt mehr Wirkung (bis zu einem Sättigungs- oder Giftigkeitspunkt), nicht weniger. „Mehr Verdünnung, mehr Wirkung“ widerspricht dem und kommt ohne plausiblen Mechanismus aus.","coreRule":"⚡ Prüfe bei jeder Wirkbehauptung zuerst den Mechanismus: Ist der behauptete Wirkstoff überhaupt vorhanden, und passt die Behauptung zur Dosis-Wirkungs-Beziehung?","beleg":"Werkstück F.2.2 (Die Kern-Behauptung); Fn. gl-f-9 (Hahnemann 1796, Hufelands Journal Bd. 2, S. 433)","status":"entwurf","scenario":"Ein Bekannter schwärmt von seinem Globuli-Fläschchen mit der Aufschrift C30. Er sagt: „Je mehr das Mittel verdünnt und geschüttelt wird, desto stärker wirkt es.“","kurz":"Eine Wirkbehauptung prüft man zuerst an ihrem Mechanismus: Bei C30 ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten, und mehr Wirkstoff bewirkt in der Pharmakologie mehr Wirkung, nicht weniger. Verbreitung und Tradition klären das nicht.","prueffrage":"Was würde mit der Wirkung einer Kopfschmerztablette geschehen, wenn man sie immer weiter mit Wasser verdünnt?","rueckmeldung":[{"option":1,"text":"Viele zufriedene Berichte wirken überzeugend. Sie sagen aber nur, dass sich Menschen besser fühlen, nicht, ob das am Mittel liegt oder an Erwartung und dem natürlichen Verlauf. Ob eine Wirkung überhaupt möglich ist, klären sie nicht."},{"option":2,"text":"Ob die Regel in Lehrbüchern steht, ist eine Frage der Quellenlage. Selbst wenn sie dort steht, sagt das nichts darüber, ob sie physikalisch plausibel ist. Eine Lehrmeinung ersetzt keinen möglichen Mechanismus."},{"option":3,"text":"Lange Anwendung klingt nach Bewährung. Doch auch bei wirkungslosen Mitteln kann der Eindruck entstehen, es habe geholfen, etwa durch Erwartung oder weil Beschwerden von selbst abklingen. Ein plausibler Mechanismus ist damit nicht gezeigt."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“ (nach Renz-Polster/Escher, Gesundheit heute)","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"25c995694481b492"}},{"id":"qx-f-041","clusterId":"F","werkstueckRef":"F.2.2","stufe":2,"question":"Was kannst du ihr über den Inhalt des Fläschchens sagen?","scenario":"Eine Freundin schwärmt von ihren Globuli: „Auf dem Fläschchen steht C30, das sind hochwirksame Spuren des Heilstoffs, nur eben sehr fein dosiert.“ Auf dem Beipackzettel steht: Bei einer C-Potenz wird in jedem Schritt im Verhältnis 1 zu 100 verdünnt und verschüttelt, die Zahl gibt die Anzahl der Schritte an. Du weißt außerdem: Ab einer Gesamtverdünnung von etwa 10 hoch 24, das entspricht C12, ist statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten.","options":["Es sind feine Spuren enthalten: C30 steht für ein Verhältnis von eins zu dreißig, also steckt rund ein Dreißigstel der Ausgangsmenge in der Arznei.","Es sind feine Spuren enthalten: Jeder der 30 Schritte lässt ein Hundertstel übrig, und ein noch so kleiner Bruchteil einer Menge wird nie ganz null.","Es ist kein Molekül zu erwarten: 30 Schritte zu je 1 zu 100 ergeben 10 hoch 60, und das liegt weit jenseits der Grenze von 10 hoch 24 bei C12.","Es ist mehr enthalten als bei C12: Beim Verschütteln reichert sich der Stoff mit jedem Schritt an, sodass höhere Potenzen trotz Verdünnung dichter sind."],"correctIndex":2,"explanation":"C30 bedeutet 30 Schritte zu je 1 zu 100, also einen Verdünnungsfaktor von 100 hoch 30 = 10 hoch 60, nicht „eins zu dreißig“. Die Avogadro-Grenze liegt bei D24 bzw. C12: Ab dort ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten (rechnerisch 0,6 Moleküle je Mol Endprodukt). C30 liegt weit jenseits dieser Grenze. Niedrigpotenzen wie D6 bis D12 enthalten noch Spuren des Ausgangsstoffs, Hochpotenzen wie C30 statistisch keines mehr; chemisch ist das Fläschchen Zucker und Wasser (Rademacher 2013). Die Lesart „eins zu dreißig“ übersieht, dass die Zahl die Schritte zählt und jeder Schritt durch 100 teilt. Ein Bruchteil wird rechnerisch zwar nie null, ein Stoff besteht aber aus einzelnen Molekülen, und ein winziger Bruchteil eines einzelnen Moleküls bleibt nicht im Fläschchen zurück. Dass die Konzentration beim Verschütteln wieder ansteigt, widerspricht der Arithmetik: Potenzieren bedeutet schrittweises Verdünnen, nicht Aufkonzentrieren.","coreRule":"⚡ Ab etwa C12 ist statistisch kein Wirkstoffmolekül mehr zu erwarten: Rechne die Verdünnung in Teilchen um, bevor du von „Spuren“ sprichst.","beleg":"Werkstück F.2.2 (Verletzung der Chemie); Fn. gl-f-tiefpotenzen (Rademacher 2013, S. 25--26); Fn. gl-f-10","status":"entwurf","kurz":"Die Zahl hinter C zählt Schritte, und jeder teilt durch 100: C30 ist ein Faktor von 10 hoch 60, weit jenseits der Grenze von 10 hoch 24, ab der statistisch kein Molekül mehr übrig ist. Wer „eins zu dreißig“ liest, übersieht das.","prueffrage":"Was genau zählt die Zahl hinter dem C, und um welchen Faktor wird bei jedem dieser Schritte verdünnt?","rueckmeldung":[{"option":0,"text":"Die Zahl hinter dem C wirkt wie ein Mengenverhältnis, daher liegt „eins zu dreißig“ nah. Laut Beipackzettel zählt sie aber Schritte, und jeder Schritt teilt durch 100. Das ergibt einen Faktor von 10 hoch 60, nicht ein Dreißigstel."},{"option":1,"text":"Richtig ist, dass jeder Schritt rechnerisch ein Hundertstel übrig lässt und ein Bruchteil nie ganz null wird. Ein Stoff besteht aber aus einzelnen Molekülen, und ab etwa C12 ist statistisch keines mehr zu erwarten. Bei C30 bleibt davon nichts übrig."},{"option":3,"text":"Jeder Schritt teilt durch 100, und Verschütteln fügt keinen Stoff hinzu. Eine höhere Potenz bedeutet deshalb stärkere Verdünnung und weniger Ausgangsstoff, nicht mehr. Aufkonzentrieren widerspricht der Rechnung auf dem Beipackzettel."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c0572d845f066fe2"}},{"id":"qx-f-042","clusterId":"F","werkstueckRef":"F.2.2","stufe":3,"question":"Was folgt aus diesem Muster am ehesten?","options":["Der Nutzen zeigt sich nur in weniger sauberen Studien. Das spricht dafür, dass die positiven Ergebnisse auf Verzerrung statt auf echter Wirkung beruhen.","Die Studien widersprechen sich. Das spricht dafür, dass die Frage nach dem Nutzen umstritten ist und sich aus diesen Daten noch keine Richtung ablesen lässt.","Die sauberen Studien folgen einem strengen Schema. Das spricht dafür, dass ihr starrer Aufbau eine Wirkung übersieht, die im Alltag der Kinder auftritt.","Ein Teil der Studien findet einen Nutzen. Das spricht dafür, dass das Mittel eine kleine Wirkung hat, die sich nur in einem Teil der Studien deutlich zeigt."],"correctIndex":0,"explanation":"Entscheidend ist das Muster: Die Studien mit geringem Verzerrungsrisiko finden keinen Nutzen, positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Risiko. Genau das erwartet man, wenn es keine echte Wirkung gibt. Positive Ergebnisse entstehen dann durch Verzerrung im Studienaufbau, etwa durch fehlende Verblindung oder unsaubere Zuteilung, oder durch Zufall. Gäbe es eine echte Wirkung, müsste sie sich auch in den sauber durchgeführten Studien zeigen. Dieser Befund ist ein Beispiel dafür, wie man bei einem Evidenzkörper nicht nur zählt, wie viele Studien positiv ausfallen, sondern auch fragt, wie belastbar sie sind. Er gilt für diese Altersgruppe und diese Beschwerden und ersetzt keine ärztliche Beratung.","coreRule":"⚡ Wenn der Nutzen mit der Studienqualität verschwindet, spricht das gegen eine echte Wirkung.","beleg":"Werkstück F.2.2 (Abschluss-Diagnose); Fn. gl-f-homoeopathie-evidenz (Hawke u. a. 2022, Cochrane CD005974)","status":"entwurf","scenario":"Eine Übersichtsarbeit fasst elf Studien mit insgesamt 1.813 Kindern zusammen, die ein homöopathisches Mittel gegen akute Atemwegsinfekte testen. Die Autoren sortieren die Studien danach, wie anfällig ihr Aufbau für Verzerrungen ist (z. B. fehlende Verblindung oder unsaubere Zuteilung der Kinder auf die Gruppen). Dabei zeigt sich ein Muster: Alle Studien mit sauberem Aufbau finden keinen Nutzen. Positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Verzerrungsrisiko.","kurz":"Wo der Aufbau sauber ist, zeigt sich kein Nutzen, positive Ergebnisse kommen nur aus schwach geschützten Studien. Genau das erwartet man ohne echte Wirkung. Der Fehler wäre, nur die Zahl positiver Studien zu zählen, statt zu fragen, wie belastbar sie sind.","prueffrage":"Wie fallen die Ergebnisse aus, wenn du die Studien nach der Sauberkeit ihres Aufbaus ordnest, statt sie nur zu zählen?","rueckmeldung":[{"option":1,"text":"Die Ergebnisse weichen tatsächlich voneinander ab. Der Unterschied ist aber kein Zufall: Er folgt dem Verzerrungsrisiko, und die sauberen Studien stimmen untereinander überein. Daraus lässt sich durchaus eine Richtung ablesen."},{"option":2,"text":"Verblindung und saubere Zuteilung sind kein starres Schema, das Wirkung übersieht, sondern schützen davor, Verzerrung mit Wirkung zu verwechseln. Eine Alltagswirkung, die nur in unsauberen Studien auftaucht, ist durch nichts gestützt."},{"option":3,"text":"Dass ein Teil der Studien positiv ausfällt, stimmt. Entscheidend ist aber, welche: genau die schwach geschützten. Eine echte Wirkung müsste sich auch in den sauberen Studien zeigen, und dort findet sich kein Nutzen."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hawke, K.; King, D.; van Driel, M. L.; McGuire, T. M. (2022): Homeopathic medicinal products for preventing and treating acute respiratory tract infections in children. Cochrane Database of Systematic Reviews, CD005974.pub6 (frei in PMC9746041)","oeffentlich":true,"doi":"10.1002/14651858.CD005974.pub6","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9746041/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"24ae11d969a295f2"}},{"id":"qx-f-043","clusterId":"F","werkstueckRef":"F.2.2","stufe":4,"question":"Was ist an der Argumentation des Verkäufers der rhetorische Kniff?","scenario":"Ein Verkäufer sagt: „Dieses C200-Globuli heilt deine Lungenentzündung.“ Eine Ärztin wendet ein, dass in C200-Globuli kein einziges Molekül des Wirkstoffs mehr enthalten ist und es keinen Wirksamkeitsnachweis gibt. Der Verkäufer antwortet: „Naja, Homöopathie ist eben ganzheitlich und regt die Selbstheilungskräfte an.“","options":["Er lenkt vom Einwand ab, indem er statt über Wirkstoff und Nachweis über Ganzheitlichkeit und Selbstheilungskräfte spricht.","Er beruft sich auf den ganzheitlichen Ansatz, als bräuchte eine solche Behandlung keinen Wirksamkeitsnachweis.","Er zieht sich unter Kritik von der kühnen Heilbehauptung auf eine bescheidene, kaum widerlegbare Aussage zurück.","Er verwendet wissenschaftlich klingende Wörter, die seiner Antwort den Anschein von Sachkunde geben, ohne etwas zu belegen."],"correctIndex":2,"explanation":"Zuerst steht eine mutige, überprüfbare Behauptung im Raum: Die Globuli heilen eine Lungenentzündung. Sobald Kritik kommt, wechselt der Verkäufer zu einer weichen Aussage („ganzheitlich“, „regt Selbstheilungskräfte an“), die so vage ist, dass sie sich kaum widerlegen lässt. Die Kritik der Ärztin zielte aber auf die erste Behauptung, und die bleibt unbeantwortet. Entscheidend ist der Rückzug von der kühnen auf die bescheidene Behauptung, die man auch „Motte-and-Bailey“ nennt: Hinter dem Rückzug steht die Hoffnung, dass das Publikum später wieder die große Behauptung im Kopf hat.","coreRule":"⚡ Erst die große Behauptung, bei Gegenwind der Rückzug auf eine bescheidene, kaum angreifbare Aussage.","beleg":"Werkstück F.2.2 (Die Anatomie der Täuschung: Motte-and-Bailey)","status":"entwurf","kurz":"Der Verkäufer verteidigt nicht, dass die Globuli eine Lungenentzündung heilen, sondern weicht auf „ganzheitlich“ und „Selbstheilungskräfte“ aus, was kaum zu widerlegen ist. Die ursprüngliche Behauptung bleibt unbeantwortet, die Kritik an ihr läuft ins Leere.","prueffrage":"Auf welche Behauptung bezog sich der Einwand der Ärztin, und beantwortet die Reaktion des Verkäufers genau diese?","rueckmeldung":[{"option":0,"text":"Der Einwand der Ärztin bleibt tatsächlich unbeantwortet. Doch es wird nicht einfach das Thema gewechselt: Der Verkäufer rettet sich in eine so weiche Aussage, dass sie sich kaum widerlegen lässt. Dieser Rückzug ist der eigentliche Kniff."},{"option":1,"text":"Ein Wirksamkeitsnachweis wird vom Verkäufer gar nicht für überflüssig erklärt. Er behauptet nur noch etwas Schwächeres, das schwer prüfbar ist, und die Heilbehauptung steht unverteidigt im Raum."},{"option":3,"text":"„Ganzheitlich“ und „Selbstheilungskräfte“ klingen zwar fachlich, der Verkäufer sagt aber nicht, er wisse es besser. Entscheidend ist, dass er sich vom prüfbaren Heilversprechen auf eine kaum widerlegbare Aussage zurückzieht."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): „Motte and Bailey Doctrines“. Practical Ethics, Oxford Uehiro Centre, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ba919784c63a165b"}},{"id":"qx-f-044","clusterId":"F","werkstueckRef":"F.2.3","stufe":1,"question":"Ein Forscherteam will ein Tier aufspüren, dessen Existenz bisher unbelegt ist. Welches Vorhaben ist ein seriöser Versuch der Entdeckung und keine bloße Monsterjagd?","options":["Ein Team untersucht in einem kaum erforschten Waldgebiet Hinweise auf ein unbekanntes Tier und will das Tier selbst oder eindeutiges Probenmaterial beschaffen.","Ein Team reist in ein kaum erforschtes Waldgebiet und will aus übereinstimmenden Berichten von Dorfbewohnern auf die Existenz eines unbekannten Tieres schließen.","Ein Team stellt in einem kaum erforschten Tal Kamerafallen für ein tonnenschweres Raubtier auf, obwohl die dortige Beute für eine überlebensfähige Population nicht reicht.","Ein Team sucht in einem gut erforschten Schutzgebiet mit dichtem Kameranetz ein großes Raubtier, das auf keiner Aufnahme der letzten Jahre zu sehen war."],"correctIndex":0,"explanation":"Dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten, zeigt nur, dass die Welt früher weniger erforscht war. Es sagt nichts darüber, ob ein bestimmtes Tier heute existiert. Entscheidend sind zwei Fragen: Wie plausibel ist die Behauptung nach dem bekannten biologischen Wissen, und wie gut sind die Beweise? Ein Vorhaben ist seriös, wenn es in wirklich unerforschtem Gebiet nach einem Tier mit plausiblen Hinweisen sucht und handfeste, prüfbare Belege anstrebt, etwa einen Kadaver, DNA oder klare Filmaufnahmen. In gut erforschten Gebieten ist eine unbemerkte, überlebensfähige Population eines großen Tieres ohne jede eindeutige Spur äußerst unwahrscheinlich.","coreRule":"⚡ Nicht die Seltsamkeit des Tieres, sondern Plausibilität und Beweisqualität trennen Suche von Jagd.","beleg":"Werkstück F.2.3 (Die Konfrontation mit der Realität: Die legitime Grenzwissenschaft); Fn. gl-f-okapi, gl-f-kalmar","status":"entwurf","scenario":"Vier Teams planen Expeditionen. Alle berufen sich darauf, dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten und später doch wissenschaftlich beschrieben wurden. Du sollst einschätzen, welches der Vorhaben auf dieser Grundlage tatsächlich eine Entdeckung erwarten lässt.","kurz":"Dass früher als Legende geltende Tiere real waren, zeigt nur, wie wenig damals erforscht war. Seriös ist, in wirklich unerforschtem Gebiet nach plausiblen Hinweisen zu suchen und Handfestes wie ein Tier oder eindeutiges Probenmaterial zu beschaffen.","prueffrage":"Welche Spuren müsste ein großes Tier über Jahrzehnte hinterlassen, und wo hätte man sie längst finden müssen?","rueckmeldung":[{"option":1,"text":"Berichte von Dorfbewohnern sind ein guter Anfang und können zeigen, wo man suchen sollte. Übereinstimmende Erzählungen ersetzen aber keinen Beleg: Beweisen kann die Existenz nur ein Tier, ein Kadaver, DNA oder klares Filmmaterial."},{"option":2,"text":"Kamerafallen sind ein gutes Werkzeug, und das Tal ist kaum erforscht. Doch ein tonnenschweres Raubtier bräuchte genug Beute, um dort überleben zu können. Fehlt sie, ist die Annahme schon nach bekanntem biologischem Wissen kaum plausibel."},{"option":3,"text":"Auch das klingt nach Forschung, und Kameras sind ein sinnvolles Mittel. In einem gut erforschten Gebiet mit dichtem Netz spricht das Ausbleiben jeder Aufnahme aber eher gegen ein verborgenes großes Raubtier. Unbemerkt überlebt hätte es dort äußerst unwahrscheinlich."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"},{"typ":"url","kurz":"Traill, L. W. u. a. (2007): Minimum viable population size (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5fb88109e6628a55"}},{"id":"qx-f-045","clusterId":"F","werkstueckRef":"F.2.3","stufe":2,"question":"Jemand behauptet, im Loch Ness lebe eine Population riesiger Reptilien, die sich dort seit Generationen hält. Welche Überlegung spricht am stärksten dagegen?","options":["Als grobe Faustregel wiegen Räuber zusammen höchstens etwa ein Zehntel ihrer Beute; auf eine überlebensfähige Gruppe verteilt, wäre jedes Tier viel zu klein.","Viele Sichtungen lassen sich durch Wellen, Treibholz und Wasservögel erklären; Augenzeugenberichte sind deshalb als Beleg für große Tiere wenig wert.","Die Beweislast liegt bei dem, der eine außergewöhnliche Behauptung aufstellt; solange kein Belegtier vorliegt, ist die Behauptung nicht gestützt.","Dass nie ein Tier gefangen oder tot gefunden wurde, ist noch kein Gegenbeweis; fehlende Funde schließen eine verborgene Population nicht aus."],"correctIndex":0,"explanation":"Die Behauptung lässt sich mit einer einfachen Bilanz prüfen: Akustische Schätzungen (Shine 1993) und Probennahmen ergaben rund 17 bis 24 Tonnen Fisch im freien Wasser des Sees. Nach einer ökologischen Faustregel macht die Masse aller Räuber zusammen davon meist höchstens etwa ein Zehntel aus, also rund zwei Tonnen. Eine Art braucht aber eine Mindestzahl von Tieren, um nicht auszusterben; bei etwa zehn Tieren käme jedes auf höchstens rund 200 Kilogramm Körpermasse, viel zu wenig für riesige Reptilien. Einschränkung: Die Faustregel gilt nur näherungsweise, und die Zahl gilt nur für das freie Wasser, Uferzone, Bodenfische und Wanderfische sind nicht erfasst; sie ist eine Größenordnung, kein exakter Wert.","coreRule":"⚡ Prüfe Existenzbehauptungen mit einer Bilanz: Reicht die Nahrung für eine überlebensfähige Population?","beleg":"Werkstück F.2.3 (Verletzung der Ökologie & des Energiebedarfs); Fn. gl-f-nessie (Shine 1993, S. 271 f.; auch Loxton, Prothero 2013, S. 158 f.)","status":"entwurf","scenario":"In einem Gespräch über Loch Ness sagt jemand: „Der See ist riesig und tief, da kann sich locker eine Gruppe großer Reptilien verstecken.“ Du weißt: Im freien Wasser des Sees schwimmen nach Sonarzählungen und Probennahmen nur rund 17 bis 24 Tonnen Fisch.","quote":"","quoteLabel":"","kurz":"Der See gibt nach der Fischbilanz nur etwa zwei Tonnen Räubermasse her. Auf eine überlebensfähige Gruppe verteilt, bliebe für jedes Tier viel zu wenig für riesige Reptilien. Die Faustregel gilt nur näherungsweise, die Größenordnung genügt aber.","prueffrage":"Welche Zahl über den See ist bekannt, und was lässt sich mit ihr nachrechnen?","rueckmeldung":[{"option":1,"text":"Dass Wellen, Treibholz und Vögel viele Sichtungen erklären, stimmt, und es schwächt Zeugenberichte. Es rechnet aber nicht nach, ob der See solche Tiere überhaupt ernähren könnte; dieses Argument greift die Behauptung selbst an."},{"option":2,"text":"Die Beweislast beim Behauptenden zu sehen ist richtig. Sie sagt aber nur, dass die Behauptung unbelegt ist, und liefert kein Argument aus den Gegebenheiten des Sees, das gegen die Population spricht."},{"option":3,"text":"Fehlende Funde sind tatsächlich kein Gegenbeweis. Das spricht aber eher für die Möglichkeit einer verborgenen Population, als gegen sie, und sagt nichts darüber, ob der See genug Nahrung für sie hätte."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Shine, A. J. (1993): Postscript: Surgeon or Sturgeon? Scottish Naturalist 105, S. 271–282 (Webfassung des Loch Ness Project)","oeffentlich":true,"url":"https://lochnessproject.org/ARCHIVE%20ROOM/papershtml/loch_ness_surgeon_sturgeon.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"150709cec6dca977"}},{"id":"qx-f-046","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"Ein Forscherteam sammelt Haarproben, die Yeti, Bigfoot und ähnlichen Wesen zugeschrieben wurden, und analysiert sie genetisch. Von den Proben mit auswertbarer DNA stammt keine einzige von einem unbekannten Primaten; gefunden werden unter anderem Bär, Pferd, Kuh, Hund, Wolf, Kojote und ein Mensch. Ein Freund sagt: „Das ist der Beweis, dass es diese Wesen nicht gibt.“ Wie ordnest du das Ergebnis richtig ein?","options":["Die Studie widerlegt die Existenz, denn nach dem Sparsamkeitsprinzip ist die einfachste Erklärung, dass die Proben von bekannten Tieren stammen, damit gesichert.","Die Studie lässt die Existenz offen, denn dass in diesen Haarproben kein unbekannter Primat steckt, widerlegt sie nicht, liefert aber auch keinen Beleg für sie.","Die Studie zeigt, dass Yeti und Bigfoot Verwechslungen mit Bären und anderen Tieren sind, denn genau deren Haare hielt man für Spuren der Wesen.","Die Studie sagt wenig aus, denn sie erfasst nur Proben mit auswertbarer DNA, und gerade unter den übrigen könnte das gesuchte Wesen noch stecken."],"correctIndex":1,"explanation":"Von den Proben mit auswertbarer DNA stammte keine von einem unbekannten Primaten. Das Ergebnis zeigt: Die untersuchten Haare, die Yetis oder Bigfoots zugeschrieben wurden, stammten von bekannten Tieren und einem Menschen. Eine endgültige Widerlegung ist das nicht, denn ein einzelnes Nichtfinden kann nie beweisen, dass etwas nirgends existiert; die Autoren der Studie sagten selbst, sie könne die Existenz unbekannter Primaten weder widerlegen noch belegen. Umgekehrt trägt die Behauptung die Beweislast, und bisher fehlt jeder tragfähige Beleg. Wer „kein Fund“ als „Beweis des Gegenteils“ liest, macht denselben Fehler wie jemand, der „nicht widerlegt“ als „bewiesen“ liest.","coreRule":"⚡ Gezielt gesucht, nichts gefunden: Das ist kein Beweis der Nichtexistenz, aber ein weiterer Mangel an Belegen für die Behauptung.","beleg":"Werkstück F.2.3 (Verletzung der Populationsbiologie); Fn. gl-f-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, S. 1--3)","status":"entwurf","scenario":"","kurz":"Dass keine auswertbare Probe von einem unbekannten Primaten stammt, widerlegt die Existenz nicht, denn ein Nichtfinden kann nie beweisen, dass etwas nirgends existiert. Belegt ist die Existenz damit aber auch nicht: Aus „nicht gefunden“ folgt so wenig „gibt es nicht“ wie aus „nicht widerlegt“.","prueffrage":"Was genau wurde untersucht, und was fand sich in den Proben mit auswertbarer DNA?","rueckmeldung":[{"option":0,"text":"Dass bekannte Tiere die einfachere Erklärung für diese Haare sind, stimmt. Einfach heißt aber nicht bewiesen, und ein Nichtfinden zeigt nie, dass etwas nirgends existiert. Widerlegt und gesichert ist deshalb zu stark."},{"option":2,"text":"Für die untersuchten Haare stimmt das: Sie stammten von bekannten Tieren und einem Menschen. Der Schluss, Yeti und Bigfoot seien damit insgesamt Verwechslungen, geht aber über diese Proben hinaus und deckt andere Sichtungen und Spuren nicht ab."},{"option":3,"text":"Dass nur Proben mit auswertbarer DNA ausgewertet wurden, ist eine echte Grenze. Doch „wenig aussagen“ ist zu viel: Die Auswertung zeigt klar, dass diese Haare von bekannten Tieren stammen. Den Rest als mögliches Versteck zu nehmen, kehrt die Beweislast um."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Sykes, B. C.; Mullis, R. A.; Hagenmuller, C.; Melton, T. W.; Sartori, M. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281(1789), 20140161 (CC BY, PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d7089a60a70d0dd5"}},{"id":"qx-f-047","clusterId":"F","werkstueckRef":"F.2.3","stufe":4,"question":"Ein Bigfoot-Fan sagt: „Der Gorilla galt lange als Mythos und existiert doch. Also kann es auch Bigfoot geben.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Fan nimmt einen Präzedenzfall als Beleg. Der Gorilla zeigt nur, dass Entdeckungen möglich sind, für Bigfoot liefert er aber keinen Beleg.","Der Fan stützt sich auf ein einziges Beispiel. Ein bestätigter Mythos ist zu wenig, um daraus auf weitere wahre Mythen zu schließen.","Der Fan wählt nur ein passendes Beispiel. Mythen, die sich nicht bestätigt haben, lässt er weg, obwohl erst beide zusammen ein faires Bild ergäben.","Der Fan vergleicht ungleiche Fälle. Gorilla und Bigfoot sind verschiedene Tiere, daher lässt sich vom einen kaum etwas auf das andere schließen."],"correctIndex":0,"explanation":"Der Fan schließt von „es gab Fälle, in denen eine Legende wahr war“ auf „also ist diese Legende wahr“. Das ist kein Beleg, sondern ein Präzedenzfall: Er zeigt nur, dass Entdeckungen möglich sind. Die Welt war damals unerforschter, und für das Okapi (1901 anhand von Fellstreifen beschrieben) und den Riesenkalmar (1857 anhand von Funden beschrieben) folgten handfeste Belege. Für Bigfoot fehlen solche Belege; gezielte DNA-Analysen angeblicher Haarproben ergaben 2014 nur bekannte Tiere, darunter Bären, Pferde, Kühe, Hunde und einen Menschen. Dazu kommt: Eine verborgene Population riesiger Primaten bräuchte Tausende Tiere, die in einer von Satelliten und Smartphones kartierten Welt keine eindeutigen Spuren hinterlassen. Dass früher manches unerforscht war, macht die Behauptung heute nicht wahrscheinlicher.","coreRule":"⚡ „Früher galt es auch als Mythos“ ersetzt keinen Beleg für das jetzt behauptete Tier.","beleg":"Werkstück F.2.3 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Dass einmal eine Legende wahr war, zeigt nur, dass Entdeckungen möglich sind, nicht, dass diese Legende stimmt. Für Bigfoot fehlen Belege, und die Welt ist heute weit besser erforscht als damals.","prueffrage":"Was hat Fachleute am Ende vom Gorilla überzeugt, und gibt es für Bigfoot etwas Vergleichbares?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Beispiel ist tatsächlich dünn. Doch auch mehrere bestätigte Legenden würden nichts über Bigfoot beweisen: Jeder Fall braucht eigene Belege, und genau die fehlen hier."},{"option":2,"text":"Vollständigkeit ist bei Beispielen immer eine berechtigte Frage. Hier liegt der Mangel aber woanders: Selbst mit einer fairen Gesamtbilanz bliebe offen, welche Belege es für Bigfoot gibt, und das sind bisher keine."},{"option":3,"text":"Gorilla und Bigfoot sind verschiedene Tiere, das stimmt. Doch auch ein sehr ähnlicher Fall würde den Schluss nicht tragen: Er zeigt nur, dass Entdeckungen möglich sind, und das ersetzt keine Belege für Bigfoot."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kubodera, T.; Mori, K. (2005): First-ever observations of a live giant squid in the wild. Proc. R. Soc. B 272(1581), S. 2583–2586 (PMC1559985)","oeffentlich":true,"doi":"10.1098/rspb.2005.3158","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"bfea49f14356c75b"}},{"id":"qx-f-048","clusterId":"F","werkstueckRef":"F.2.4","stufe":1,"question":"Eine Werbung für ein neues Buch lautet: „Millionen Leser können sich nicht irren – dieses Buch beweist, dass Außerirdische die Pyramiden gebaut haben!“ Was ist an dieser Argumentation fehlerhaft?","options":["Sie folgert aus der großen Verbreitung eines Buches, dass seine Behauptung belegt ist, obwohl Verkaufszahlen nichts über die Beweislage aussagen.","Sie verlangt, dass die Behauptung schon deshalb richtig sein muss, weil bisher niemand den Beweis erbracht hat, dass die Pyramiden von Menschen gebaut wurden.","Sie stützt sich auf ein einziges Buch als Quelle; würden mehrere Bücher dieselbe These vertreten, wäre die Behauptung damit belegt.","Sie schließt aus einem sehr alten Bauwerk, dass die damaligen Menschen es nicht errichtet haben können, weil ihnen die nötige Technik gefehlt habe."],"correctIndex":0,"explanation":"Verkaufszahlen messen Neugier, Marketing und Unterhaltungswert, nicht Wahrheit. Erich von Däniken etwa trug die Alien-Idee 1968 mit „Erinnerungen an die Zukunft“ zu einem Millionenpublikum (die englische Ausgabe verkaufte sich über sieben Millionen Mal), obwohl die Idee älter war und dadurch nicht besser belegt wurde. Ob eine Behauptung stimmt, entscheiden Belege und Methoden, nicht die Zahl derer, die sie gekauft, gehört oder geglaubt haben. Prüfe deshalb immer: Welche Beweise werden vorgelegt, und nicht: Wie viele glauben es?","coreRule":"⚡ Bekannt gemacht ist nicht bewiesen: Die Popularität einer Idee ist kein Beleg.","beleg":"Werkstück F.2.4 (Die Autopsie-Akte); Fn. gl-f-daeniken (Inselmann 2026, Skeptiker 1/2026, S. 25 und 27)","status":"entwurf","scenario":"","kurz":"Millionen Käufer zeigen nur, dass ein Buch Neugier weckt und sich gut verkauft, nicht dass seine These stimmt. Der Fehler liegt im Schluss von „viele glauben es“ auf „es ist belegt“: Ob etwas stimmt, entscheiden Belege und Methoden.","prueffrage":"Welche Belege nennt die Werbung selbst, und was davon sagt etwas über die Pyramiden?","rueckmeldung":[{"option":1,"text":"Die Beweislast so umzudrehen, wäre tatsächlich ein klassischer Fehlschluss. Die Werbung tut das aber nicht, sie beruft sich auf die Leserzahl. Außerdem ist der Bau der Pyramiden durch Menschen gut belegt."},{"option":2,"text":"Die Zahl der Quellen ist nicht der Kern: Auch viele Bücher mit derselben These belegen nichts, solange keines Beweise vorlegt. Die Werbung macht einen anderen Fehler, sie beruft sich auf die Zahl der Leser statt auf Belege."},{"option":3,"text":"Das „Es fehlte die Technik“-Argument kommt in Alien-Theorien oft vor, steht aber nicht in dieser Werbung, und es stimmt auch nicht: Die Ägypter besaßen die nötigen Werkzeuge und Organisation. Diese Werbung setzt auf Verkaufszahlen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to the People“/„Bandwagon“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Associated Press via NBC News (11.01.2026): „Erich von Däniken, Swiss writer who spawned alien archaeology, dies at 90“","oeffentlich":true,"url":"https://www.nbcnews.com/news/obituaries/erich-von-daniken-swiss-writer-spawned-alien-archaeology-dies-90-rcna253448","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Inselmann, L. (2026): Zurück zu den Sternen. Ein skeptischer Nachruf auf Erich von Däniken. Skeptiker 1/2026, S. 25–35","oeffentlich":false,"seite":"S. 27"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6964cbf8fd894a43"}},{"id":"qx-f-049","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Welche Frage prüft die Deutung des Sprechers am besten?","scenario":"In einer Dokumentation wird eine Höhlenmalerei gezeigt: eine stilisierte Figur mit großem Kopfschmuck. Der Sprecher sagt: „Das ist ein Wesen im Raumanzug, kein Zweifel.“ Erhalten sind weder Beschriftungen noch Beigaben, die die Figur erklären.","options":["Wie ähnlich sieht der Kopfschmuck der Figur einem heutigen Raumanzughelm, und welche Teile der Figur lassen sich als Schläuche oder Visier deuten?","Welche Kopfbedeckungen und rituellen Gewänder gab es in der Kultur, die das Bild gemalt hat, und passt der Kopfschmuck der Figur dazu?","Mit welchen Farbstoffen und welcher Technik wurde die Figur gemalt, und lässt sich der Kopfschmuck damit zeitlich einordnen?","Wie lässt sich ausschließen, dass die Figur samt Kopfschmuck eine spätere Fälschung ist, und wer hat die Höhle zuerst untersucht?"],"correctIndex":1,"explanation":"Der Sprecher liest ein sehr altes Bild durch die Brille der Gegenwart: Weil wir Raumanzüge kennen, sehen wir sie auch dort, wo ein Kopfschmuck zu sehen ist. Das ist Präsentismus. Die Deutung gewinnt nicht dadurch an Gewicht, dass sie dem heutigen Auge naheliegt. Entscheidend ist, was für die Entstehungszeit und den kulturellen Rahmen des Bildes belegt ist. In vielen frühen Kulturen gehören Kopfschmuck und Masken zu Ritualen, und eine Figur mit auffälligem Kopfschmuck passt deshalb wahrscheinlich zu einer Person in ritueller Kleidung, etwa einem Schamanen. Die beste Prüffrage fragt daher nach dem Kontext des Bildes. Die anderen Fragen klingen sinnvoll, führen hier aber nicht weiter. Wer nach Ähnlichkeiten mit einem Raumanzughelm sucht, sucht nur Bestätigung für die Deutung, die erst geprüft werden soll. Farbstoffe und Technik sind für Restauratoren und die Datierung wichtig, sagen aber nichts darüber, was die Figur darstellt. Eine Fälschungsprüfung ist sinnvoll, wenn die Echtheit zweifelhaft ist, davon ist hier nicht die Rede.","coreRule":"⚡ Wer ein altes Bild deuten will, fragt zuerst nach dem Kontext seiner Zeit, nicht nach der Ähnlichkeit zu heutiger Technik.","beleg":"Werkstück F.2.4 (Verletzung der Kunstgeschichte & Religionswissenschaft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Das heutige Auge liest einen Raumanzug in den Kopfschmuck, weil wir Raumanzüge kennen. Das ist Präsentismus. Belastbar ist, was zur Entstehungszeit und zum kulturellen Rahmen des Bildes belegt ist, etwa rituelle Kopfbedeckungen.","prueffrage":"Was ist von dem Bild selbst erhalten, und was fügt der Sprecher aus eigenem Wissen hinzu?","rueckmeldung":[{"option":0,"text":"Ähnlichkeiten lassen sich fast immer finden, wenn man gezielt danach sucht. So bestätigt man aber nur die Deutung, die erst geprüft werden soll, und fragt nicht, was die Figur für ihre Zeit bedeutete."},{"option":2,"text":"Farbstoffe und Technik sind für Datierung und Restaurierung wichtig. Sie verraten jedoch nicht, was die Figur darstellen soll, und klären deshalb die Deutung des Sprechers nicht."},{"option":3,"text":"Eine Fälschungsprüfung ist sinnvoll, wenn die Echtheit zweifelhaft ist. Davon ist hier nicht die Rede, und wer die Höhle zuerst untersuchte, sagt nichts darüber, was die Figur darstellt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Colavito, J.: „Faking Ancient Art in Uzbekistan“ (jasoncolavito.com)","oeffentlich":true,"url":"https://www.jasoncolavito.com/faking-ancient-art-in-uzbekistan.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3ce13b3245f01f67"}},{"id":"qx-f-050","clusterId":"F","werkstueckRef":"F.2.4","stufe":3,"question":"Eine Doku-Reihe fragt in jeder Folge neu: „Was, wenn die Götter in Wahrheit Astronauten waren?“ Eine Zuschauerin sagt: „Die behaupten ja gar nichts, die fragen nur. Da kann man ihnen nichts vorwerfen.“ Was ist an dieser Verteidigung fehlerhaft?","options":["Wer nur fragt, legt eine Antwort nahe, ohne sie zu behaupten, und umgeht so die Pflicht, sie zu belegen.","Eine offene Frage lässt jedem Zuschauer die Prüfung selbst und ist deshalb die sauberste Form einer Hypothese.","Wer nichts behauptet, kann auch nichts Falsches sagen, und deshalb bleibt eine Frage immer frei von Fehlschlüssen.","Eine Frage verlagert die Beweislast auf die Kritiker, weil diese das Gegenteil zeigen müssen, um sie zu entkräften."],"correctIndex":0,"explanation":"Eine Suggestivfrage wie „Was, wenn die Götter in Wahrheit Astronauten waren?“ stellt keine beweisbare Behauptung auf, legt aber eine bestimmte Antwort nahe. Das erzeugt ein Gefühl des Mysteriums, und weil nichts Konkretes behauptet wird, muss auch nichts belegt werden. Die Beweislast liegt jedoch bei dem, der eine außergewöhnliche Deutung nahelegt, nicht bei denen, die sie bezweifeln. Wer nur fragt, entzieht sich der Prüfung und bekommt trotzdem die Wirkung einer Behauptung. Ein Test: Formuliere die Frage als Aussage um („Die Götter waren Astronauten“). Wenn du dann Belege verlangen würdest, gilt das auch für die Frageform.","coreRule":"⚡ Wer nur fragt, scheint nichts zu behaupten und umgeht so die Beweislast: Das ist die Wirkung der Suggestivfrage.","beleg":"Werkstück F.2.4 (Die Anatomie der Täuschung: „Ich stelle ja nur Fragen“)","status":"entwurf","scenario":"","kurz":"Eine Suggestivfrage behauptet nichts Konkretes und legt trotzdem eine bestimmte Antwort nahe. So entsteht die Wirkung einer Behauptung, ohne dass jemand Belege liefern muss. Der Fehler liegt darin, dass die Frageform vor der Prüfung schützt.","prueffrage":"Welchen Eindruck hinterlässt die Frage bei dir, und was bliebe von ihr übrig, wenn du sie als bloße Aussage lesen würdest?","rueckmeldung":[{"option":1,"text":"Eine echte Hypothese ist so formuliert, dass man sie prüfen kann. Die Frage hier lenkt dagegen auf eine bestimmte Antwort, ohne sich festzulegen, und entgeht damit genau der Prüfung, die eine Hypothese braucht."},{"option":2,"text":"Wer nichts behauptet, sagt in der Tat nichts Falsches. Doch die Suggestivfrage erzielt die Wirkung einer Behauptung und umgeht den Beleg. Deshalb bleibt sie keineswegs immer frei von Fehlschlüssen."},{"option":3,"text":"Wer eine Frage nicht widerlegen kann, scheint im Nachteil. Die Beweislast trägt aber, wer eine außergewöhnliche Deutung nahelegt; Kritiker müssen das Gegenteil nicht zeigen, um die Deutung anzuzweifeln."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Loaded Question“, „Complex Question“ und „Burden of Proof“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f41319df7fffa842"}},{"id":"qx-f-051","clusterId":"F","werkstueckRef":"F.3.1","stufe":1,"question":"Der Heilpraktiker sagt: „Krebs ist keine Fehlfunktion des Körpers, sondern ein sinnvolles Programm, das durch einen seelischen Schock ausgelöst wird. Eine Chemotherapie stört diesen Heilungsprozess und ist die eigentliche Todesursache.“ Welcher Einwand trifft den Kern dieser Behauptung am besten?","options":["Krebs ist kein sinnvolles Programm, sondern entsteht aus mutierten körpereigenen Zellen, die unkontrolliert wachsen und unbehandelt zum Tod führen können.","Der Heilpraktiker hat keine ärztliche Zulassung, und schon deshalb kann nichts von dem stimmen, was er dem Onkel über Krebs und Chemotherapie erklärt.","Ein Heilpraktiker, der von der Operation abrät, verdient womöglich an Alternativbehandlungen, und deshalb muss seine Erklärung des Krebses falsch sein.","Der Onkel ist durch die Diagnose verunsichert und deshalb leicht zu beeinflussen, also ist die Erklärung, die ihm der Heilpraktiker gibt, nicht ernst zu nehmen."],"correctIndex":0,"explanation":"Die Behauptung deutet eine zerstörerische Krankheit in einen „sinnvollen“ Vorgang um, ohne einen zellbiologischen Mechanismus anzugeben. Krebs ist unkontrolliertes Wachstum mutierter körpereigener Zellen, das Gewebe zerstört und den Organismus ohne Behandlung töten kann. Dass ein Tumor „Sinn“ hätte, ist eine Zuschreibung, kein Befund. Dazu kommt: Wird die Behandlung für den Tod verantwortlich gemacht, kann die Aussage nie scheitern. Wer geheilt wird, bestätigt sie; wer stirbt, hat den „Konflikt nicht gelöst“, einen „Folgekonflikt“ erlitten oder wurde durch die „panikmachende Schulmedizin“ getötet. Eine Aussage, die durch kein denkbares Ergebnis widerlegt werden kann, sagt nichts über die Welt aus.","coreRule":"⚡ Wer eine tödliche Krankheit zum „sinnvollen Programm“ erklärt, braucht einen prüfbaren Mechanismus; ohne ihn ist es eine Umdeutung, keine Erklärung.","beleg":"Werkstück F.3.1 (Die Kern-Behauptung; Verletzung der Onkologie & Zellbiologie; Falsifizierbarkeit)","status":"entwurf","scenario":"Eine Bekannte erzählt dir, ihr Onkel habe eine Krebsdiagnose bekommen. Er wolle die Operation absagen, weil ihm ein Heilpraktiker eine ungewöhnliche Erklärung gegeben habe.","kurz":"Der Einwand muss die Behauptung selbst prüfen: Krebs ist unkontrolliertes Wachstum mutierter Körperzellen, ein „Sinn“ wird nur zugeschrieben, und die Aussage kann durch keinen Ausgang scheitern. Wer sie stattdessen über Person oder Motiv angreift, lässt sie unberührt.","prueffrage":"Woran sterben Menschen mit Krebs, die nie eine Chemotherapie bekommen haben?","rueckmeldung":[{"option":1,"text":"Dass ein Heilpraktiker keine ärztliche Zulassung hat, stimmt und darf misstrauisch machen. Es sagt aber nur etwas über die Person, nicht über den Inhalt, und „nichts davon kann stimmen“ folgt daraus nicht."},{"option":2,"text":"Ein möglicher finanzieller Vorteil ist ein berechtigtes Warnsignal. Er zeigt aber nur, warum jemand etwas sagen könnte, und entscheidet nicht, ob es stimmt: Auch eine eigennützige Aussage kann richtig sein."},{"option":3,"text":"Wer durch eine Diagnose verunsichert ist, hört womöglich eher auf einfache Deutungen, und das erklärt, warum der Onkel zuhört. Ob die Deutung stimmt, sagt das aber nicht, denn es betrifft den Zuhörer und nicht die Behauptung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: „What Is Cancer?“","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"AG Prävention und Integrative Onkologie (PRiO) in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d58982469a48da46"}},{"id":"qx-f-052","clusterId":"F","werkstueckRef":"F.3.1","stufe":2,"question":"Was ist an dieser Argumentation der entscheidende Fehler?","options":["Das Argument deutet Heilung wie Tod zugunsten der Lehre, sodass kein denkbares Ergebnis sie widerlegen kann und sie sich nicht prüfen lässt.","Das Argument schließt aus einer Heilung nach der Behandlung, dass die Lehre sie bewirkt hat, und übersieht andere Gründe für die Genesung.","Das Argument schiebt Todesfälle der Schulmedizin zu und lenkt so von den Schwächen der Lehre auf einen äußeren Gegner als Schuldigen ab.","Das Argument gibt bei Todesfällen den Kranken selbst die Schuld, und sein Fehler liegt darin, dass es den Verstorbenen Unrecht tut."],"correctIndex":0,"explanation":"Eine Aussage ist nur dann prüfbar, wenn es ein denkbares Ergebnis gibt, das sie widerlegen würde. Hier wird jeder Ausgang eingebaut: Heilung bestätigt die Lehre, Tod wird dem Patienten („Konflikt nicht gelöst“, „Folgekonflikt“) oder der Schulmedizin („von der Schulmedizin getötet“) angelastet. Ein solches System kann nie scheitern, und gerade deshalb sagt es nichts darüber, ob es stimmt. Im Ernstfall ist das gefährlich, denn bei ernsten Erkrankungen wie Krebs bedeutet der Verzicht auf wirksame Behandlung ein hohes Todesrisiko. Wer prüfen will, fragt: „Welches Ergebnis würde dich überzeugen, dass die Lehre falsch ist?“ Kommt darauf keine Antwort, ist die Lehre keine Erkenntnis, sondern ein Glaubenssystem.","coreRule":"⚡ Wenn jeder Ausgang die Lehre bestätigt, ist sie nicht prüfbar, und im Ernstfall gefährlich.","beleg":"Werkstück F.3.1 (Die Konfrontation mit der Realität: Falsifizierbarkeit)","status":"entwurf","scenario":"Ein Bekannter will einer todkranken Verwandten eine „Konflikt-Heillehre“ empfehlen und verteidigt sie so: „Wenn jemand nach der Behandlung gesund wird, beweist das die Lehre. Stirbt jemand, hat er seinen Konflikt nicht gelöst, einen Folgekonflikt erlitten oder wurde von der Schulmedizin getötet. Die Lehre irrt also nie.“","kurz":"Das Argument wertet jeden Ausgang zugunsten der Lehre: Heilung bestätigt sie, Tod wird dem Kranken oder der Schulmedizin angelastet. Was nie scheitern kann, sagt nichts darüber, ob es stimmt, und lässt sich nicht prüfen.","prueffrage":"Wie erklärt die Argumentation die Todesfälle, und wem gibt sie dabei jeweils die Schuld?","rueckmeldung":[{"option":1,"text":"Dass eine Heilung nach der Behandlung nicht zeigt, dass die Behandlung sie bewirkt hat, stimmt. Das Argument beruft sich aber nicht nur auf Heilungen, es erklärt auch jeden Todesfall zur Bestätigung. Dort liegt das größere Problem."},{"option":2,"text":"Die Schulmedizin als Schuldigen zu nennen, ist tatsächlich Teil des Musters. Entscheidend ist aber weniger der Gegner als die Wirkung: Zusammen mit den anderen Erklärungen bleibt kein Ausgang übrig, der die Lehre widerlegen könnte."},{"option":3,"text":"Den Kranken die Schuld zu geben, ist tatsächlich hart und unfair. Der Kern ist aber ein logischer: Auch ohne diese Schuldzuweisung blieben genug Ausweichmöglichkeiten, damit die Lehre nie scheitern kann."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"AG PRiO in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"20f0ba1300ca8f4d"}},{"id":"qx-f-053","clusterId":"F","werkstueckRef":"F.3.1","stufe":3,"question":"Was sind die Ringe, und was folgt daraus für die Behauptung des Heilers?","options":["Sie sind echte Strukturen im Gehirn, deren Bedeutung ungeklärt ist, und damit lässt sich die Behauptung vorerst weder stützen noch widerlegen.","Sie sind krankhafte Veränderungen im Gehirn, die ärztlich abgeklärt gehören, und damit hat der Heiler etwas Echtes gesehen, es aber falsch gedeutet.","Sie sind normale Strukturen des gesunden Gehirns, die auf vielen CT-Bildern erscheinen, und damit müsste der Heiler zeigen, dass sie bei Kranken anders aussehen.","Sie sind Artefakte der Aufnahmetechnik, die das CT-Gerät selbst erzeugt, und damit trägt ihr bloßes Sichtbarsein die Behauptung des Heilers nicht."],"correctIndex":3,"explanation":"Dass etwas auf einem Bild sichtbar ist, heißt noch nicht, dass es eine Eigenschaft des Patienten abbildet. Bildgebende Verfahren können selbst Strukturen erzeugen, die es im Körper gar nicht gibt. Bei diesen Ringen ist das der Fall: Radiologen kennen sie seit Langem als Ringartefakte, die die Computertomographie selbst erzeugt und die keine medizinische Bedeutung haben (so beschreibt es etwa Prang 2014). Wer aus ihnen Konflikttyp und Tumorort ablesen will, schließt aus einem Fehler der Technik auf eine Eigenschaft des Patienten. Die richtige Prüffrage lautet deshalb, ob die Struktur überhaupt eine Eigenschaft des Patienten zeigt oder eine des Messgeräts, und nicht, ob sie echt aussieht.","coreRule":"⚡ Was auf dem Bild wie ein Befund aussieht, kann ein Artefakt der Technik sein.","beleg":"Werkstück F.3.1 (Verletzung der Neurologie); Fn. gl-f-hamerherde (Prang 2014, Kap. „Germanische Neue Medizin“)","status":"entwurf","scenario":"Ein Heiler behauptet, er könne auf Gehirn-CT-Bildern an ringförmigen Strukturen („Herden“) erkennen, welchen seelischen Konflikt ein Patient hatte und wo im Körper sein Tumor sitzt. Als Beleg zeigt er dir mehrere Bilder, auf denen solche Ringe deutlich zu sehen sind. Die Ringe selbst sind unstrittig vorhanden.","kurz":"Die Ringe erzeugt das CT-Gerät selbst; sie sind Ringartefakte ohne medizinische Bedeutung. Aus einem Fehler der Technik lässt sich keine Eigenschaft des Patienten ablesen, auch wenn die Ringe auf den Bildern deutlich zu sehen sind.","prueffrage":"Wofür halten Fachleute, die täglich CT-Bilder auswerten, solche Ringe?","rueckmeldung":[{"option":0,"text":"Dass die Ringe im Bild sichtbar sind, ist unstrittig, und ihre Deutung ist der eigentliche Streitpunkt. Sie sind aber keine Hirnstrukturen mit unklarer Bedeutung, sondern vom Gerät erzeugte Artefakte ohne medizinische Bedeutung, und das lässt sich beurteilen."},{"option":1,"text":"Dass der Heiler etwas auf den Bildern wirklich sieht, stimmt. Es ist aber keine krankhafte Veränderung des Gehirns, sondern ein Ringartefakt der Aufnahmetechnik. Er hat also nichts am Patienten gesehen, das falsch gedeutet wurde."},{"option":2,"text":"Ein Vergleich zwischen Gesunden und Kranken wäre ein sinnvoller Test, wenn die Ringe zum Körper gehörten. Sie gehören aber nicht zum gesunden Gehirn, sondern entstehen im CT-Gerät, sodass der Vergleich an der eigentlichen Frage vorbeigeht."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dawes, L.; Ismail, M.; Murphy, A. u. a.: „Ring artifact“. Radiopaedia.org (rID 1988)","oeffentlich":true,"url":"https://radiopaedia.org/articles/ring-artifact","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Abschnitt Hamer-Herde)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prang, M. (2014): Alternativmedizin: Was sie leistet. Wann sie schadet. München: C. H. Beck, Kap. „Germanische Neue Medizin“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"bb3eedafb112ee8c"}},{"id":"qx-f-054","clusterId":"F","werkstueckRef":"F.3.1","stufe":4,"question":"Ein Anbieter wirbt für die „5 Biologischen Naturgesetze“ und versichert: „Mit der Germanischen Neuen Medizin hat das nichts zu tun.“ Auf Nachfrage zählt er als „Gesetze“ dieselben Behauptungen auf wie die Germanische Neue Medizin: Jede Krankheit gehe auf einen seelischen Schock-Konflikt zurück, Tumore seien „sinnvolle Programme“, Chemotherapie störe die Heilung. Was folgt daraus für die Beurteilung des Angebots?","options":["Die Lehre ist inhaltlich dieselbe, denn Schock-Konflikt, „sinnvolle Programme“ und gestörte Heilung durch Chemotherapie sind die alten Behauptungen unter neuem Namen.","Die Lehre ist schon wegen der verschwiegenen Herkunft fragwürdig, denn wer die Wurzeln seines Angebots verschweigt, dem ist auch in der Sache schwer zu trauen.","Die Lehre ist an den Erfahrungen ihrer Nutzer zu messen, denn ob sie auf die Germanische Neue Medizin zurückgeht, ist für Kranke weniger wichtig als die Frage, ob sie hilft.","Die Lehre ist vorerst offen zu beurteilen, denn der Anbieter hat sich ausdrücklich abgegrenzt, und Übereinstimmungen in einzelnen Punkten kommen bei Heillehren vor."],"correctIndex":0,"explanation":"Ob eine Behauptung stimmt, hängt von ihrem Inhalt und ihren Belegen ab, nicht von ihrem Etikett. Wer dieselben Kernthesen unter neuem Namen anbietet, bietet dieselbe Lehre an. Hamers Lehre wird seit seinem Tod (2017) unter mehreren Namen weitergeführt, etwa als „5 Biologische Naturgesetze“ oder in der „Meta-Medizin“, die Hamers fünf „Gesetze“ übernimmt. Die Bezeichnung „5 Biologische Naturgesetze“ vermeidet dabei gerade den belasteten Begriff „Germanisch“. Die Lehre wurde also weitergeführt, nicht korrigiert: Die Kernthesen bleiben dieselben, also bleiben auch die Probleme. Der richtige Prüfschritt ist deshalb, die Inhalte mit der bekannten Lehre zu vergleichen und nach unabhängigen Belegen zu fragen, nicht dem Namen zu glauben.","coreRule":"⚡ Prüfe die Lehre, nicht das Etikett: Umbenennen ersetzt keine Belege.","beleg":"Werkstück F.3.1 (Die Autopsie-Akte); Fn. gl-f-14 (Psiram; Apotheken Umschau, abgerufen 23.09.2026)","status":"entwurf","scenario":"Du stößt in einer Messenger-Gruppe auf einen Anbieter, der „5 Biologische Naturgesetze“ als neue Heilmethode bewirbt. Der Name klingt neutral. Auf die Frage nach dem Ursprung sagt er nur, mit der Germanischen Neuen Medizin habe das nichts zu tun.","kurz":"Entscheidend ist der Inhalt, nicht der Name: Dieselben Kernthesen wie bei der Germanischen Neuen Medizin bedeuten dieselbe Lehre, nur umbenannt. Der Fehler wäre, der Abgrenzung zu glauben, statt die Thesen zu vergleichen und nach unabhängigen Belegen zu fragen.","prueffrage":"Welche Behauptungen stehen hinter dem Namen, und wo hast du sie schon einmal gelesen?","rueckmeldung":[{"option":1,"text":"Verschwiegene Herkunft ist ein berechtigter Anlass, genauer hinzusehen. Als Begründung trägt sie aber nicht, denn ob eine Lehre stimmt, hängt von ihren Inhalten und Belegen ab, nicht davon, wie offen jemand mit ihrer Geschichte umgeht."},{"option":2,"text":"Ob etwas Kranken hilft, ist tatsächlich die entscheidende Frage. Einzelne Erfahrungsberichte belegen das aber nicht, denn Zufall, Spontanverlauf und Auswahl können jeden Eindruck erzeugen. Dafür braucht es unabhängige Belege."},{"option":3,"text":"Eine offene Beurteilung wäre sinnvoll, wenn nur einzelne Punkte übereinstimmten. Hier sind es aber die Kernthesen selbst, und die Abgrenzung ist nur ein Etikett. Sie ändert nichts daran, dass die Lehre dieselbe ist."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Synonyme „fünf biologische Naturgesetze (5bn/5BN)“, „Germanische Heilkunde“)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Metamedizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Metamedizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c7484b7a07f6245b"}},{"id":"qx-f-055","clusterId":"F","werkstueckRef":"F.4.1","stufe":1,"question":"Eine Freundin erzählt: „Ich glaube an Karma und Reinkarnation, lege aber auch meine Tarotkarten, trage Heilsteine, meditiere zum ‚inneren Kind‘ und glaube an die Kraft der Schwingungen. Eine feste Gemeinschaft oder verbindliche Regeln brauche ich nicht.“ Welche Schlussfolgerung zieht man daraus am sinnvollsten?","options":["Ihre Weltanschauung ist eine selbst zusammengestellte Mischung, weil sie Versatzstücke aus verschiedenen Quellen frei verbindet.","Ihre Weltanschauung ist im Kern hinduistisch oder buddhistisch, weil Karma und Reinkarnation die zentralen Lehren dieser Religionen sind.","Ihre Weltanschauung ist im Kern psychologisch fundiert, weil das Konzept des „inneren Kindes“ aus der Psychologie stammt.","Ihre Weltanschauung ist in sich widersprüchlich, weil Karma, Tarot und Schwingungen aus miteinander unvereinbaren Lehren stammen."],"correctIndex":0,"explanation":"Karma und Reinkarnation stammen aus indischen Religionen wie Hinduismus und Buddhismus, das „innere Kind“ aus der Psychologie, Kristallheilung (Heilsteine) gehört zu den Pseudowissenschaften. Die Freundin kombiniert solche Versatzstücke nach eigenem Geschmack, ohne feste Dogmen, ohne Gemeinschaft und ohne verbindliche Regeln – ein Baukasten, aus dem man sich wie in einem Supermarkt bedient. Die Elemente werden dabei häufig aus ihrem ursprünglichen Zusammenhang gelöst: Karma etwa gehört in diesen Religionen in einen strengen ethischen Zusammenhang, der hier wegfällt. In solchen selbst zusammengestellten Weltanschauungen gilt oft das eigene Erleben als Maßstab, nicht überprüfbare Evidenz. Dass sich etwas stimmig anfühlt, ist aber kein Test, ob es stimmt.","coreRule":"⚡ Wer sich seine Weltanschauung aus Fertigteilen zusammenbaut, entscheidet nach Gefühl und Geschmack. Dass die Teile zusammenpassen, heißt nicht, dass sie stimmen.","beleg":"Werkstück F.4.1 (Die Anatomie der Lehre: Das Baukasten-Prinzip)","status":"entwurf","scenario":"","kurz":"Die Freundin bedient sich aus verschiedenen Quellen und fügt die Teile nach eigenem Geschmack zusammen, ohne Dogmen oder Gemeinschaft. Wer nur auf ein Element schaut, etwa Karma, übersieht, dass es hier aus seinem Zusammenhang gelöst ist.","prueffrage":"Was sagt die Freundin über Regeln und Gemeinschaft, und was verbindet Tarot, Heilsteine und Karma miteinander?","rueckmeldung":[{"option":1,"text":"Karma und Reinkarnation stammen tatsächlich aus indischen Religionen. Tarot, Heilsteine und das „innere Kind“ gehören aber nicht dazu, und weder Regeln noch Gemeinschaft sind da. Ein einzelnes Element macht noch keinen Kern."},{"option":2,"text":"Das „innere Kind“ kommt wirklich aus der Psychologie. Das ist aber nur ein Baustein unter mehreren, und Heilsteine gelten als Pseudowissenschaft. Die Herkunft eines Begriffs sagt nichts über die ganze Weltanschauung."},{"option":3,"text":"Die Quellen sind tatsächlich verschieden. Doch ohne feste Lehre gibt es nichts, was sich förmlich widersprechen müsste: Sie wählt nach Geschmack aus. Das Auffällige ist die freie Zusammenstellung, nicht ein logischer Widerspruch."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung „Wenn Familien zweimal Weihnachten feiern – Mehr als ein Fünftel der Deutschen pflegen Patchwork-Religiosität“ (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5b559e82ee54cb73"}},{"id":"qx-f-056","clusterId":"F","werkstueckRef":"F.4.1","stufe":2,"question":"Ein Verkäufer entgegnet auf Kritik an seinen Heilsteinen: „Das ist nur deine materialistische Sichtweise, du bist für höhere Wahrheiten nicht offen.“ Was bewirkt diese Antwort für die Prüfbarkeit seiner Behauptung?","scenario":"Du äußerst an einem Stand auf einer Esoterikmesse Zweifel an der Wirkung von Heilsteinen.","options":["Sie lässt die Prüfbarkeit unberührt, weil der Verkäufer nur dich beurteilt und seine Aussage über die Heilsteine selbst bestehen lässt.","Sie macht die Behauptung unangreifbar, weil der Verkäufer Zweifel an seinen Heilsteinen pauschal als mangelnde Offenheit abtun kann.","Sie zeigt, dass die Wirkung eine Frage der Sichtweise ist, weil materialistische und spirituelle Zugänge zur Wahrheit gleichberechtigt sind.","Sie stützt die Behauptung, weil der Verkäufer mit den höheren Wahrheiten eine Erklärung für die Wirkung der Heilsteine liefert."],"correctIndex":1,"explanation":"Der Verkäufer behauptet, Heilsteine wirkten. Auf die Kritik antwortet er nicht mit einem Beleg, sondern mit einem Urteil über den Kritiker: Wer zweifelt, sei „nicht offen“. So lässt sich jede wissenschaftliche Kritik abwehren; die Behauptung wird unangreifbar und unfalsifizierbar. Entscheidend ist hier nur der Mechanismus: Kritik wird durch Immunisierung statt durch Belege beantwortet.","coreRule":"⚡ Wenn nur das eigene Gefühl zählt, kann kein Gegenbeweis zählen.","beleg":"Werkstück F.4.1 (Die epistemologische Grundlage: Absolute Subjektivität)","status":"entwurf","kurz":"Der Verkäufer antwortet nicht mit einem Beleg, sondern mit einem Urteil über den Zweifler: Wer zweifelt, sei „nicht offen“. So lässt sich jede Kritik abwehren, und die Behauptung wird unprüfbar. Das Urteil über die Person ersetzt hier den Beleg.","prueffrage":"Worüber spricht der Verkäufer in seiner Antwort: über die Steine oder über die Person, die zweifelt?","rueckmeldung":[{"option":0,"text":"Formal richtet sich der Satz tatsächlich gegen dich und nicht gegen die Steine. Gerade so schirmt er die Behauptung aber gegen jede Kritik ab, denn Zweifel gelten nun als Charakterfehler. Prüfbarer wird sie dadurch nicht, sondern unangreifbar."},{"option":2,"text":"Wer verschiedene Sichtweisen gelten lässt, wirkt tolerant. Ob ein Stein eine Wirkung hat, ist aber eine Frage der Tatsachen und keine der Perspektive. Der Satz belegt die Gleichberechtigung nicht, er setzt sie nur voraus, um den Zweifel abzuwehren."},{"option":3,"text":"„Höhere Wahrheiten“ klingt nach einer Begründung. Es bleibt aber ein Etikett ohne Mechanismus, Beleg oder prüfbare Aussage. Eine Erklärung für die Wirkung der Steine liefert der Satz damit nicht, und die Behauptung stützt er auch nicht."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"30dc711c9b20ac66"}},{"id":"qx-f-057","clusterId":"F","werkstueckRef":"F.4.1","stufe":3,"question":"Eine Bekannte erzählt dir, ihre Schwester habe ihre Krebstherapie abgebrochen und setze nun nur noch auf Energiearbeit und Kristalle. Die Bekannte meint: „Esoterik ist doch eine harmlose Quelle von Trost, jeder darf glauben, was er will.“ Was ist an dieser Einschätzung für den vorliegenden Fall am ehesten falsch?","options":["Sie übersieht, dass der Schaden erst entsteht, wenn das Heilversprechen der Kristalle die wirksame Krebstherapie ersetzt, nicht schon durch den Trost.","Sie übersieht, dass Esoterik bei einer so schweren Krankheit schon als Trost schadet, weil sie der Schwester falsche Hoffnung auf Heilung macht.","Sie übersieht, dass auch ein tröstender Glaube falsch sein kann; Kristalle und Energiearbeit trösten die Schwester mit einer Wirkung, die sie nicht haben.","Sie übersieht, dass „jeder darf glauben, was er will“ eine freie Wahl voraussetzt, die eine schwere Krebsdiagnose der Schwester sehr erschweren kann."],"correctIndex":0,"explanation":"Trost und Inspiration können für viele Menschen harmlos sein. Problematisch wird es dort, wo ein unbelegtes Heilversprechen eine nachweislich wirksame Behandlung verdrängt: Dann steht die Gesundheit auf dem Spiel, und die Berufung auf „jeder darf glauben, was er will“ geht am Kern vorbei. Entscheidend sind die Folgen für konkrete Menschen. Dass viele einen Glauben teilen, sagt zwar nichts über seine Richtigkeit, aber die Bekannte stützt sich gar nicht auf die Zahl der Gläubigen. Wer Kristalle nur zur Beruhigung nutzt, muss dafür keinen Beleg liefern; der Schaden liegt hier in der verdrängten Therapie. Die Herkunft einzelner Praktiken ist ein anderes Thema und ändert nichts an der Gefahr für die Schwester.","coreRule":"⚡ Gefährlich wird eine Weltanschauung nicht durch ihren Trost, sondern dort, wo sie wirksame Behandlung ersetzt oder Mitmenschen aus dem Blick verliert.","beleg":"Werkstück F.4.1 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Trost allein schadet meist nicht; gefährlich wird es, wenn ein unbelegtes Heilversprechen eine wirksame Krebstherapie verdrängt. Dann zählt nicht, was jeder glauben darf, sondern was der Verzicht auf die Behandlung für die Schwester bedeutet.","prueffrage":"Was hat die Schwester konkret aufgegeben, und was kann das bei einer Krebserkrankung bedeuten?","rueckmeldung":[{"option":1,"text":"Dass ein unbelegtes Heilversprechen heikel ist, stimmt. Trost allein schadet aber nicht, weil Kristalle zur Beruhigung niemandem Heilung vorgaukeln müssen. Zum Problem wird es erst, wenn sie die Therapie ersetzen."},{"option":2,"text":"Ein tröstender Glaube kann sachlich falsch sein, doch wer Kristalle nur zur Beruhigung nutzt, braucht dafür keinen Beleg und richtet nichts an. Der Fall wiegt schwerer, weil dort nicht nur getröstet, sondern eine Behandlung abgebrochen wird."},{"option":3,"text":"Eine schwere Diagnose kann Entscheidungen belasten. Davon steht im Fall aber nichts, und der Satz der Bekannten wird dadurch nicht getroffen. Falsch daran ist, dass er den Verzicht auf die wirksame Behandlung übergeht."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, J Natl Cancer Inst 110(1), S. 121–124 (Abstract öffentlich, PMID 28922780)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4d01a0427b190b1d"}},{"id":"qx-f-058","clusterId":"F","werkstueckRef":"F.4.1","stufe":4,"question":"Ein Freund erklärt: „Ich glaube an Astrologie, Kristallheilung, Reinkarnation und an die Kraft positiven Denkens. Das passt alles zusammen, weil für mich zählt, was sich richtig anfühlt.“ Warum kann ein solches Weltbild praktisch jede unbelegte Behauptung problemlos aufnehmen?","options":["Weil sich seine Lehren, wie er selbst sagt, nicht widersprechen, sodass neben Astrologie und Reinkarnation auch beliebige weitere Lehren ohne Konflikt Platz finden.","Weil solche Lehren oft vage formuliert sind, sodass sich ihre Aussagen von Astrologie bis Reinkarnation irgendwie auf das eigene Leben beziehen lassen.","Weil es dabei um Sinnfragen geht, die sich wissenschaftlich kaum prüfen lassen, sodass Astrologie wie Kristallheilung außerhalb wissenschaftlicher Prüfung stehen.","Weil sein Weltbild keine feste Lehre und keinen Maßstab außer dem eigenen Gefühl kennt, sodass Astrologie wie Reinkarnation und alles Weitere hineinpassen."],"correctIndex":3,"explanation":"Ein Weltbild, das sich aus frei gewählten Bausteinen zusammensetzt und als einzigen Maßstab das eigene Gefühl akzeptiert, kennt kein Kriterium, das etwas ausschließen könnte. Wo nichts geprüft wird, kann auch nichts durchfallen: Astrologie, Kristallheilung und Reinkarnation lassen sich daher widerspruchslos nebeneinander einbauen, auch wenn keine davon belegt ist. Hinzu kommt: Kritik lässt sich mit Sätzen wie „Das ist nur deine materialistische Sichtweise“ abwehren, das System ist also nicht widerlegbar (unfalsifizierbar). Ein festes Lehrgebäude hätte dagegen Regeln, die manches ausschließen würden. Die Esoterik ersetzt überprüfbare Evidenz durch subjektive innere Erfahrung und macht sich dadurch immun gegen Kritik.","coreRule":"⚡ Wo nur das eigene Gefühl zählt, kann jedes Modul rein, auch das unbelegte: Ein Weltbild, das nichts ausschließt, belegt nichts.","beleg":"Werkstück F.4.1 (Die Esoterik als Wurzel und Nährboden; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Gespräch mit einem Freund über sein persönliches Weltbild.","kurz":"Wenn allein das eigene Gefühl zählt, gibt es kein Kriterium, das etwas ausschließen könnte. Wo nichts geprüft wird, fällt auch nichts durch, und jede unbelegte Behauptung passt hinein, und Kritik lässt sich als „materialistisch“ abwehren.","prueffrage":"Hat der Freund je eine Überzeugung wieder aufgegeben, und was hätte ihn dazu bringen können?","rueckmeldung":[{"option":0,"text":"Dass sich nichts widerspricht, stimmt in dem Sinn, dass nichts aneinander scheitern kann. Das liegt aber nicht an der inneren Stimmigkeit der Lehren, sondern daran, dass kein Maßstab vorhanden ist, an dem sie gemessen würden."},{"option":1,"text":"Vage Aussagen lassen sich tatsächlich leicht aufs eigene Leben beziehen, und manche Horoskope leben davon. Der Kern liegt aber woanders: Auch eine ganz genaue Behauptung würde aufgenommen, solange allein das Gefühl entscheidet."},{"option":2,"text":"Manche Sinnfragen lassen sich wissenschaftlich kaum prüfen. Kristallheilung und Astrologie machen aber durchaus überprüfbare Aussagen. Entscheidend ist nicht, dass Prüfung unmöglich wäre, sondern dass im Weltbild des Freundes kein Prüfmaßstab außer dem Gefühl zählt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung zur Patchwork-Religiosität (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"f4659d7051b30e9d"}},{"id":"qx-f-059","clusterId":"F","werkstueckRef":"F.4.2","stufe":1,"question":"Auf welche Art von Rechtfertigung stützt sich deine Freundin damit?","options":["Auf Autorität: Die Behauptung gilt als wahr, weil eine Schrift und eine Lehrinstanz sie bestätigen, nicht weil sie geprüft wurde.","Auf Tradition: Die Behauptung gilt als wahr, weil sie seit Jahrhunderten weitergegeben wird, nicht weil sie geprüft wurde.","Auf Mehrheit: Die Behauptung gilt als wahr, weil die Menschen in ihrer Gemeinde sie gemeinsam für richtig halten, nicht weil sie geprüft wurde.","Auf eigene Überzeugung: Die Behauptung gilt als wahr, weil sie selbst fest daran glaubt, nicht weil sie geprüft wurde."],"correctIndex":0,"explanation":"Wer sich auf eine heilige Schrift und eine Lehrinstanz beruft, stützt sich auf Autorität: Die Wahrheit wird in diesem Rahmen nicht durch empirische Experimente entdeckt, sondern durch göttliche Offenbarung empfangen. Über Fragen von Sinn und Ethik hat die Wissenschaft nicht zu entscheiden. Bei überprüfbaren Tatsachenbehauptungen wie dem Alter der Erde betreten Glaubenslehren dagegen das Feld empirischer Prüfung, und Konflikte mit den Befunden sind deshalb angelegt. Dass eine Schrift und eine Gemeinde etwas lehren, ersetzt keine Prüfung.","coreRule":"⚡ Autorität ist keine Prüfung: Eine Aussage gilt nicht schon deshalb als belegt, weil eine Schrift oder Institution sie verkündet.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage: Offenbarung vs. Realität)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über die Frage, ob die Erde nur 6.000 Jahre alt ist. Sie entgegnet: „Ich glaube das, weil es in unserer heiligen Schrift steht und unsere Gemeinde es seit Jahrhunderten so lehrt.“","quote":"","quoteLabel":"","kurz":"Sie beruft sich auf eine Schrift und eine Lehrinstanz, also auf Autorität. Das ist keine Prüfung: Beim Alter der Erde geht es um eine Tatsache, die sich empirisch prüfen lässt, und dass etwas gelehrt wird, ersetzt diese Prüfung nicht.","prueffrage":"Was hat die Freundin selbst beobachtet oder gemessen, und was hat sie von anderen übernommen?","rueckmeldung":[{"option":1,"text":"Dass die Gemeinde es seit Jahrhunderten lehrt, spielt mit hinein, und ein hohes Alter wirkt beruhigend. Ein Grund für Wahrheit ist es aber nicht, denn auch alte Lehren können falsch sein. Sie stützt sich ausdrücklich auf Schrift und Lehre."},{"option":2,"text":"Eine Gemeinde, die gemeinsam glaubt, erinnert an das Argument „viele können sich nicht irren“. Sie sagt aber nicht, dass viele es glauben, sondern verweist auf Schrift und Lehre. Auch Zustimmung vieler wäre übrigens keine Prüfung."},{"option":3,"text":"Sie glaubt fest daran, das stimmt, doch das ist der Gegenstand der Frage und nicht ihre Begründung. Als Grund nennt sie die Schrift und die Lehre der Gemeinde, nicht ihr eigenes Gefühl oder Erleben."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"„Religion and Science“, Stanford Encyclopedia of Philosophy (2017, rev. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/religion-science/","seite":"Abschnitt 1.3, 2.1, 3.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"f05f901f898f3f54"}},{"id":"qx-f-060","clusterId":"F","werkstueckRef":"F.4.2","stufe":3,"question":"Worin liegt der entscheidende Unterschied zwischen dem Gespräch, das du als gefährlich einstufen würdest, und den harmlosen?","options":["Gefährlich ist D, weil dort eine überprüfbare Behauptung gegen Belege abgeschirmt und Zweifel als Sünde gebrandmarkt wird.","Gefährlich ist B, weil feste Schriften und eine verbindliche Auslegung durch die Gemeinde das Nachfragen stark erschweren.","Gefährlich ist C, weil große Reichweite und viel Einfluss in einer Stadt eine Gemeinschaft oft zur Bedrohung machen.","Gefährlich ist A, weil Aussagen über Sinn und Lebensführung der Wissenschaft entzogen sind und sich nicht prüfen lassen."],"correctIndex":0,"explanation":"Entscheidend ist, ob eine Aussage prüfbar ist und trotzdem gegen Belege geschützt wird. Ob Gebet eine medizinische Behandlung ersetzt, ist eine überprüfbare Behauptung über die Welt, und ein Irrtum kann hier das Leben des Kindes gefährden. Wird diese Frage zusätzlich mit „Sünde“ belegt, ist Zweifel nicht mehr erlaubt. Sinn, Trost und Gemeinschaft (A) sind keine Tatsachenbehauptungen, über die Belege entscheiden könnten, und feste Schriften (B) oder Einfluss (C) schirmen für sich genommen noch keine prüfbare Behauptung ab. Gefährlich wird es dort, wo prüfbare Behauptungen gegen Belege immunisiert werden, Zweifel als Sünde sanktioniert wird oder Ausgrenzung, Zwang oder Gewalt gerechtfertigt werden.","coreRule":"⚡ Sinn und Moral sind nicht das Problem; prüfbare Behauptungen, die Belege abwehren, sind es.","beleg":"Werkstück F.4.2 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Vier Gespräche über Glauben:\\n\\nA: Eine Frau sagt: „Mein Glaube gibt meinem Leben Sinn und der Gemeinde Halt.“\\nB: Ein Mann sagt: „Meine Religion hat feste Schriften, und unsere Gemeinde legt sie verbindlich aus.“\\nC: Eine Gemeinde unterstützt ihre Mitglieder stark und hat dadurch großen Einfluss in ihrer Stadt.\\nD: Ein Vater sagt: „Unser Sohn braucht keine Antibiotika, Beten heilt ihn. Wer daran zweifelt, versündigt sich.“","kurz":"Entscheidend ist, ob eine prüfbare Behauptung gegen Belege geschützt wird. Ob Beten Antibiotika ersetzt, lässt sich klären; wer Zweifel dazu als Sünde brandmarkt, verbietet die Prüfung. Sinn, Halt und Gemeinschaft stellen gar keine solche Behauptung auf.","prueffrage":"Was stünde in jedem der vier Gespräche auf dem Spiel, wenn sich die Beteiligten irren?","rueckmeldung":[{"option":1,"text":"Feste Schriften und verbindliche Auslegung können Nachfragen erschweren, das ist ein berechtigter Gedanke. Für sich genommen schützen sie aber noch keine prüfbare Behauptung gegen Belege und bestrafen keinen Zweifel; das fehlt in Gespräch B."},{"option":2,"text":"Große Reichweite und viel Einfluss wirken schnell bedrohlich. Sie sagen aber nichts darüber, ob etwas gegen Belege abgeschirmt wird; hier unterstützt die Gemeinde zunächst ihre Mitglieder, und Größe allein ist kein Gefahrenzeichen."},{"option":3,"text":"Dass Sinn und Lebensführung sich nicht wissenschaftlich prüfen lassen, stimmt. Genau deshalb steht dort nichts im Konflikt mit Belegen: Es wird keine Tatsache behauptet, über die Daten entscheiden könnten, also auch nichts gegen Belege geschützt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bd8d973a94b8ce5e"}},{"id":"qx-f-061","clusterId":"F","werkstueckRef":"F.4.2","stufe":2,"question":"Welche Entgegnung auf diesen Satz ist am stärksten?","options":["Auch Religionen widersprechen sich in vielen moralischen Fragen; also liefert Religion selbst keinen verlässlichen Maßstab für Moral.","Viele Nichtreligiöse handeln im Alltag sichtbar moralisch; also erübrigt sich die Frage nach einem verlässlichen Maßstab.","Moral ist am Ende Sache des eigenen Gewissens; also braucht es keinen äußeren Maßstab, ob religiös begründet oder nicht.","Ob Religiöse im Alltag moralischer handeln, lässt sich schwer erfassen; begründen lässt sich Moral zudem auch säkular."],"correctIndex":3,"explanation":"Die Behauptung unterstellt zweierlei: dass es ohne Religion an Moral mangelt und dass es ohne sie keinen verlässlichen Maßstab gibt. Ob religiöse oder nichtreligiöse Menschen im Alltag moralischer handeln, lässt sich nur schwer erfassen, weil Selbstauskünfte ihre Grenzen haben; ein Vorsprung einer der beiden Gruppen ist deshalb nicht belegt (eine große Befragung im Alltag, Hofmann u. a. 2014 in Science, fand keinen Unterschied in den selbst berichteten Handlungen). Begründen lässt sich Moral außerdem auch säkular, etwa über Empathie, Vernunft und den Gesellschaftsvertrag, und selbst die Naturrechtstradition des Thomas von Aquin hält Moralgrundsätze für mit der Vernunft erkennbar. Wer eine Behauptung prüfen will, fragt also: Was würde sie im Alltag vorhersagen, und lässt sich das überhaupt zuverlässig feststellen?","coreRule":"⚡ Wer behauptet, etwas sei die Voraussetzung für Moral, muss zeigen, dass es ohne sie weniger Moral gibt.","beleg":"Werkstück F.4.2 (Ethik und funktionierendes Zusammenleben); Fn. gl-f-hofmann (Hofmann u. a. 2014, Science 345, S. 1340--1343); Fn. gl-f-naturrecht Am 14.10.2026 nach Sturms Urteil umgebaut: Die Studie (Hofmann u. a. 2014) steht nur noch in der Erklärung und in den Quellen, nicht mehr als Voraussetzung einer Option; Option 3 abgeschwächt („schwer erfassen“) und richtig, die frühere richtige Option 2 durch eine unpassende ersetzt.","status":"entwurf","scenario":"Im Gespräch über Werte und Erziehung fällt der Satz: „Ohne Religion gibt es keinen verlässlichen Maßstab für Moral.“ Du willst die Behauptung prüfen, statt sie nur zu glauben oder abzulehnen.","kurz":"Der Satz unterstellt zweierlei: dass es ohne Religion an Moral mangelt und dass kein Maßstab bleibt. Ein Handlungsvorsprung einer Gruppe lässt sich kaum belegen, und Moral lässt sich auch säkular begründen, etwa über Empathie und Vernunft.","prueffrage":"Was müsste man im Alltag religiöser und nichtreligiöser Menschen beobachten, wenn die Behauptung stimmt?","rueckmeldung":[{"option":0,"text":"Dass Religionen in moralischen Fragen auseinanderliegen, stimmt. Daraus folgt aber nicht, dass sie keinen Maßstab liefern, und die Behauptung wird so nur gespiegelt. Ob es ohne Religion Moral und einen Maßstab gibt, bleibt unbeantwortet."},{"option":1,"text":"Viele Nichtreligiöse handeln sichtbar moralisch, das trifft zu. Solche Alltagseindrücke sind aber ein schwacher Beleg, denn Unterschiede im Handeln lassen sich schwer erfassen. Und ob ein Maßstab nötig ist, ist damit auch nicht beantwortet."},{"option":2,"text":"Das Gewissen wirkt wie ein bequemer Ausweg aus dem Streit. Es begründet aber nichts: Wer nur auf das eigene Gewissen verweist, liefert gerade keinen verlässlichen Maßstab. Dabei gibt es säkulare Begründungen, die sich prüfen lassen."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Hofmann, W.; Wisneski, D. C.; Brandt, M. J.; Skitka, L. J. (2014): „Morality in everyday life“, Science 345(6202), S. 1340–1343 (Abstract öffentlich, PMID 25214626)","oeffentlich":true,"doi":"10.1126/science.1251560","abruf":"2026-10-12"},{"typ":"url","kurz":"Murphy, M. (2002/2025): „The Natural Law Tradition in Ethics“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/natural-law-ethics/","seite":"Abschnitt 1.2","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ea22ce11e707a9e1"}},{"id":"qx-f-062","clusterId":"F","werkstueckRef":"F.4.2","stufe":4,"question":"In einem Vortrag heißt es: „Im Mittelalter glaubten alle an eine flache Erde, und die Kirche bekämpfte die Wissenschaft von jeher.“ Welche Einschätzung trifft zu?","options":["Die flache Erde ist eine Legende des 19. Jahrhunderts, der „ewige Krieg“ ist übertrieben, echte Einzelkonflikte gab es dennoch.","Beides stimmt im Kern: Die Kirche lehrte die flache Erde und verurteilte deshalb Kopernikus und Galilei als Ketzer.","Die flache Erde ist eine Legende, der Konflikt dagegen trifft zu: Die Kirche stellte sich der Wissenschaft über Jahrhunderte entgegen.","Die flache Erde stimmt im Kern, der „ewige Krieg“ dagegen ist übertrieben: Gestritten wurde nur in Einzelfällen wie um Galilei."],"correctIndex":0,"explanation":"Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist. Die Legende von der flachen Erde stammt aus dem 19. Jahrhundert, als Kirchenkritiker sie als Waffe im angeblichen Krieg zwischen Wissenschaft und Religion nutzten. Dass dieser Krieg „ewig“ gewesen sei, ist ebenfalls überzeichnet. Echte Konflikte gab es trotzdem: 1616 kam das Buch des Kopernikus auf den Index (er selbst war schon 1543 gestorben und wurde nie verurteilt), Galilei wurde 1633 verurteilt, und kreationistische Strömungen in manchen Religionsgemeinschaften bestreiten bis heute die Evolutionslehre. Die Streitfälle betrafen also das Weltbild und die Evolution, nicht die Kugelgestalt der Erde.","coreRule":"⚡ Der Konflikt war real, aber nicht ewig und nicht um die Kugelgestalt der Erde.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage); Fn. gl-f-flacheerde (Garwood 2008; Leisman 2019); Fn. gl-f-konflikt (Numbers 2009, S. 1 und 6)","status":"entwurf","kurz":"Die flache Erde war im Mittelalter kein Gelehrtenwissen, sondern wurde im 19. Jahrhundert als Legende verbreitet. Auch der „ewige Krieg“ ist überzeichnet: Es gab echte Einzelkonflikte, aber keinen Dauerkampf der Kirche gegen die Wissenschaft.","prueffrage":"Was schrieben Gelehrte des Mittelalters selbst über die Gestalt der Erde, und welche Streitfälle zwischen Kirche und Forschung sind mit Anlass und Datum überliefert?","rueckmeldung":[{"option":1,"text":"Dass es echte Konflikte um das Weltbild gab, stimmt. Die Kirche lehrte aber keine flache Erde, und Kopernikus wurde nie verurteilt: Er starb 1543, sein Buch kam erst 1616 auf den Index."},{"option":2,"text":"Daran stimmt: Die flache Erde ist eine Legende. Doch ein jahrhundertelanger Gegensatz ist selbst überzeichnet; belegt sind einzelne Streitfälle wie 1616 und 1633, nicht ein Dauerkampf."},{"option":3,"text":"Daran stimmt: Der „ewige Krieg“ ist übertrieben, und Galilei war ein echter Einzelfall. Die flache Erde stimmt aber nicht, denn Gelehrte des Mittelalters wussten um die Kugelgestalt. Zudem gab es weitere Streitfälle, etwa um die Evolution."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Russell, J. B. (1997): „The Myth of the Flat Earth“, Vortrag, American Scientific Affiliation","oeffentlich":true,"url":"https://www.asa3.org/ASA/topics/history/1997Russell.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (2005/2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","seite":"Abschnitt 2 und 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Numbers, R. L. (Hg.) (2009): Galileo Goes to Jail and Other Myths about Science and Religion. Harvard University Press (Einleitung S. 1, 6; Cormack, Myth 3, S. 28–34)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"f21a096baea0186e"}},{"id":"qx-f-063","clusterId":"F","werkstueckRef":"F.4.3","stufe":1,"question":"Welche Frage prüft diese Behauptung am besten?","options":["Welche realen Ängste ihrer Entstehungszeit bündeln Zombiefilme, und was in Geschichte und Erzählung spricht dafür?","Was sagen die Macher von Zombiefilmen über ihre Absichten, und was in ihren Interviews spricht für eine tiefere Botschaft?","Warum sehen Zuschauer nach eigener Angabe Zombiefilme, und was in Umfragen spricht für bloße Unterhaltung?","Gibt es Zombiefilme ganz ohne Konsum oder Seuchen, und was in ihrer Handlung spricht gegen einen Zusammenhang?"],"correctIndex":0,"explanation":"Die Frage macht die Deutung prüfbar: Welche Ängste und Spannungen ihrer Entstehungszeit bündeln Zombiefilme, und was spricht dafür oder dagegen? Der moderne Zombie lässt sich etwa als Bild für die Angst vor dem Verlust der Individualität lesen, in einer Masse, die nur noch konsumiert oder sich ansteckt. Das ist eine Lesart, kein Nachweis, aber sie nimmt die Zufallsbehauptung ernst und lässt sich an Geschichte und Erzählung überprüfen.","coreRule":"⚡ Zeig mir dein Monster, und ich sage dir, wovor sich deine Zeit fürchtet.","beleg":"Werkstück F.4.3 (Kernidee; Die Autopsie der drei Archetypen; Red Flags)","status":"entwurf","scenario":"Eine Podcast-Hörerin sagt: „Zombiefilme sind doch nur Unterhaltung. Dass sie gerade in Zeiten von Massenkonsum und Pandemien so beliebt sind, ist Zufall.“","kurz":"Die Behauptung wird prüfbar, wenn man fragt, welche Ängste ihrer Entstehungszeit die Filme bündeln und was an Geschichte und Erzählung dafür oder dagegen spricht. Das ergibt eine Lesart, keinen Beweis, aber „Zufall“ wird so ernst genommen und nicht bloß behauptet.","prueffrage":"Gab es auch Jahrzehnte, in denen Zombiefilme beliebt waren, ohne dass Massenkonsum oder Seuchen die Menschen beschäftigten?","rueckmeldung":[{"option":1,"text":"Was Macher über ihre Absichten sagen, ist eine Quelle, aber keine Prüfung der Behauptung. Ein Film kann Ängste der Zeit aufgreifen, ohne dass es beabsichtigt war, und Interviews sagen wenig darüber, was die Filme tatsächlich erzählen."},{"option":2,"text":"Umfragen zeigen, was Zuschauer als Grund angeben. Ob die Filme Ängste ihrer Zeit bündeln, klären sie kaum, denn solche Deutungen sind den Befragten oft nicht bewusst. Außerdem sucht die Frage nur Belege für eine Seite, statt beide Seiten zu prüfen."},{"option":3,"text":"Gegenbeispiele sind ein sinnvolles Prüfmittel, doch einzelne Filme ohne Konsum- oder Seuchenmotiv widerlegen noch keine Deutung des Genres insgesamt. Zudem fragt die Option nur nach Belegen gegen den Zusammenhang statt nach dafür und dagegen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Grupe, D. (2014): „Faszination Zombie“, Schwäbische Zeitung (schwaebische.de), mit Aussagen von Gudrun Rath, Universität Konstanz","oeffentlich":true,"url":"https://www.schwaebische.de/panorama/faszination-zombie-762677","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ackermann, H.-W.; Gauthier, J. (1991): „The Ways and Nature of the Zombi“, Journal of American Folklore 104(414), S. 466–494","oeffentlich":false,"seite":"S. 467, 489"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5637caab00b09be2"}},{"id":"qx-f-064","clusterId":"F","werkstueckRef":"F.4.3","stufe":2,"question":"Ein Vortrag sagt: „Die Vampirlegende zeigt die Angst der Bauern vor dem adeligen Ausbeuter, siehe die Fälle von 1725 und 1732.“ Was ist an dieser Begründung fehlerhaft?","options":["Die Fälle von 1725 und 1732 betrafen Adelige, die ihre Untertanen aussaugten; die Deutung ist daher durch sie gedeckt.","Der Vampir stand in jeder Epoche allein für Seuchen und nie für gesellschaftliche Ausbeutung; die Deutung ist daher grundsätzlich falsch.","Die Fälle von 1725 und 1732 betrafen tote Dorfbewohner; der adelige Vampir ist erst eine spätere literarische Erfindung.","Die Fälle von 1725 und 1732 sind erfunden; aus dieser Zeit gibt es keine Berichte über Vampire oder Wiedergänger."],"correctIndex":2,"explanation":"Die Belege tragen die Deutung nicht: Die Fälle von 1725 (Plogojowitz) und 1732 (Paole) sind durch zeitgenössische amtliche Berichte gut belegt, betrafen aber tote Dorfbewohner, die als Wiedergänger galten, keine Adeligen. Den adeligen Verführer erfand John Polidori erst 1819 mit „The Vampyre“, Bram Stoker gab ihm 1897 seine endgültige Gestalt. Die Deutung als Bild für Ausbeutung passt also auf die Literaturfigur, nicht auf die Fälle, die der Vortrag als Beleg anführt. Seuchenangst und tabuisierte Sexualität sind weitere Hintergründe des Vampirmotivs.","coreRule":"⚡ Prüfe, ob der angeführte Beleg die Deutung wirklich trägt: Die Metapher vom adeligen Parasiten passt zum literarischen Vampir, nicht zu den Fällen des 18. Jahrhunderts.","beleg":"Werkstück F.4.3 („Der Vampir (Der adelige Parasit)“); Fn. gl-f-vampir-adel (Flückinger 1732; Bunson 2000; Bane 2010; Bräunlein 2015; Bohn 2008)","status":"entwurf","kurz":"Die angeführten Fälle betrafen tote Dorfbewohner, keine Adeligen; der adelige Vampir kam erst 1819 in der Literatur auf. Wer eine Deutung durch Fälle belegt, muss prüfen, ob diese Fälle überhaupt zur Deutung passen.","prueffrage":"Wer genau waren die Betroffenen in den Fällen von 1725 und 1732, und was berichten die damaligen Akten über sie?","rueckmeldung":[{"option":0,"text":"Solange man die Fälle nicht nachschlägt, wirkt die Deutung gedeckt. In den Fällen von 1725 und 1732 ging es aber um tote Dorfbewohner, nicht um Adelige, die ihre Untertanen aussaugten."},{"option":1,"text":"Seuchenangst ist tatsächlich ein wichtiger Hintergrund des Vampirmotivs, aber nicht der einzige. Die Ausbeutungsdeutung ist nicht grundsätzlich falsch: Sie passt auf die adelige Literaturfigur, nur nicht auf die angeführten Fälle."},{"option":3,"text":"Zweifel an alten Quellen sind oft berechtigt. Über beide Fälle gibt es aber zeitgenössische amtliche Berichte. Der Fehler der Begründung liegt woanders: Die Betroffenen waren tote Dorfbewohner, keine Adeligen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Bräunlein, P. J. (2015): „Furchterregende Randzonen der Aufklärung: Skandalon Vampirismus“, Zeitschrift für Anomalistik 15, S. 55–87 (Repositorium Univ. Tübingen)","oeffentlich":true,"doi":"10.15496/publikation-39362","seite":"S. 61, 63","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schneider, N. (2024): „Virale Monster: Spuren infektiöser Krankheiten im Vampirismus & die Konstruktion ansteckender Identität“, Thewis 11, S. 92–113","oeffentlich":true,"doi":"10.21248/thewis.11.2024.139","seite":"S. 97, 99","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0f08af5af013157c"}},{"id":"qx-f-065","clusterId":"F","werkstueckRef":"F.4.3","stufe":3,"question":"Eine Schlagzeile behauptet: „Wissenschaftler haben das Rätsel gelöst: Vampire gab es nie, es waren Menschen mit Porphyrie!“ Wie solltest du diese Aussage einordnen?","options":["Als zu starke Behauptung: Eine Krankheit mag zum Mythos beigetragen haben, doch Ähnlichkeit einzelner Symptome beweist nicht, dass Porphyrie ihn vollständig erklärt.","Als glaubwürdig: Die Schlagzeile beruft sich auf Wissenschaftler, und wenn Fachleute ein Rätsel für gelöst erklären, darf man ihnen das bis auf Weiteres glauben.","Als Sensationsmache: Eine Schlagzeile mit Ausrufezeichen soll vor allem Aufmerksamkeit erzeugen, deshalb ist an der Porphyrie-Deutung vermutlich nichts dran.","Als Widerspruch: Wer sagt, Vampire habe es nie gegeben, kann nicht zugleich sagen, es seien Menschen mit Porphyrie gewesen, sodass sich die Aussage selbst aufhebt."],"correctIndex":0,"explanation":"Die Schlagzeile schließt von einer Ähnlichkeit einzelner Symptome auf eine vollständige Erklärung. Das trägt nicht: Die Porphyrie-These ist in der Fachwelt umstritten. Winkler und Anderson bezeichnen sie als eher Gerücht denn als wissenschaftliche Theorie, ihr Urheber Dolphin habe sie nie veröffentlicht. Für Blutdurst bei Porphyriekranken oder eine Linderung durch Bluttrinken gibt es keinen Beleg. Der Vampir des Volksglaubens ging zudem auch bei Tageslicht um, die Lichtscheu kam erst später durch Filme wie „Nosferatu“ (1922) ins Vampirbild. Dasselbe gilt für die Tollwut-These: Auch dort wird Tollwut nur als einer von mehreren möglichen Beiträgen zu Werwolf- und Vampirlegenden verstanden. Eine medizinische Parallele kann ein Echo sein. Ob sie eine Erklärung ist, zeigt erst ein Beleg dafür, dass die Krankheit die Geschichte tatsächlich hervorgebracht hat. Wer Ähnlichkeit mit Ursache gleichsetzt, ersetzt die Prüfung durch eine passende Geschichte.","coreRule":"⚡ Eine Ähnlichkeit ist ein Hinweis, kein Beweis: Medizinische Parallelen liefern ein Echo, nicht automatisch die ganze Erklärung.","beleg":"Werkstück F.4.3 (Das medizinische Echo); Fn. gl-f-11 (Gómez-Alonso 1998; Wasik, Murphy 2012); Fn. gl-f-12 (Winkler, Anderson 1990)","status":"entwurf","scenario":"","kurz":"Die Schlagzeile macht aus der Ähnlichkeit einzelner Symptome eine vollständige Erklärung. Eine Krankheit kann ein Echo im Mythos sein; dass sie ihn hervorgebracht hat, ist damit nicht belegt, und die These ist in der Fachwelt umstritten.","prueffrage":"Welche Merkmale des Vampirs im alten Volksglauben passen zu den Symptomen, und für welche gibt es überhaupt einen Beleg?","rueckmeldung":[{"option":1,"text":"Sich auf Fachleute zu stützen ist oft vernünftig. Das Wort „Wissenschaftler“ ersetzt hier aber keinen Beleg, und die These gilt in der Fachwelt als umstritten und wurde von ihrem Urheber nie veröffentlicht."},{"option":2,"text":"Reißerische Schlagzeilen sind ein Warnsignal, doch der Stil entscheidet nicht über den Inhalt. Die Parallele kann durchaus ein Echo sein; der Fehler liegt darin, aus einer Ähnlichkeit eine vollständige Erklärung zu machen."},{"option":3,"text":"Beides lässt sich vereinbaren: Es gab keine übernatürlichen Vampire, und reale Kranke könnten trotzdem Vorbild gewesen sein. Nicht die Logik der Aussage trägt nicht, sondern der Schluss von Ähnlichkeit auf eine vollständige Erklärung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Cox, A. M. (1995): „Porphyria and vampirism: another myth in the making“, Postgraduate Medical Journal 71(841), S. 643–644 (PMC2398345)","oeffentlich":true,"doi":"10.1136/pgmj.71.841.643-a","seite":"S. 643 f.","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gómez-Alonso, J. (1998): „Rabies: a possible explanation for the vampire legend“, Neurology 51(3), S. 856–859 (Abstract öffentlich)","oeffentlich":true,"doi":"10.1212/wnl.51.3.856"},{"typ":"literatur","kurz":"Winkler, M. G.; Anderson, K. E. (1990): „Vampires, Porphyria, and the Media: Medicalization of a Myth“, Perspectives in Biology and Medicine 33(4), S. 598–611, DOI 10.1353/pbm.1990.0051","oeffentlich":false,"seite":"S. 598, 600, 606"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"41ac07368f5ff1f4"}},{"id":"qx-f-066","clusterId":"F","werkstueckRef":"F.4.3","stufe":4,"question":"Was ist an dieser Sprache problematisch, und woran erkennst du es?","scenario":"Ein Redner nennt eine Minderheit eine „Seuche“ und „Bestien“, vor denen man das Land schützen müsse.","options":["Es liegt Entmenschlichung vor: Die Minderheit wird als „Seuche“ und „Bestien“ zum Monster erklärt und zur Zielscheibe, gegen die Hass und Gewalt gerechtfertigt erscheinen.","Es liegt bloße Übertreibung vor: Der Redner greift zu drastischen Bildern; problematisch ist vor allem der raue Ton, weniger der Inhalt dessen, was er über die Minderheit sagt.","Es liegt Angstmache vor: Der Redner spricht vom Schutz des Landes und weckt damit Furcht; problematisch ist vor allem, dass er sein Publikum über Gefühle statt Gründe anspricht.","Es liegt eine Pauschalisierung vor: Der Redner urteilt über die ganze Minderheit, ohne zwischen einzelnen Menschen zu unterscheiden; erkennbar ist das daran, dass er keinen Beleg nennt."],"correctIndex":0,"explanation":"In Geschichten sind Monster Spiegel von Ängsten: Man projiziert die Furcht in eine erfundene Figur, bekämpft sie und erlebt eine symbolische Entlastung. Dabei trifft die Gewalt niemanden. Hier läuft es umgekehrt: Das Monster-Bild wird auf reale Menschen gelegt. Wer als „Bestie“ oder „Seuche“ gilt, wird entmenschlicht, und gegen eine Seuche darf man alles tun. So lenkt Propaganda reale Ängste auf ein Feindbild, und die Geschichte zeigt, dass entmenschlichende Propaganda Gewalt vorbereiten kann. Beschönigt wird hier nichts, die Wörter sind im Gegenteil drastisch, ein Euphemismus ist es also nicht. Einen Strohmann gibt es nicht, weil der Redner gar keine Position der Minderheit wiedergibt, die er verzerren könnte. Und ein Dammbruchargument fehlt, denn von einem Zugeständnis und einer Kette von Folgeschritten ist nirgends die Rede.","coreRule":"⚡ Monster in der Fiktion sind Spiegel; Monster-Sprache über Menschen ist Entmenschlichung.","beleg":"Werkstück F.4.3 (Anwendung & Relevanz: Im Verständnis von Propaganda; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer als „Seuche“ oder „Bestie“ gilt, ist kein Mensch mehr, und gegen eine Seuche scheint alles erlaubt. Der naheliegende Fehler ist, darin nur einen rauen Ton zu sehen. Hier wird das Monster-Bild auf reale Menschen gelegt und kann Gewalt vorbereiten.","prueffrage":"Was bliebe von der Forderung des Redners übrig, wenn er dieselbe Gruppe in ruhigem Ton und mit Zahlen beschriebe?","rueckmeldung":[{"option":1,"text":"Die Bilder sind drastisch, das stimmt. Entscheidend ist aber nicht die Schärfe des Tons: „Seuche“ und „Bestien“ sprechen der Minderheit das Menschsein ab, und das ist ein inhaltliches Problem, auch bei ruhigem Vortrag."},{"option":2,"text":"Der Schutzgedanke weckt tatsächlich Furcht, und das verdient Aufmerksamkeit. Das Problem liegt aber tiefer: Die Angst wird auf Menschen gelenkt, die zu Monstern erklärt werden. Gefühle anzusprechen ist an sich noch keine Entmenschlichung."},{"option":3,"text":"Der Redner urteilt tatsächlich über eine ganze Gruppe, ohne zu unterscheiden. Doch ein fehlender Beleg zeigt das Kernproblem nicht an: Menschen werden zu „Seuche“ und „Bestien“ erklärt. Das geht über bloße Verallgemeinerung hinaus."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum: „Nazi Propaganda“, Holocaust Encyclopedia","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/nazi-propaganda","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): „Seven Challenges for the Dehumanization Hypothesis“, Perspectives on Psychological Science 16(1), S. 3–13 (PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haslam, N. (2006): „Dehumanization: An Integrative Review“, Personality and Social Psychology Review 10(3), S. 252–264, DOI 10.1207/s15327957pspr1003_4","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bc608b7399f7e462"}}]`);export{t as n,n as t};